window.LC = window.LC || { course: null, alphabet: null, units: [] };
LC.course={"slug":"learnfrench","domain":"learnfrench.zyeemzia.com","title":"Learn French","native":"Le français facile","tagline":"Easy French for English speakers, from your first sound to real conversations.","lang":"French","langNative":"Français","voice":"fr-FR","htmlLang":"fr","cjk":false,"mark":"Fr","greeting":"Bonjour !","greetingMeaning":"Hello!","alphabetTitle":"Sounds & Letters","alphabetShort":"Sounds","alphabetIntro":"The 26 letters, the accents and the sounds that make French sound French. Tap any letter to hear it.","rootsLabel":"Word families","hanzi":false,"wish":{"t":"Félicitations !","mean":"Congratulations!"},"pdf":"Learn-French-Book.pdf","accent":"#2648a8","fontsCss":"family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&family=Figtree:wght@400;500;600;700&family=Reem+Kufi:wght@600;700","targetFont":"\"Fraunces\", Georgia, serif"};
LC.alphabet={"groups":[{"id":"letters","label":"The 26 letters","note":"Same letters as English, French names. Tap to hear each name."},{"id":"accents","label":"Accents & joined letters","note":"Small marks that change the sound or the meaning."},{"id":"sounds","label":"Sound spellings","note":"Letter teams that make one French sound."}],"items":[{"id":"a","ch":"A a","name":"a","say":"a","tr":"ah","group":"letters","sound":"Open your mouth wide and say a short, bright 'ah', as in 'father' but shorter.","example":{"t":"ami","tr":"ah-MEE","mean":"friend"}},{"id":"b","ch":"B b","name":"bé","say":"bé","tr":"bay","group":"letters","sound":"Like English b. Say the name as a clean 'bay' with no 'ee' glide at the end.","example":{"t":"bonjour","tr":"bohn-ZHOOR","mean":"hello"},"tip":"Final b is rare; when it is there, it is usually said: {{club}}."},{"id":"c","ch":"C c","name":"cé","say":"cé","tr":"say","group":"letters","sound":"Hard 'k' before a, o, u and consonants ({{café}}). Soft 's' before e, i, y ({{merci}}).","example":{"t":"café","tr":"kah-FAY","mean":"coffee"},"tip":"C + e or i = 's'. C + a, o, u = 'k'. Same rule as in English 'city' and 'cat'."},{"id":"d","ch":"D d","name":"dé","say":"dé","tr":"day","group":"letters","sound":"Like English d, but touch your tongue tip on the back of your top teeth.","example":{"t":"dimanche","tr":"dee-MAHNSH","mean":"Sunday"},"tip":"A d at the end of a word is usually silent: {{grand}}."},{"id":"e","ch":"E e","name":"e","say":"e","tr":"uh","group":"letters","sound":"Without an accent, e often sounds like a soft 'uh' with rounded lips. At the end of a word it is usually silent.","example":{"t":"petit","tr":"puh-TEE","mean":"small"},"tip":"The letter E is called 'uh', not 'ee'. 'Ee' is the name of I!"},{"id":"f","ch":"F f","name":"effe","say":"effe","tr":"ef","group":"letters","sound":"Like English f. Usually said even at the end of a word.","example":{"t":"fleur","tr":"fluhr","mean":"flower"}},{"id":"g","ch":"G g","name":"gé","say":"gé","tr":"zhay","group":"letters","sound":"Hard 'g' before a, o, u ({{gare}}). Soft 'zh' (the s in 'measure') before e, i, y ({{girafe}}).","example":{"t":"gare","tr":"gahr","mean":"station"},"tip":"The name of G sounds like English 'J' backwards: G = 'zhay', J = 'zhee'."},{"id":"h","ch":"H h","name":"ache","say":"ache","tr":"ahsh","group":"letters","sound":"Always silent. Never breathe out an English 'h' sound.","example":{"t":"homme","tr":"om","mean":"man"},"tip":"Think 'H is for Hush': it never makes a sound."},{"id":"i","ch":"I i","name":"i","say":"i","tr":"ee","group":"letters","sound":"A tight, bright 'ee' with smiling lips, shorter than English 'see'.","example":{"t":"lit","tr":"lee","mean":"bed"}},{"id":"j","ch":"J j","name":"ji","say":"ji","tr":"zhee","group":"letters","sound":"Always 'zh', like the s in 'pleasure'. Never the English 'dj' of 'jam'.","example":{"t":"jour","tr":"zhoor","mean":"day"}},{"id":"k","ch":"K k","name":"ka","say":"ka","tr":"kah","group":"letters","sound":"Like English k, without the puff of air. Found mostly in borrowed words.","example":{"t":"kilo","tr":"kee-LOH","mean":"kilo"}},{"id":"l","ch":"L l","name":"elle","say":"elle","tr":"el","group":"letters","sound":"A light, clear l with the tongue tip behind the top teeth, even at the end of a word.","example":{"t":"lune","tr":"lewn","mean":"moon"}},{"id":"m","ch":"M m","name":"emme","say":"emme","tr":"em","group":"letters","sound":"Like English m. After a vowel and before a consonant it can make the vowel nasal ({{jambon}}).","example":{"t":"maman","tr":"mah-MAHN","mean":"mum"}},{"id":"n","ch":"N n","name":"enne","say":"enne","tr":"en","group":"letters","sound":"Like English n. After a vowel and before a consonant or at the end of a word, it usually makes the vowel nasal and is not said itself.","example":{"t":"nuit","tr":"nwee","mean":"night"}},{"id":"o","ch":"O o","name":"o","say":"o","tr":"oh","group":"letters","sound":"A round, pure 'oh' without the English 'w' glide at the end.","example":{"t":"orange","tr":"oh-RAHNZH","mean":"orange"}},{"id":"p","ch":"P p","name":"pé","say":"pé","tr":"pay","group":"letters","sound":"Like English p, but with no puff of air. Final p is usually silent ({{trop}}).","example":{"t":"pomme","tr":"pom","mean":"apple"}},{"id":"q","ch":"Q q","name":"qu","say":"qu","tr":"kew","group":"letters","sound":"Almost always written {{qu}} and said 'k'. The u is silent.","example":{"t":"quatre","tr":"katr","mean":"four"},"tip":"The name of Q uses the French u sound: round your lips as for 'oo' and say 'ee'."},{"id":"r","ch":"R r","name":"erre","say":"erre","tr":"ehr","group":"letters","sound":"Made at the back of the throat, a soft gargle, like a gentle 'h' with voice. Never rolled with the tongue tip.","example":{"t":"rouge","tr":"roozh","mean":"red"},"tip":"Say 'k', feel where your tongue is, then breathe a soft, buzzing 'h' in that spot."},{"id":"s","ch":"S s","name":"esse","say":"esse","tr":"es","group":"letters","sound":"Usually 's'. Between two vowels it becomes 'z' ({{rose}}). Final s is usually silent.","example":{"t":"soleil","tr":"soh-LEY","mean":"sun"}},{"id":"t","ch":"T t","name":"té","say":"té","tr":"tay","group":"letters","sound":"Like English t with the tongue on the back of the teeth and no puff of air. Final t is usually silent.","example":{"t":"thé","tr":"tay","mean":"tea"},"tip":"{{th}} is just 't'. French has no English 'th' sound."},{"id":"u","ch":"U u","name":"u","say":"u","tr":"ew","group":"letters","sound":"Say 'ee', keep your tongue still, then push your lips into a small round kiss. It is NOT 'oo'.","example":{"t":"une","tr":"ewn","mean":"one, a"},"tip":"In our respellings, 'ew' always means this French u sound."},{"id":"v","ch":"V v","name":"vé","say":"vé","tr":"vay","group":"letters","sound":"Like English v.","example":{"t":"vélo","tr":"vay-LOH","mean":"bike"}},{"id":"w","ch":"W w","name":"double vé","say":"double vé","tr":"doo-bluh VAY","group":"letters","sound":"Usually 'w' in English loanwords ({{wifi}}), sometimes 'v' in older words ({{wagon}}).","example":{"t":"wifi","tr":"wee-FEE","mean":"Wi-Fi"},"tip":"Its name means 'double V', not 'double U'."},{"id":"x","ch":"X x","name":"ixe","say":"ixe","tr":"eeks","group":"letters","sound":"Usually 'ks' ({{taxi}}). Final x is usually silent ({{deux}}).","example":{"t":"taxi","tr":"tak-SEE","mean":"taxi"}},{"id":"y","ch":"Y y","name":"i grec","say":"i grec","tr":"ee GREK","group":"letters","sound":"Like French i ('ee') as a vowel, or like English y before a vowel ({{yaourt}}).","example":{"t":"yaourt","tr":"yah-OORT","mean":"yogurt"},"tip":"Its name means 'Greek i'."},{"id":"z","ch":"Z z","name":"zède","say":"zède","tr":"zed","group":"letters","sound":"Like English z. Final z is usually silent ({{nez}}).","example":{"t":"zéro","tr":"zay-ROH","mean":"zero"}},{"id":"e-acute","ch":"É é","name":"e accent aigu","say":"e accent aigu","tr":"ay","group":"accents","sound":"A crisp 'ay' with smiling lips and no glide: shorter than English 'day'.","example":{"t":"café","tr":"kah-FAY","mean":"coffee"},"tip":"The aigu accent points up to the right, like your voice going up to a bright 'ay'."},{"id":"e-grave","ch":"È è","name":"e accent grave","say":"e accent grave","tr":"eh","group":"accents","sound":"An open 'eh', as in English 'bed'.","example":{"t":"mère","tr":"mehr","mean":"mother"},"tip":"The grave accent slopes down, and the mouth opens wider: 'eh'."},{"id":"e-circ","ch":"Ê ê","name":"e accent circonflexe","say":"e accent circonflexe","tr":"eh","group":"accents","sound":"Same open 'eh' as è. The little hat often marks an old s that disappeared.","example":{"t":"fête","tr":"fet","mean":"party"},"tip":"{{fête}} was once 'feste': think of English 'feast'."},{"id":"e-trema","ch":"Ë ë","name":"e tréma","say":"e tréma","tr":"eh","group":"accents","sound":"The two dots (tréma) tell you to say this vowel separately from the one before it.","example":{"t":"Noël","tr":"noh-EL","mean":"Christmas"}},{"id":"a-grave","ch":"À à","name":"a accent grave","say":"a accent grave","tr":"ah","group":"accents","sound":"Same 'ah' sound as a. The accent only changes the meaning: {{a}} = has, {{à}} = to / at.","example":{"t":"voilà","tr":"vwah-LAH","mean":"there it is"}},{"id":"a-circ","ch":"Â â","name":"a accent circonflexe","say":"a accent circonflexe","tr":"ah","group":"accents","sound":"An 'ah', sometimes a little deeper and longer. Most speakers say it like a plain a.","example":{"t":"gâteau","tr":"gah-TOH","mean":"cake"}},{"id":"c-cedilla","ch":"Ç ç","name":"c cédille","say":"c cédille","tr":"s","group":"accents","sound":"The little tail makes c soft: always 's'. Only used before a, o, u.","example":{"t":"garçon","tr":"gar-SOHN","mean":"boy"},"tip":"The cedilla is a tiny tail that says 'hiss!'"},{"id":"i-circ","ch":"Î î","name":"i accent circonflexe","say":"i accent circonflexe","tr":"ee","group":"accents","sound":"Same 'ee' as i. The hat is a spelling memory, not a new sound.","example":{"t":"île","tr":"eel","mean":"island"},"tip":"{{île}} was once 'isle', like English 'isle'."},{"id":"i-trema","ch":"Ï ï","name":"i tréma","say":"i tréma","tr":"ee","group":"accents","sound":"Say this i separately from the vowel before it.","example":{"t":"maïs","tr":"mah-EES","mean":"corn"},"tip":"Without the dots, {{mais}} would be 'meh' (= but)."},{"id":"o-circ","ch":"Ô ô","name":"o accent circonflexe","say":"o accent circonflexe","tr":"oh","group":"accents","sound":"A closed, round 'oh'.","example":{"t":"hôtel","tr":"oh-TEL","mean":"hotel"},"tip":"{{hôtel}} was once 'hostel'."},{"id":"u-circ","ch":"Û û","name":"u accent circonflexe","say":"u accent circonflexe","tr":"ew","group":"accents","sound":"Same French u sound as u ('ee' with round lips).","example":{"t":"sûr","tr":"sewr","mean":"sure"},"tip":"{{sur}} = on, {{sûr}} = sure. Same sound, different meaning."},{"id":"u-grave","ch":"Ù ù","name":"u accent grave","say":"u accent grave","tr":"oo","group":"accents","sound":"Used in just one word, {{où}} (where). There it is part of the 'oo' sound of ou.","example":{"t":"où","tr":"oo","mean":"where"},"tip":"{{ou}} = or, {{où}} = where: the accent 'points' to a place."},{"id":"u-trema","ch":"Ü ü","name":"u tréma","say":"u tréma","tr":"ew","group":"accents","sound":"Very rare. It tells you to say the u separately.","example":{"t":"capharnaüm","tr":"kah-far-nah-OM","mean":"a messy junk room"}},{"id":"y-trema","ch":"Ÿ ÿ","name":"y tréma","say":"y tréma","tr":"ee","group":"accents","sound":"Extremely rare: mostly in a few place names and family names.","example":{"t":"L'Haÿ-les-Roses","tr":"lah-ee lay ROHZ","mean":"a town near Paris"}},{"id":"oe","ch":"Œ œ","name":"e dans l'o","say":"e dans l'o","tr":"uh","group":"accents","sound":"O and e joined together. Usually an 'uh' with round lips, as in {{cœur}}.","example":{"t":"cœur","tr":"kuhr","mean":"heart"},"tip":"Its French name means 'e in the o'."},{"id":"ae","ch":"Æ æ","name":"e dans l'a","say":"e dans l'a","tr":"ay","group":"accents","sound":"A and e joined. Found in a few Latin words, said 'ay'.","example":{"t":"et cætera","tr":"et say-tay-RAH","mean":"and so on"},"tip":"Its French name means 'e in the a'."},{"id":"ou","ch":"ou","name":"ou","say":"ou","tr":"oo","group":"sounds","sound":"A deep, round 'oo' as in 'food', with lips pushed forward.","example":{"t":"nous","tr":"noo","mean":"we"},"tip":"If you see ou, think 'oo'. If you see u alone, it is the French u."},{"id":"oi","ch":"oi","name":"oi","say":"moi","tr":"wah","group":"sounds","sound":"Always 'wah', never 'oy'.","example":{"t":"trois","tr":"trwah","mean":"three"},"tip":"{{moi}} rhymes with 'wah': the famous 'moi' of cartoons."},{"id":"eau","ch":"eau · au","name":"eau, au","say":"eau","tr":"oh","group":"sounds","sound":"Both spellings simply say 'oh'.","example":{"t":"beau","tr":"boh","mean":"beautiful"},"tip":"Three letters, one sound: e-a-u = 'oh'. And {{eau}} itself means water."},{"id":"ai","ch":"ai · ei","name":"ai, ei","say":"mai","tr":"eh","group":"sounds","sound":"An open 'eh' as in 'bed'.","example":{"t":"lait","tr":"leh","mean":"milk"}},{"id":"eu","ch":"eu · œu","name":"eu, œu","say":"eux","tr":"uh","group":"sounds","sound":"Round your lips as for 'oh', then say 'uh'. Like the 'u' in 'fur' without any r.","example":{"t":"deux","tr":"duh","mean":"two"}},{"id":"er-ez","ch":"-er · -ez","name":"-er, -ez","say":"parler","tr":"ay","group":"sounds","sound":"At the end of a word, -er and -ez usually say 'ay', like é.","example":{"t":"parler","tr":"par-LAY","mean":"to speak"},"tip":"{{-er}}, {{-ez}}, {{-é}}: three ways to write 'ay'."},{"id":"an-en","ch":"an · en","name":"an, en, am, em","say":"an","tr":"ahn","group":"sounds","sound":"A nasal 'ah': open wide and let air go through your nose. Do not say the n.","example":{"t":"enfant","tr":"ahn-FAHN","mean":"child"},"tip":"Our respelling 'ahn' means: nasal 'ah', no real n."},{"id":"in","ch":"in · ain","name":"in, im, ain, ein","say":"vin","tr":"an","group":"sounds","sound":"A nasal 'eh/a', a bit like 'an' in 'bang' without the ng.","example":{"t":"pain","tr":"pan","mean":"bread"}},{"id":"on","ch":"on · om","name":"on, om","say":"on","tr":"ohn","group":"sounds","sound":"A nasal 'oh' with very round lips. Do not say the n.","example":{"t":"bonbon","tr":"bohn-BOHN","mean":"sweet, candy"}},{"id":"un","ch":"un · um","name":"un, um","say":"un","tr":"uhn","group":"sounds","sound":"A nasal 'uh'. Many French speakers say it just like in.","example":{"t":"lundi","tr":"luhn-DEE","mean":"Monday"}},{"id":"gn","ch":"gn","name":"gn","say":"agneau","tr":"ny","group":"sounds","sound":"Like the 'ny' in 'canyon' or the 'ni' in 'onion'.","example":{"t":"montagne","tr":"mohn-TAHNY","mean":"mountain"}},{"id":"ch","ch":"ch","name":"ch","say":"chat","tr":"sh","group":"sounds","sound":"Always 'sh' as in 'shop', never the 'tch' of 'church'.","example":{"t":"chat","tr":"shah","mean":"cat"},"tip":"French chefs make {{chocolat}}: 'shoh-koh-LAH'."},{"id":"qu","ch":"qu","name":"qu","say":"qui","tr":"k","group":"sounds","sound":"Just 'k'. The u is silent, so no 'kw' sound.","example":{"t":"qui","tr":"kee","mean":"who"}},{"id":"ph","ch":"ph","name":"ph","say":"photo","tr":"f","group":"sounds","sound":"Like f, just as in English.","example":{"t":"photo","tr":"foh-TOH","mean":"photo"}},{"id":"tion","ch":"-tion","name":"-tion","say":"nation","tr":"syohn","group":"sounds","sound":"At the end of a word, -tion says 'syohn': the t sounds like s.","example":{"t":"nation","tr":"nah-SYOHN","mean":"nation"},"tip":"Many English -tion words exist in French: just change the ending sound."},{"id":"ill","ch":"ill","name":"ill, -il","say":"fille","tr":"y","group":"sounds","sound":"After a vowel, ill (and often -il at the end) sounds like English y.","example":{"t":"fille","tr":"FEE-y","mean":"girl, daughter"},"tip":"Exceptions to know: {{ville}} (veel), {{mille}} (meel)."},{"id":"ui","ch":"ui","name":"ui","say":"huit","tr":"wee","group":"sounds","sound":"A quick French u gliding into 'ee', close to 'wee'.","example":{"t":"nuit","tr":"nwee","mean":"night"}}]};
LC.units.push({"id":"sounds","order":1,"icon":"Aa","color":"teal","title":"Sounds & Letters","subtitle":"Hear, say and read French with confidence","lessons":[{"id":"u1-how-french-sounds","icon":"♪","title":"How French Sounds","subtitle":"Rhythm, stress and pure vowels","minutes":10,"goals":["Hear the smooth, even rhythm of French","Put the stress at the end of a word group","Read our easy respellings"],"blocks":[{"type":"text","text":"Bienvenue! Welcome! Before learning words, let's tune your ears. French sounds smooth and flowing, like a gentle stream. Once you hear its rhythm, everything else gets easier."},{"type":"steps","items":[{"title":"Even beats","desc":"Give every syllable about the same time: {{ca-fé}}, {{cho-co-lat}}. No syllable is swallowed."},{"title":"Lean on the end","desc":"The last syllable of a word or a word group is a little longer. That's the French 'stress'."},{"title":"Pure vowels","desc":"Keep each vowel clean and steady. {{café}} ends on a crisp 'ay', not 'ay-ee'."},{"title":"Busy lips","desc":"French lips work hard: they smile for 'ee', round tightly for 'oo' and 'ew'."}],"title":"Four golden rules"},{"type":"compare","items":[{"t":"chocolat","label":"French: shoh-koh-LAH","desc":"Three even beats, the last one a little longer."},{"t":"chocolate","label":"English: CHOK-lit","desc":"Strong first beat, the middle disappears."}],"title":"Same word, different music"},{"type":"examples","items":[{"t":"hôtel","tr":"oh-TEL","mean":"hotel"},{"t":"animal","tr":"ah-nee-MAHL","mean":"animal"},{"t":"important","tr":"an-por-TAHN","mean":"important"},{"t":"restaurant","tr":"res-toh-RAHN","mean":"restaurant"},{"t":"Paris","tr":"pah-REE","mean":"Paris"},{"t":"téléphone","tr":"tay-lay-FON","mean":"telephone"}],"title":"Words you already know"},{"type":"text","text":"In a sentence, French stresses only the **end of each word group**, not every word. Listen to how this flows as one long word:"},{"type":"examples","items":[{"t":"Bonjour, je m'appelle Léa.","tr":"bohn-ZHOOR, zhuh mah-pel lay-AH","mean":"Hello, my name is Léa.","note":"Two groups, two stresses: ZHOOR and AH."},{"t":"Un café, s'il vous plaît.","tr":"uhn kah-FAY, seel voo PLEH","mean":"A coffee, please."}]},{"type":"table","head":["Respelling","Means","Example"],"rows":[["CAPITALS","the stressed (slightly longer) syllable","{{merci}} = mehr-SEE"],["ew","French u: say 'ee' with round lips","{{tu}} = tew"],["uh","soft 'uh' with rounded lips","{{le}} = luh"],["zh","the s in 'measure'","{{jour}} = zhoor"],["ahn, ohn, an, uhn","nasal vowels: the n is NOT said","{{bon}} = bohn"],["r","French r, made in the throat","{{rouge}} = roozh"]],"title":"How to read our respellings"},{"type":"tip","kind":"memory","text":"Imagine French as a wave that rises and lands at the end of each group: je voudrais un ca-FÉ. Ride the wave, land on the last beat!"},{"type":"tip","kind":"fun","text":"French is spoken on five continents, by more than 300 million people, from Paris to Montréal, Dakar and Tahiti."},{"type":"practice","text":"Tap each word, listen, then say it with even beats and a longer last syllable.","lines":["merci","bonjour","chocolat","important","un café","s'il vous plaît"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Where does French usually put the stress?","options":["On the last syllable of a word group","On the first syllable of every word","On the longest word","On every second syllable"],"answer":0},{"q":"How should you say the vowel at the end of {{café}}?","options":["'ay' sliding into 'ee'","A clean, steady 'ay'","A long 'ee'","Silent"],"answer":1},{"q":"Which respelling fits {{chocolat}}?","options":["CHOK-lit","shoh-koh-LAH","SHOH-koh-lah","choh-KOH-lat"],"answer":1},{"q":"In our respellings, what does 'ohn' mean?","options":["'oh' then a clear n","A long 'oo'","'own' as in English","A nasal 'oh', with no real n"],"answer":3},{"q":"Listen. Which phrase do you hear?","say":"s'il vous plaît","options":["merci beaucoup","bonjour madame","s'il vous plaît","à bientôt"],"answer":2},{"q":"In {{Bonjour, je m'appelle Léa}}, which syllables carry the stress?","options":["-jour and -a","bon- and je","je and -pelle","Every syllable equally"],"answer":0}]}]},{"id":"u1-alphabet","icon":"A","title":"The French Alphabet","subtitle":"26 familiar letters with French names","minutes":12,"goals":["Say the names of the 26 letters","Avoid the classic E/I and G/J traps","Spell a word aloud in French"],"blocks":[{"type":"text","text":"Good news: French uses the same 26 letters as English. Only the names are different. Tap each letter to hear its French name."},{"type":"letters","items":["a","b","c","d","e","f","g","h","i","j","k","l","m","n","o","p","q","r","s","t","u","v","w","x","y","z"],"title":"A to Z"},{"type":"table","head":["Letter","French name","Sounds like"],"rows":[["E","{{e}}","uh"],["I","{{i}}","ee"],["G","{{gé}}","zhay"],["J","{{ji}}","zhee"],["H","{{ache}}","ahsh"],["R","{{erre}}","ehr"],["U","{{u}}","ew"],["W","{{double vé}}","doo-bluh VAY"],["Y","{{i grec}}","ee GREK"]],"title":"The tricky ones"},{"type":"compare","items":[{"t":"e","label":"E = 'uh'","desc":"Soft, round lips. Not 'ee'!"},{"t":"i","label":"I = 'ee'","desc":"Smiling lips. This is the English 'E' sound."}],"title":"E and I swap"},{"type":"compare","items":[{"t":"g","label":"G = 'zhay'","desc":"Rhymes with 'day'."},{"t":"j","label":"J = 'zhee'","desc":"Rhymes with 'see'."}],"title":"G and J swap"},{"type":"tip","kind":"memory","text":"English speakers swap these pairs. Remember: **G**ay → 'zhay' (G rhymes with dAY), **J**ee → 'zhee'. And the French E is the shy 'uh', while I is the happy 'ee'."},{"type":"text","text":"Most letter names follow a pattern: vowel-like letters ending in 'ay' ({{bé, cé, dé, gé, pé, té, vé}}) and letters starting with 'e' ({{effe, elle, emme, enne, erre, esse}})."},{"type":"text","text":"People often ask {{Ça s'écrit comment ?}} (How is that spelled?). Then you spell letter by letter:","title":"Spelling aloud"},{"type":"examples","items":[{"t":"Léa : L, E accent aigu, A","tr":"el, uh ak-SAHN tay-GEW, ah","mean":"Léa: L, É, A"},{"t":"Paris : P, A, R, I, S","tr":"pay, ah, ehr, ee, es","mean":"Paris"},{"t":"deux L","tr":"duh el","mean":"double L (as in 'elle')"}]},{"type":"tip","kind":"tip","text":"For double letters, French says {{deux}} (two): {{deux L}}, {{deux S}}, {{deux M}}."},{"type":"practice","text":"Spell these words aloud, letter by letter, using the French names.","lines":["ami","chat","jour","girafe","Québec","wifi"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"What is the French name of the letter I?","options":["eye","uh","ee","ay"],"answer":2},{"q":"Listen. Which letter is this?","say":"gé","options":["G","J","E","Z"],"answer":0},{"q":"Listen. Which letter is this?","say":"ji","options":["G","I","Y","J"],"answer":3},{"q":"What does the letter H sound like in a French word?","options":["A breathy 'h'","Nothing: it is silent","Like 'sh'","Like a French r"],"answer":1},{"q":"How do you say 'double S' when spelling?","options":["deux S","double esse","S S","deux double S"],"answer":0},{"q":"The French name of Y means…","options":["Double i","Long u","Greek i","Why"],"answer":2},{"q":"Listen. Which letter is this?","say":"e","options":["I","E","A","U"],"answer":1}]}]},{"id":"u1-vowels-accents","icon":"é","title":"Vowels & Accents","subtitle":"Small marks with big jobs","minutes":12,"goals":["Say the pure French vowels","Tell é from è and ê","Know what ç and the tréma do"],"blocks":[{"type":"text","text":"French vowels are short, pure and steady. Accents are little helpers: some change the sound, some only change the meaning. Let's meet them."},{"type":"examples","items":[{"t":"a","tr":"ah","mean":"as in {{papa}}"},{"t":"é","tr":"ay","mean":"as in {{été}} (summer)"},{"t":"è","tr":"eh","mean":"as in {{mère}} (mother)"},{"t":"i","tr":"ee","mean":"as in {{midi}} (noon)"},{"t":"o","tr":"oh","mean":"as in {{vélo}} (bike)"},{"t":"u","tr":"ew","mean":"as in {{tu}} (you)"}],"title":"Six key vowels"},{"type":"letters","items":["e-acute","e-grave","e-circ","e-trema","a-grave","a-circ","c-cedilla","i-circ","i-trema","o-circ","u-circ","u-grave","oe"],"title":"The accents"},{"type":"table","head":["Mark","Name","What it does"],"rows":[["{{é}}","accent aigu","only on e: says 'ay'"],["{{è à ù}}","accent grave","on e: says 'eh'; on a and u: changes the meaning only"],["{{ê â î ô û}}","accent circonflexe","on e: says 'eh'; often marks a lost s"],["{{ë ï}}","tréma","say this vowel separately"],["{{ç}}","cédille","makes c say 's' before a, o, u"]]},{"type":"compare","items":[{"t":"é","label":"'ay' (closed)","desc":"Smile, mouth almost closed: {{été}}, {{café}}."},{"t":"è","label":"'eh' (open)","desc":"Drop your jaw a little: {{mère}}, {{très}}."},{"t":"ê","label":"'eh' (open)","desc":"Same as è: {{fête}}, {{forêt}}."}],"title":"é vs è / ê"},{"type":"tip","kind":"memory","text":"Draw it in the air! The aigu accent (´) climbs up: your voice is high and tight, 'ay'. The grave accent (`) slides down: your jaw drops, 'eh'. The circonflexe (^) is a little hat that hides a lost s: {{forêt}} = forest, {{hôpital}} = hospital."},{"type":"rule","name":"Accents can change meaning","color":"purple","desc":"Some words sound the same but the accent tells them apart.","examples":[{"t":"a / à","tr":"ah","hl":"à"},{"t":"ou / où","tr":"oo","hl":"où"},{"t":"la / là","tr":"lah","hl":"là"},{"t":"sur / sûr","tr":"sewr","hl":"sûr"}],"how":"{{a}} = has, {{à}} = to. {{ou}} = or, {{où}} = where. {{la}} = the, {{là}} = there. {{sur}} = on, {{sûr}} = sure."},{"type":"rule","name":"The cédille","color":"green","desc":"C before a, o, u is hard 'k'. Add a tail (ç) to make it a soft 's'.","examples":[{"t":"ça","tr":"sah","hl":"ç"},{"t":"garçon","tr":"gar-SOHN","hl":"ç"},{"t":"reçu","tr":"ruh-SEW","hl":"ç"}]},{"type":"rule","name":"The tréma","color":"orange","desc":"Two dots say: pronounce me on my own.","examples":[{"t":"Noël","tr":"noh-EL","hl":"ë"},{"t":"maïs","tr":"mah-EES","hl":"ï"}],"how":"Compare {{mais}} ('meh', but) with {{maïs}} ('mah-EES', corn)."},{"type":"practice","text":"Read each word. Watch the accent and adjust your mouth.","lines":["été","mère","fête","très","voilà","ça","Noël","hôtel"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Which accent makes e say 'ay'?","options":["é (aigu)","è (grave)","ê (circonflexe)","ë (tréma)"],"answer":0},{"q":"Listen. Which word do you hear?","say":"mère","options":["mari","mère","marée","mûre"],"answer":1,"explain":"{{mère}} (mother) has an open 'eh'."},{"q":"What does the cédille in {{garçon}} do?","options":["Makes c say 's'","Makes c say 'k'","Makes c silent","Makes the o nasal"],"answer":0},{"q":"{{où}} means…","options":["or","yes","where","who"],"answer":2},{"q":"Why does {{maïs}} have two dots on the i?","options":["The i is silent","The i is long","It is a plural","Say a and i separately"],"answer":3},{"q":"The circumflex in {{forêt}} often reminds us of…","options":["a silent t","a lost letter s","a long 'ee'","a capital letter"],"answer":1,"explain":"{{forêt}} = forest."},{"q":"Listen. Which word do you hear?","say":"été","options":["été","étape","tête","thé"],"answer":0}]}]},{"id":"u1-silent-letters","icon":"s̶","title":"Silent Final Letters","subtitle":"Many last letters stay quiet","minutes":10,"goals":["Know which final letters are usually silent","Use the CaReFuL trick","Hear the change in petit / petite"],"blocks":[{"type":"text","text":"French spelling keeps letters that people stopped saying centuries ago. Relax: there are clear patterns, and you'll soon read them without thinking."},{"type":"rule","name":"Final consonants are usually silent","color":"gray","desc":"Most consonants at the very end of a word are not said.","examples":[{"t":"petit","tr":"puh-TEE","hl":"t"},{"t":"grand","tr":"grahn","hl":"d"},{"t":"Paris","tr":"pah-REE","hl":"s"},{"t":"beaucoup","tr":"boh-KOO","hl":"p"},{"t":"deux","tr":"duh","hl":"x"},{"t":"nez","tr":"nay","hl":"z"}]},{"type":"rule","name":"Final e is usually silent","color":"gray","desc":"An e at the end of a word is not said, but it makes the consonant before it heard.","examples":[{"t":"petite","tr":"puh-TEET","hl":"e"},{"t":"grande","tr":"grahnd","hl":"e"},{"t":"rose","tr":"rohz","hl":"e"}]},{"type":"compare","items":[{"t":"petit","label":"puh-TEE","desc":"Final t silent: small (masculine)."},{"t":"petite","label":"puh-TEET","desc":"Final e silent, but now you hear the t: small (feminine)."}],"title":"One letter, a new sound"},{"type":"rule","name":"CaReFuL letters are often said","color":"green","desc":"Final C, R, F and L are usually pronounced.","examples":[{"t":"avec","tr":"ah-VEK","hl":"c"},{"t":"bonjour","tr":"bohn-ZHOOR","hl":"r"},{"t":"neuf","tr":"nuhf","hl":"f"},{"t":"avril","tr":"ah-VREEL","hl":"l"}],"how":"Big exception: verbs ending in -er ({{parler}}, {{manger}}) say 'ay', with a silent r."},{"type":"tip","kind":"memory","text":"Be CaReFuL! The consonants in C-a-R-e-F-u-L (c, r, f, l) are the ones French usually says at the end of a word."},{"type":"rule","name":"Plural -s and verb -ent are silent","color":"gray","desc":"Plural s/x and the verb ending -ent make no sound.","examples":[{"t":"les chats","tr":"lay SHAH","hl":"s"},{"t":"ils parlent","tr":"eel PARL","hl":"ent"},{"t":"des gâteaux","tr":"day gah-TOH","hl":"x"}],"how":"So {{il parle}} and {{ils parlent}} sound exactly the same."},{"type":"tip","kind":"warn","text":"One-syllable little words keep their e as a soft 'uh': {{le}}, {{de}}, {{je}}, {{me}}, {{que}}."},{"type":"examples","items":[{"t":"le chocolat chaud","tr":"luh shoh-koh-lah SHOH","mean":"hot chocolate"},{"t":"un grand lit","tr":"uhn grahn LEE","mean":"a big bed"},{"t":"trois petits chats","tr":"trwah puh-tee SHAH","mean":"three little cats"}],"title":"Spot the silent letters"},{"type":"practice","text":"Read aloud. Cover the last letter with your finger if it helps!","lines":["petit","petite","Paris","avec","parler","les chats","ils parlent","beaucoup"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"How do you say {{petit}}?","options":["puh-TEE","puh-TEET","PET-it","puh-TEES"],"answer":0},{"q":"Which final letters does the CaReFuL trick say are usually pronounced?","options":["s, t, d, x","a, e, i, o","c, r, f, l","p, t, k, s"],"answer":2},{"q":"In {{parler}}, the final r is…","options":["a strong French r","silent: the ending says 'ay'","said like English r","doubled"],"answer":1},{"q":"Listen. Which word do you hear?","say":"petite","options":["petit","petite","petits","peut-être"],"answer":1},{"q":"{{il parle}} and {{ils parlent}}…","options":["sound different","have a nasal ending","end in a 't' sound","sound the same"],"answer":3},{"q":"Which word ends with a pronounced consonant?","options":["avec","grand","trois","beaucoup"],"answer":0}]}]},{"id":"u1-nasal-vowels","icon":"on","title":"Nasal Vowels","subtitle":"The famous French hum","minutes":12,"goals":["Make the four nasal vowels","Spot when a vowel goes nasal","Hear vent, vont and vin"],"blocks":[{"type":"text","text":"Nasal vowels are the 'hum' that makes French sound French. The secret: let air flow through your nose and your mouth at the same time, and do NOT say the n."},{"type":"steps","items":[{"title":"Hold your nose","desc":"Say 'ah'. It sounds normal: that's an oral vowel."},{"title":"Let go and hum","desc":"Now say 'ah' while letting some air out of your nose. Your tongue stays down."},{"title":"Stop before the n","desc":"Never touch the roof of your mouth with your tongue. {{an}} = 'ahn' with no real n."}],"title":"Make a nasal vowel"},{"type":"table","head":["Sound","Spellings","Example"],"rows":[["ahn","{{an}}, {{en}}, {{am}}, {{em}}","{{enfant}} (child)"],["ohn","{{on}}, {{om}}","{{bonbon}} (sweet)"],["an","{{in}}, {{im}}, {{ain}}, {{ein}}","{{pain}} (bread)"],["uhn","{{un}}, {{um}}","{{lundi}} (Monday)"]],"title":"The four nasals"},{"type":"letters","items":["an-en","on","in","un"]},{"type":"compare","items":[{"t":"vent","label":"ahn: vahn","desc":"wind: mouth open wide."},{"t":"vont","label":"ohn: vohn","desc":"(they) go: lips very round."},{"t":"vin","label":"an: van","desc":"wine: lips spread, smile."}],"title":"Three words, three nasals"},{"type":"tip","kind":"memory","text":"One sentence holds all the nasals: {{un bon vin blanc}} (a good white wine) = uhn bohn van BLAHN. Say it like a little song!"},{"type":"rule","name":"When is it NOT nasal?","color":"red","desc":"If the n or m is followed by a vowel, or doubled, the vowel is normal and you DO say the n.","examples":[{"t":"bon / bonne","tr":"bohn / bon","hl":"nne"},{"t":"un / une","tr":"uhn / ewn","hl":"ne"},{"t":"fin / fine","tr":"fan / feen","hl":"ne"}]},{"type":"compare","items":[{"t":"américain","label":"ah-may-ree-KAN","desc":"Nasal ending: American (man)."},{"t":"américaine","label":"ah-may-ree-KEN","desc":"n followed by e: no nasal (woman)."}]},{"type":"tip","kind":"tip","text":"M before b or p works the same way: {{jambon}} (ham), {{temps}} (time), {{simple}}."},{"type":"examples","items":[{"t":"maman","tr":"mah-MAHN","mean":"mum"},{"t":"jambon","tr":"zhahn-BOHN","mean":"ham"},{"t":"le temps","tr":"luh TAHN","mean":"time, weather"},{"t":"important","tr":"an-por-TAHN","mean":"important"},{"t":"un parfum","tr":"uhn par-FUHN","mean":"a perfume"}]},{"type":"practice","text":"Hum the nasal vowels. Never touch your tongue to the roof of your mouth.","lines":["an","on","vin","un","vent, vont, vin","un bon vin blanc","bon, bonne","une maman"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"To make a nasal vowel, you…","options":["say a strong n at the end","let air out through the nose and skip the n","close your lips","add a 'g' sound"],"answer":1},{"q":"Listen. Which word do you hear?","say":"vin","options":["vin","vent","vont","vingt-deux"],"answer":0},{"q":"Listen. Which word do you hear?","say":"vont","options":["vin","vent","vont","vous"],"answer":2},{"q":"Which word has NO nasal vowel?","options":["bon","pont","nom","bonne"],"answer":3},{"q":"Which spelling does NOT usually make the 'ahn' sound?","options":["in","an","en","em"],"answer":0},{"q":"How many nasal vowels are in {{un bon vin blanc}}?","options":["Two","Four","None","One"],"answer":1},{"q":"Why is the e in {{une}} needed for the sound?","options":["It makes a nasal 'uhn'","It is said 'ay'","It stops the nasal, so you hear 'n'","It makes the u silent"],"answer":2}]}]},{"id":"u1-r-and-u","icon":"r","title":"The French R, U and OU","subtitle":"Two sounds English doesn't have","minutes":12,"goals":["Make a soft throat r","Say the French u","Hear tu vs tout"],"blocks":[{"type":"text","text":"Two sounds give English speakers the most fun: the French r and the French u. With a few tricks and a little practice, you'll have both."},{"type":"steps","items":[{"title":"Find the spot","desc":"Say 'k' or 'g'. Feel the back of your tongue touch the back of your mouth."},{"title":"Breathe there","desc":"Leave a tiny gap at that same spot and breathe out a soft, buzzing 'h'."},{"title":"Keep the tip down","desc":"Your tongue tip rests behind your bottom teeth. No rolling, no curling."}],"title":"The French r in 3 steps"},{"type":"tip","kind":"memory","text":"Think of a light gargle, or a cat's soft purr. Too strong? Make it gentler. French people say it softly."},{"type":"examples","items":[{"t":"rouge","tr":"roozh","mean":"red"},{"t":"Paris","tr":"pah-REE","mean":"Paris"},{"t":"merci","tr":"mehr-SEE","mean":"thank you"},{"t":"très","tr":"treh","mean":"very"},{"t":"frère","tr":"frehr","mean":"brother"}],"title":"Practise the r"},{"type":"steps","items":[{"title":"Smile","desc":"Say a long 'ee'."},{"title":"Freeze","desc":"Keep your tongue exactly where it is."},{"title":"Kiss","desc":"Push your lips into a small round circle. Out comes the French u: 'ew'."}],"title":"The French u in 3 steps"},{"type":"compare","items":[{"t":"tu","label":"u = 'ew'","desc":"you: tongue forward, lips round."},{"t":"tout","label":"ou = 'oo'","desc":"all: tongue back, like English 'too'."}],"title":"u vs ou"},{"type":"compare","items":[{"t":"rue","label":"rew","desc":"street"},{"t":"roue","label":"roo","desc":"wheel"}]},{"type":"compare","items":[{"t":"dessus","label":"duh-SEW","desc":"on top"},{"t":"dessous","label":"duh-SOO","desc":"underneath"}]},{"type":"tip","kind":"warn","text":"Mixing u and ou can change the meaning. {{Tu}} is 'you', {{tout}} is 'all'. {{Vu}} is 'seen', {{vous}} is 'you'."},{"type":"examples","items":[{"t":"une rue","tr":"ewn REW","mean":"a street"},{"t":"la lune","tr":"lah LEWN","mean":"the moon"},{"t":"tu as vu ?","tr":"tew ah VEW","mean":"did you see?"},{"t":"nous trouvons","tr":"noo troo-VOHN","mean":"we find"}]},{"type":"practice","text":"Slowly, then faster. Feel your lips move.","lines":["tu, tout","rue, roue","vu, vous","dessus, dessous","une rue rouge","Tu trouves tout ?"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Where is the French r made?","options":["With the tongue tip rolled","With curled tongue, like English","At the back of the mouth, near the throat","With the lips"],"answer":2},{"q":"To make the French u, you…","options":["say 'ee' and round your lips","say 'oo' with a smile","say 'uh' with your mouth open","say 'you' quickly"],"answer":0},{"q":"Listen. Which word do you hear?","say":"tu","options":["tout","tu","toi","thé"],"answer":1},{"q":"Listen. Which word do you hear?","say":"roue","options":["rue","rêve","rude","roue"],"answer":3},{"q":"{{dessous}} means…","options":["underneath","on top","inside","behind"],"answer":0},{"q":"Which word has the French u sound ('ew')?","options":["loup","nous","lune","rouge"],"answer":2},{"q":"Listen. Which word do you hear?","say":"vous","options":["vu","vous","veut","vos"],"answer":1}]}]},{"id":"u1-sound-spellings","icon":"eau","title":"Sound Spellings","subtitle":"Letter teams that make one sound","minutes":14,"goals":["Read the most common letter teams","Know soft and hard c and g","Read new words with confidence"],"blocks":[{"type":"text","text":"French often uses two or three letters for one sound. Learn these teams once, and you can read almost any French word aloud, even ones you've never seen."},{"type":"letters","items":["ou","oi","eau","ai","eu","er-ez","gn","ch","qu","ph","tion","ill","ui"],"title":"The teams"},{"type":"table","head":["Sound","Spellings","Examples"],"rows":[["oh","{{o}}, {{au}}, {{eau}}","{{vélo}}, {{chaud}}, {{beau}}"],["eh","{{è}}, {{ê}}, {{ai}}, {{ei}}","{{mère}}, {{fête}}, {{lait}}, {{neige}}"],["ay","{{é}}, {{-er}}, {{-ez}}","{{été}}, {{parler}}, {{nez}}"],["wah","{{oi}}","{{moi}}, {{trois}}"],["oo","{{ou}}","{{nous}}, {{soupe}}"],["uh","{{eu}}, {{œu}}","{{deux}}, {{sœur}}"],["sh","{{ch}}","{{chat}}, {{chien}}"],["ny","{{gn}}","{{montagne}}"],["k","{{c}}, {{qu}}, {{k}}","{{café}}, {{qui}}, {{kilo}}"],["y","{{ill}}, {{y}}","{{fille}}, {{yaourt}}"]],"title":"One sound, many spellings"},{"type":"tip","kind":"memory","text":"E-A-U looks scary, but it's just 'oh'! Picture a bottle of water: {{eau}} = 'oh'. And a {{bateau}} (boat) floats on it: bah-TOH."},{"type":"compare","items":[{"t":"oi","label":"wah","desc":"{{moi}}: me. Never 'oy'."},{"t":"ou","label":"oo","desc":"{{nous}}: we."},{"t":"eu","label":"uh","desc":"{{deux}}: two."}],"title":"Don't read them the English way"},{"type":"rule","name":"Soft c and g","color":"blue","desc":"Before e, i, y: c = 's' and g = 'zh'. Before a, o, u: c = 'k' and g = 'g'.","examples":[{"t":"cinéma","tr":"see-nay-MAH","hl":"c"},{"t":"café","tr":"kah-FAY","hl":"c"},{"t":"girafe","tr":"zhee-RAHF","hl":"g"},{"t":"gare","tr":"gahr","hl":"g"}]},{"type":"rule","name":"Keeping g soft","color":"blue","desc":"To keep g soft before a or o, French adds an e: {{ge}}.","examples":[{"t":"mangeons","tr":"mahn-ZHOHN","hl":"ge"},{"t":"Georges","tr":"zhorzh","hl":"ge"}],"how":"And to make g hard before e or i, add a u: {{guitare}} (ghee-TAR)."},{"type":"rule","name":"-tion = 'syohn'","color":"green","desc":"At the end of a word, -tion says 'syohn'.","examples":[{"t":"nation","tr":"nah-SYOHN","hl":"tion"},{"t":"attention","tr":"ah-tahn-SYOHN","hl":"tion"},{"t":"information","tr":"an-for-mah-SYOHN","hl":"tion"}]},{"type":"examples","items":[{"t":"le château","tr":"luh shah-TOH","mean":"the castle"},{"t":"un oiseau","tr":"uhn-nwah-ZOH","mean":"a bird"},{"t":"la neige","tr":"lah NEZH","mean":"snow"},{"t":"la campagne","tr":"lah kahn-PAHNY","mean":"the countryside"},{"t":"la feuille","tr":"lah FUHY","mean":"the leaf"},{"t":"huit","tr":"weet","mean":"eight"}],"title":"Decode these"},{"type":"practice","text":"Find the teams first, then read the whole word.","lines":["beau","moi","soupe","lait","deux","chat","montagne","nation","fille","oiseau"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"How do you say {{eau}}?","options":["ee-ah-oo","oh","yoo","ay-oh"],"answer":1},{"q":"How do you say {{oi}} in {{moi}}?","options":["wah","oy","oh-ee","wee"],"answer":0},{"q":"Listen. Which word do you hear?","say":"chat","options":["chaud","chou","chez","chat"],"answer":3},{"q":"In {{cinéma}}, the c sounds like…","options":["k","sh","s","ch"],"answer":2},{"q":"{{gn}} in {{montagne}} sounds like…","options":["the 'ny' in 'canyon'","a hard g then n","the 'gn' in 'sign'","the 'ng' in 'sing'"],"answer":0},{"q":"Which word has the 'ay' sound at the end?","options":["lait","mère","fête","parler"],"answer":3,"explain":"-er at the end of a verb says 'ay'. The others end in 'eh'."},{"q":"Listen. Which word do you hear?","say":"deux","options":["doux","deux","de l'eau","des"],"answer":1},{"q":"{{attention}} ends with the sound…","options":["shun","tee-on","syohn","tyohn"],"answer":2}]}]},{"id":"u1-liaison-elision","icon":"‿","title":"Liaison & Elision","subtitle":"How French words link together","minutes":12,"goals":["Link words with liaison","Drop a vowel with elision","Know where linking is not allowed"],"blocks":[{"type":"text","text":"French loves smooth sound. When one word ends and the next begins with a vowel, French links them, so speech flows without bumps. Two tools do this: **liaison** and **elision**."},{"type":"rule","name":"Liaison","color":"blue","desc":"A silent final consonant wakes up when the next word starts with a vowel or a silent h.","examples":[{"t":"les amis","tr":"lay-zah-MEE","hl":"s a"},{"t":"vous avez","tr":"voo-zah-VAY","hl":"s a"},{"t":"un ami","tr":"uhn-nah-MEE","hl":"n a"},{"t":"deux enfants","tr":"duh-zahn-FAHN","hl":"x e"}],"how":"s and x link with a 'z' sound; d links with a 't' sound ({{un grand homme}} = uhn grahn-TOM)."},{"type":"compare","items":[{"t":"les chats","label":"lay SHAH","desc":"Consonant next: s stays silent."},{"t":"les amis","label":"lay-zah-MEE","desc":"Vowel next: s wakes up as 'z'."}],"title":"Silent or awake?"},{"type":"tip","kind":"memory","text":"Imagine the silent letter is asleep. A vowel next door knocks and wakes it up: 'les… ZAMIS!'"},{"type":"rule","name":"Elision","color":"purple","desc":"Small words drop their last vowel before a vowel or silent h, and an apostrophe takes its place.","examples":[{"t":"l'ami","tr":"lah-MEE","hl":"l'"},{"t":"j'aime","tr":"zhem","hl":"j'"},{"t":"c'est","tr":"seh","hl":"c'"},{"t":"d'accord","tr":"dah-KOR","hl":"d'"},{"t":"l'hôtel","tr":"loh-TEL","hl":"l'"}],"how":"le, la, je, me, te, se, de, ne, que, ce → l', j', m', t', s', d', n', qu', c'."},{"type":"compare","items":[{"t":"le chat","label":"luh SHAH","desc":"Consonant next: le stays whole."},{"t":"l'ami","label":"lah-MEE","desc":"Vowel next: le becomes l'."}]},{"type":"rule","name":"No linking here!","color":"red","desc":"Never link after {{et}} (and), and never before an 'aspirated' h (marked * in dictionaries).","examples":[{"t":"et un","tr":"ay UHN","hl":"et"},{"t":"les haricots","tr":"lay ah-ree-KOH","hl":"les h"},{"t":"le héros","tr":"luh ay-ROH","hl":"le h"}]},{"type":"tip","kind":"warn","text":"Most h words are 'silent h' ({{l'homme}}, {{l'hôtel}}, {{les hommes}} = lay-ZOM). A few block linking: {{le héros}}, {{les haricots}}, {{la Hollande}}. Learn them as you meet them."},{"type":"examples","items":[{"t":"Ils ont un ami.","tr":"eel-zohn-tuhn-nah-MEE","mean":"They have a friend."},{"t":"C'est un hôtel.","tr":"seh-tuhn-noh-TEL","mean":"It's a hotel."},{"t":"J'habite à Lyon.","tr":"zhah-beet ah lee-OHN","mean":"I live in Lyon."}],"title":"Smooth sentences"},{"type":"practice","text":"Link the words smoothly, like one long word.","lines":["les amis","vous avez","un ami","deux enfants","l'ami","j'aime","c'est un hôtel","les haricots"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"How do you say {{les amis}}?","options":["lay ah-MEE","les-ah-MEES","lay-zah-MEE","lay-sah-MEE"],"answer":2},{"q":"Before a vowel, {{je}} becomes…","options":["j'","je'","jé","j"],"answer":0},{"q":"In liaison, a final s sounds like…","options":["s","sh","t","z"],"answer":3},{"q":"Which phrase has NO liaison?","options":["les amis","et un","vous avez","deux enfants"],"answer":1},{"q":"Listen. Which do you hear?","say":"l'ami","options":["l'ami","les amis","le mime","la nuit"],"answer":0},{"q":"Why is it {{le héros}} and not {{l'héros}}?","options":["Héros is plural","The é is silent","Its h blocks linking","It's an English word"],"answer":2},{"q":"Listen. Which phrase do you hear?","say":"vous avez","options":["vous savez","vous allez","nous avons","vous avez"],"answer":3}]}]},{"id":"u1-reading-lab","icon":"Abc","title":"Reading Lab","subtitle":"From syllables to real sentences","minutes":15,"goals":["Read syllables, words and phrases","Use everything from this unit together","Read a short dialogue aloud"],"blocks":[{"type":"text","text":"Time to put it all together! Read each level aloud, tap to check, and only move on when it feels easy. Slow and smooth beats fast and bumpy."},{"type":"examples","items":[{"t":"la","tr":"lah"},{"t":"le","tr":"luh"},{"t":"li","tr":"lee"},{"t":"lo","tr":"loh"},{"t":"lu","tr":"lew"},{"t":"lou","tr":"loo"},{"t":"loi","tr":"lwah"}],"title":"Level 1: syllables"},{"type":"examples","items":[{"t":"papa","tr":"pah-PAH","mean":"dad"},{"t":"ami","tr":"ah-MEE","mean":"friend"},{"t":"vélo","tr":"vay-LOH","mean":"bike"},{"t":"merci","tr":"mehr-SEE","mean":"thank you"},{"t":"maison","tr":"meh-ZOHN","mean":"house"},{"t":"bonjour","tr":"bohn-ZHOOR","mean":"hello"}],"title":"Level 2: words"},{"type":"tip","kind":"tip","text":"In {{maison}}, the s is between two vowels, so it says 'z': meh-ZOHN."},{"type":"examples","items":[{"t":"un café","tr":"uhn kah-FAY","mean":"a coffee"},{"t":"le chat","tr":"luh SHAH","mean":"the cat"},{"t":"la maison","tr":"lah meh-ZOHN","mean":"the house"},{"t":"les amis","tr":"lay-zah-MEE","mean":"the friends"},{"t":"mon ami","tr":"mohn-nah-MEE","mean":"my friend"},{"t":"l'école","tr":"lay-KOL","mean":"the school"}],"title":"Level 3: little groups"},{"type":"examples","items":[{"t":"Bonjour, madame !","tr":"bohn-ZHOOR, mah-DAHM","mean":"Hello, madam!"},{"t":"Merci beaucoup !","tr":"mehr-SEE boh-KOO","mean":"Thank you very much!"},{"t":"Je m'appelle Léa.","tr":"zhuh mah-pel lay-AH","mean":"My name is Léa."},{"t":"C'est un bon vin blanc.","tr":"seh-tuhn bohn van BLAHN","mean":"It's a good white wine."},{"t":"Les enfants sont à l'école.","tr":"lay-zahn-FAHN sohn-tah lay-KOL","mean":"The children are at school."}],"title":"Level 4: phrases"},{"type":"dialogue","lines":[{"who":"Léa","t":"Bonjour ! Ça va ?","tr":"bohn-ZHOOR! sah VAH?","mean":"Hello! How are you?"},{"who":"Hugo","t":"Très bien, merci. Et toi ?","tr":"treh BYAN, mehr-SEE. ay TWAH?","mean":"Very well, thanks. And you?"},{"who":"Léa","t":"Ça va bien. Un café ?","tr":"sah vah BYAN. uhn kah-FAY?","mean":"I'm fine. A coffee?"},{"who":"Hugo","t":"Oui, avec plaisir !","tr":"wee, ah-vek pleh-ZEER!","mean":"Yes, with pleasure!"}],"title":"Level 5: a mini dialogue"},{"type":"practice","text":"Read the whole dialogue aloud twice: once slowly, once at a natural speed.","lines":["Bonjour ! Ça va ?","Très bien, merci. Et toi ?","Ça va bien. Un café ?","Oui, avec plaisir !"]},{"type":"selfcheck","title":"Can you…?","items":["I keep my vowels short and pure.","I stress the end of each word group.","I don't say most final consonants.","I make nasal vowels without a real n.","I link words with liaison and elision."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"How do you read {{maison}}?","options":["MAY-son","meh-ZOHN","may-SOHN","mah-ee-SON"],"answer":1},{"q":"Listen. Which phrase do you hear?","say":"mon ami","options":["mon ami","mon avis","mes amis","un ami"],"answer":0},{"q":"In {{Très bien}}, the s of {{très}} is…","options":["said 's'","said 'z'","silent","said 'sh'"],"answer":2},{"q":"{{Ça va ?}} means…","options":["Thank you","Goodbye","Let's go to school","How are you?"],"answer":3},{"q":"Listen. Which sentence do you hear?","say":"Merci beaucoup !","options":["Bonjour, madame !","Merci beaucoup !","Avec plaisir !","Très bien, merci."],"answer":1},{"q":"How many syllables are in {{l'école}}?","options":["Two (lay-KOL)","Three (luh-ay-KOL)","One","Four"],"answer":0}]}]}]});
LC.units.push({"id":"writing","order":2,"icon":"é","color":"cyan","title":"Writing & Spelling","subtitle":"Write French neatly, with accents and confidence","lessons":[{"id":"u2-letters-accents","icon":"é","title":"Writing Letters & Accents","subtitle":"Clear letters, neat accents","minutes":14,"goals":["Write é, è, ê, ç, à and œ correctly","Put each accent in the right direction","Type accents on your phone and computer"],"blocks":[{"type":"text","text":"You already know how to write the letters. In French, the magic is in the small marks. A missing or wrong accent can change a word, so let's write them with care. Grab a pen!"},{"type":"tip","kind":"culture","text":"In France, children learn joined-up handwriting on paper with little squares and lines. Many people also write the number 1 with a long up-stroke and cross the 7 so it isn't confused with 1."},{"type":"howto","char":"é","name":"e accent aigu","steps":["Write a small e: start in the middle, go right, loop up and around, finish open at the bottom right.","Lift your pen.","Draw a short stroke above the e, rising from bottom left to top right (´).","Keep it small and just above the letter, not touching it."],"tip":"Aigu climbs UP to the right, like your voice rising to 'ay'."},{"type":"howto","char":"è","name":"e accent grave","steps":["Write a small e.","Lift your pen.","Draw a short stroke above it, sloping down from top left to bottom right (`)."],"tip":"Grave goes down: think of a slide going down to the right."},{"type":"howto","char":"ê","name":"e accent circonflexe","steps":["Write a small e.","Draw a small up-stroke to the right.","Without lifting, come down to the right: a tiny roof or hat (^)."],"tip":"A little hat sits on the letter, hiding a lost s: {{fête}} = feast."},{"type":"howto","char":"ç","name":"c cédille","steps":["Write a small c.","Start just under the bottom of the c.","Add a small tail that curls down and to the left, like a tiny comma."],"tip":"Only before a, o or u. Never write ç before e or i: c is already soft there."},{"type":"howto","char":"à","name":"a accent grave","steps":["Write a small a.","Lift your pen.","Add a short stroke sloping down to the right (`)."],"tip":"{{à}} with an accent = to / at. {{a}} without = has."},{"type":"howto","char":"œ","name":"e dans l'o","steps":["Start a small o, but don't close it on the right.","Let the right side of the o become the start of the e.","Finish the e loop. The two letters share one side."],"tip":"Common words: {{cœur}} (heart), {{sœur}} (sister), {{œuf}} (egg)."},{"type":"write","level":"letter","items":["é","è","ê","ë","à","â","ç","î","ô","ù","û","œ"],"note":"Say the name of each one as you write it."},{"type":"write","level":"word","items":["café","mère","fête","garçon","voilà","cœur","Noël","hôtel"],"note":"Write the word first, then add the accents."},{"type":"tip","kind":"warn","text":"Capital letters keep their accents: {{École}}, {{État}}, {{À bientôt}}, {{Ça va}}. Writing them is correct and clearer."},{"type":"table","head":["Device","How to get é, è, ç…"],"rows":[["Phone or tablet","Press and hold the letter (e, a, c, o…) and slide to the accent you need."],["Mac","Option + e then e = {{é}}; Option + ` then e = {{è}}; Option + i then e = {{ê}}; Option + c = {{ç}}"],["Windows","Add the French or 'US International' keyboard in Settings, or use the touch keyboard and hold the letter."]],"title":"Typing accents"},{"type":"practice","text":"Read each word aloud, then write it from memory.","lines":["été","très","forêt","ça","là","sœur"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Which way does the accent on {{é}} go?","options":["Up to the right (´)","Down to the right (`)","Like a hat (^)","Two dots (¨)"],"answer":0},{"q":"Where does the cédille go on ç?","options":["Above the c","After the c","Under the c","Inside the c"],"answer":2},{"q":"Which is spelled correctly?","options":["garcon","garçon","garçcon","gaŕçon"],"answer":1},{"q":"When do you write ç?","options":["Before e or i","At the end of a word","Only in capitals","Before a, o or u"],"answer":3},{"q":"Which word means 'heart'?","options":["cœur","cour","cure","car"],"answer":0},{"q":"Do capital letters keep their accents?","options":["No, never","Yes, it is correct: École","Only on the letter A","Only in names"],"answer":1},{"q":"Listen. Which word do you hear?","say":"sœur","options":["sœur","sur","sourd","seul"],"answer":0}]}]},{"id":"u2-spelling-patterns","icon":"eau","title":"Common Spelling Patterns","subtitle":"Hear a sound, choose the letters","minutes":14,"goals":["Pick common spellings for a sound","Use s vs ss and plural endings","Turn English words into French ones"],"blocks":[{"type":"text","text":"French spelling looks tricky, but it follows patterns. Once you know them, you can often guess how to write a word you hear. Let's become spelling detectives!"},{"type":"table","head":["You hear","Often written","Examples"],"rows":[["oh","{{o}}, {{au}}, {{eau}}","{{vélo}}, {{auto}}, {{gâteau}}"],["eh","{{è}}, {{ê}}, {{ai}}, {{e}} + 2 consonants","{{père}}, {{tête}}, {{maison}}, {{belle}}"],["ay","{{é}}, {{-er}}, {{-ez}}","{{été}}, {{manger}}, {{chez}}"],["s","{{s}}, {{ss}}, {{c}}, {{ç}}, {{-tion}}","{{sac}}, {{classe}}, {{ici}}, {{leçon}}, {{nation}}"],["k","{{c}}, {{qu}}, {{k}}","{{carte}}, {{quand}}, {{kiwi}}"],["ahn","{{an}}, {{en}}, {{am}}, {{em}}","{{blanc}}, {{vent}}, {{jambe}}, {{temps}}"]],"title":"Sound → spelling"},{"type":"rule","name":"s or ss?","color":"blue","desc":"Between two vowels, one s says 'z'. To keep the 's' sound, write ss.","examples":[{"t":"rose","tr":"rohz","hl":"s"},{"t":"maison","tr":"meh-ZOHN","hl":"s"},{"t":"classe","tr":"klahs","hl":"ss"},{"t":"poisson","tr":"pwah-SOHN","hl":"ss"}]},{"type":"compare","items":[{"t":"poison","label":"pwah-ZOHN","desc":"One s = 'z': poison."},{"t":"poisson","label":"pwah-SOHN","desc":"Double s = 's': fish."}],"title":"Don't poison the fish!"},{"type":"compare","items":[{"t":"désert","label":"day-ZEHR","desc":"One s: desert."},{"t":"dessert","label":"deh-SEHR","desc":"Double s: dessert (you want more of it, so two s!)."}]},{"type":"rule","name":"Plurals","color":"green","desc":"Usually add a silent -s. Words in -eau and -eu add -x. Many words in -al change to -aux.","examples":[{"t":"un chat → des chats","tr":"uhn SHAH → day SHAH","hl":"s"},{"t":"un gâteau → des gâteaux","tr":"uhn gah-TOH → day gah-TOH","hl":"x"},{"t":"un jeu → des jeux","tr":"uhn ZHUH → day ZHUH","hl":"x"},{"t":"un animal → des animaux","tr":"uhn-nah-nee-MAHL → day-zah-nee-MOH","hl":"aux"}],"how":"You often can't hear the plural, so look at the little word in front: {{le/la}} vs {{les}}, {{un}} vs {{des}}."},{"type":"rule","name":"Feminine -e","color":"orange","desc":"Many words add -e for the feminine. Sometimes you hear it, sometimes not.","examples":[{"t":"grand → grande","tr":"grahn → grahnd","hl":"e"},{"t":"petit → petite","tr":"puh-TEE → puh-TEET","hl":"e"},{"t":"ami → amie","tr":"ah-MEE → ah-MEE","hl":"e"}]},{"type":"tip","kind":"memory","text":"Free vocabulary! Many English endings have French twins: -ty → {{-té}} ({{liberté}}, {{université}}), -ous → {{-eux}} ({{curieux}}, {{dangereux}}), -ly → {{-ment}} ({{rapidement}}), -tion stays {{-tion}} ({{information}})."},{"type":"examples","items":[{"t":"la liberté","tr":"lah lee-behr-TAY","mean":"freedom, liberty"},{"t":"curieux","tr":"kew-RYUH","mean":"curious"},{"t":"rapidement","tr":"rah-peed-MAHN","mean":"quickly"},{"t":"la société","tr":"lah soh-syay-TAY","mean":"society"}],"title":"English → French"},{"type":"practice","text":"Read, then cover and write each word. Check your s and ss!","lines":["rose","classe","poisson","dessert","des gâteaux","des animaux","une amie","la liberté"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"You hear 'pwah-SOHN' (fish). How is it written?","options":["poison","poissson","poisson","poisonne"],"answer":2},{"q":"Which is the correct plural of {{gâteau}}?","options":["gâteaux","gâteaus","gâteau","gâteaues"],"answer":0},{"q":"One s between two vowels sounds like…","options":["s","z","sh","nothing"],"answer":1},{"q":"{{animal}} in the plural is…","options":["animals","animales","animalx","animaux"],"answer":3},{"q":"Which is the French spelling of 'university'?","options":["université","universitée","universitey","universitie"],"answer":0},{"q":"Listen. Which word do you hear?","say":"dessert","options":["désert","désir","dessert","dessin"],"answer":2},{"q":"{{dangereux}} means…","options":["danger","dangerous","dangerously","endangered"],"answer":1}]}]},{"id":"u2-capitals-punctuation","icon":"«»","title":"Capitals & Punctuation","subtitle":"Small rules that look very French","minutes":12,"goals":["Know which words have no capital","Use « guillemets » for quotes","Put a space before ! ? : ;"],"blocks":[{"type":"text","text":"French punctuation has a few surprises. Get them right and your writing instantly looks French. They are easy to learn: just a few small habits."},{"type":"rule","name":"No capitals for days, months and languages","color":"red","desc":"Inside a sentence, days, months, languages and nationality adjectives start with a small letter.","examples":[{"t":"lundi","tr":"luhn-DEE"},{"t":"en janvier","tr":"ahn zhahn-VYAY"},{"t":"Je parle anglais.","tr":"zhuh parl ahn-GLEH","hl":"anglais"},{"t":"un livre français","tr":"uhn leevr frahn-SEH","hl":"français"}]},{"type":"compare","items":[{"t":"un Français","label":"Capital F","desc":"A French person (a noun for people)."},{"t":"un livre français","label":"Small f","desc":"A French book (describing word)."},{"t":"le français","label":"Small f","desc":"The French language."}],"title":"Français or français?"},{"type":"tip","kind":"memory","text":"Only PEOPLE get a capital: {{les Français}}, {{une Anglaise}}. Books, food and languages stay small: {{le fromage français}}, {{l'anglais}}."},{"type":"rule","name":"A space before two-part marks","color":"blue","desc":"Put a space before ! ? : ; and none before . or ,","examples":[{"t":"Bonjour !","tr":"bohn-ZHOOR"},{"t":"Ça va ?","tr":"sah VAH"},{"t":"Attention : danger !","tr":"ah-tahn-SYOHN : dahn-ZHAY"}],"how":"A good trick: marks made of two pieces (! ? : ;) get a space. One-piece marks (. ,) don't."},{"type":"rule","name":"« Guillemets » for quotes","color":"purple","desc":"French uses « » for quotations, with a space inside each one.","examples":[{"t":"Il dit : « Bonjour ! »","tr":"eel DEE : bohn-ZHOOR","hl":"« Bonjour ! »"}],"how":"In dialogues, a new speaker is often shown with a dash: — Ça va ? — Oui, merci."},{"type":"tip","kind":"fun","text":"{{Guillemets}} (ghee-yuh-MEH) are said to be named after a French printer called Guillaume. They look like little arrows hugging the words."},{"type":"table","head":["","English","French"],"rows":[["Decimal","3.5","{{3,5}}"],["Thousands","10,000","{{10 000}}"],["Quote","\"Hi!\"","{{« Salut ! »}}"],["Question","Why?","{{Pourquoi ?}}"]],"title":"Side by side"},{"type":"tip","kind":"tip","text":"Write {{monsieur}} and {{madame}} with a small letter inside a sentence. Use a capital at the start of a letter ({{Chère Madame,}}) and in the short forms {{M.}} and {{Mme}}."},{"type":"practice","text":"Read aloud, then copy each line with the French spacing.","lines":["Bonjour !","Comment ça va ?","Elle dit : « Merci ! »","Lundi, je parle français.","Il a 3,5 euros."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Which is correct French?","options":["J'aime le Français.","J'aime le français.","J'Aime le français.","j'aime Le français."],"answer":1},{"q":"Which is written correctly?","options":["Ça va ?","Ça va?","Ça va ;","« Ça va »?"],"answer":0},{"q":"How do you write 'Monday' inside a sentence?","options":["Lundi","LUNDI","Lun-di","lundi"],"answer":3},{"q":"Which marks does French use for quotations?","options":["\" \"","( )","« »","[ ]"],"answer":2},{"q":"Which needs a space before it in French?","options":[".",":",",","'"],"answer":1},{"q":"'A French person' is written…","options":["un Français","un français","un Francais","un françois"],"answer":0},{"q":"How is 2.5 written in French?","options":["2.5","2-5","2'5","2,5"],"answer":3}]}]},{"id":"u2-apostrophes","icon":"l'","title":"Apostrophes & Elision","subtitle":"When little words lose a letter","minutes":10,"goals":["Know the words that drop their vowel","Write l', j', d', c', n', qu' correctly","Avoid common apostrophe mistakes"],"blocks":[{"type":"text","text":"In Unit 1 you heard elision: {{le ami}} becomes {{l'ami}}. Now let's write it. The rule is simple and very regular: a small word drops its vowel before another vowel or a silent h."},{"type":"table","head":["Word","Before a vowel","Example"],"rows":[["{{le}}, {{la}}","{{l'}}","{{l'ami}}, {{l'école}}"],["{{je}}","{{j'}}","{{j'aime}}"],["{{me}}, {{te}}, {{se}}","{{m'}}, {{t'}}, {{s'}}","{{je m'appelle}}, {{il s'appelle}}"],["{{de}}","{{d'}}","{{un verre d'eau}}"],["{{ne}}","{{n'}}","{{je n'aime pas}}"],["{{que}}","{{qu'}}","{{qu'est-ce que…}}"],["{{ce}}","{{c'}}","{{c'est}}"],["{{si}}","{{s'}} (only before il/ils)","{{s'il vous plaît}}"]],"title":"The elision family"},{"type":"tip","kind":"memory","text":"Think of the apostrophe as a little bandage where a vowel fell off: {{je + aime}} → {{j'aime}}. The two words now hold hands."},{"type":"rule","name":"Silent h counts as a vowel","color":"green","desc":"Before a silent h, elide just like before a vowel.","examples":[{"t":"l'homme","tr":"lom","hl":"l'"},{"t":"l'hôtel","tr":"loh-TEL","hl":"l'"},{"t":"j'habite","tr":"zhah-BEET","hl":"j'"}]},{"type":"rule","name":"No elision here","color":"red","desc":"Before a consonant or an 'aspirated' h, keep the full word.","examples":[{"t":"le chat","tr":"luh SHAH"},{"t":"le héros","tr":"luh ay-ROH"},{"t":"la Hollande","tr":"lah oh-LAHND"},{"t":"si elle","tr":"see EL"}],"how":"{{si}} becomes {{s'}} only before {{il}} and {{ils}}: {{s'il}}, but {{si elle}}."},{"type":"compare","items":[{"t":"le ami","label":"Wrong","desc":"Two vowels bump into each other."},{"t":"l'ami","label":"Right","desc":"Smooth: one apostrophe, no space after it."}],"title":"Spot the mistake"},{"type":"tip","kind":"warn","text":"No space after the apostrophe: {{l'école}}, never {{l' école}}. And only the little words in the table elide: {{une amie}}, never {{un' amie}}."},{"type":"examples","items":[{"t":"aujourd'hui","tr":"oh-zhoor-DWEE","mean":"today","note":"A word with a built-in apostrophe."},{"t":"quelqu'un","tr":"kel-KUHN","mean":"someone"},{"t":"Qu'est-ce que c'est ?","tr":"kes-kuh SEH","mean":"What is it?"}],"title":"Words to remember"},{"type":"write","level":"word","items":["l'ami","l'école","j'aime","c'est","d'accord","aujourd'hui","quelqu'un","s'il vous plaît"]},{"type":"practice","text":"Read aloud. Say each elided pair as one word.","lines":["J'aime l'école.","C'est l'hôtel.","Je n'ai pas d'argent.","Il s'appelle Hugo.","Qu'est-ce que c'est ?"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"{{je + habite}} is written…","options":["je habite","j' habite","j'habite","jhabite"],"answer":2},{"q":"Which is correct?","options":["le chat","l'chat","l'e chat","le' chat"],"answer":0},{"q":"Which is correct?","options":["s'elle","s'il elle","si' elle","si elle"],"answer":3},{"q":"{{la + école}} becomes…","options":["la école","l'école","l' école","la'école"],"answer":1},{"q":"Which word keeps its vowel before {{héros}}?","options":["le (le héros)","l' (l'héros)","la (la héros)","lé (lé héros)"],"answer":0},{"q":"Listen. Which do you hear?","say":"aujourd'hui","options":["au jour","à jeudi","aujourd'hui","d'accord"],"answer":2},{"q":"{{ce + est}} is written…","options":["ce est","c' est","s'est","c'est"],"answer":3,"explain":"{{s'est}} also exists (from {{se}}), but 'it is' is {{c'est}}."}]}]},{"id":"u2-dictation","icon":"✎","title":"Dictation Practice","subtitle":"Listen, write, check","minutes":15,"goals":["Write what you hear, step by step","Check accents and silent letters","Tell a/à, et/est and ou/où apart"],"blocks":[{"type":"text","text":"La dictée (dictation) is a French classic: someone reads, you write. It trains your ears and your spelling at the same time. Don't worry about mistakes: they show you exactly what to practise."},{"type":"steps","items":[{"title":"Listen","desc":"Hear the whole item once without writing."},{"title":"Write","desc":"Play it again and write what you hear."},{"title":"Check sounds","desc":"Did you use the right team for each sound (eau, ai, ou…)?"},{"title":"Check silent letters","desc":"Plural s? Feminine e? Final t or d?"},{"title":"Check accents","desc":"Every é, è, à, ç in place?"}],"title":"The 5-step method"},{"type":"dictation","items":[{"t":"café","tr":"kah-FAY","mean":"coffee"},{"t":"mère","tr":"mehr","mean":"mother"},{"t":"garçon","tr":"gar-SOHN","mean":"boy"},{"t":"bateau","tr":"bah-TOH","mean":"boat"},{"t":"fille","tr":"FEE-y","mean":"girl"},{"t":"montagne","tr":"mohn-TAHNY","mean":"mountain"}],"title":"Level 1: words"},{"type":"dictation","items":[{"t":"le petit chat","tr":"luh puh-tee SHAH","mean":"the little cat"},{"t":"une maison blanche","tr":"ewn meh-zohn BLAHNSH","mean":"a white house"},{"t":"les amis","tr":"lay-zah-MEE","mean":"the friends"},{"t":"l'école","tr":"lay-KOL","mean":"school"}],"title":"Level 2: little groups"},{"type":"rule","name":"Sound-alikes","color":"purple","desc":"Same sound, different word. Use a swap test to choose.","examples":[{"t":"a / à","tr":"ah"},{"t":"et / est","tr":"ay / eh"},{"t":"ou / où","tr":"oo"}],"how":"If you can say {{avait}} instead, write {{a}}. If you can say {{était}}, write {{est}}. If you can say {{ou bien}}, write {{ou}}."},{"type":"tip","kind":"memory","text":"The swap test: {{Il a un chat}} → {{Il avait un chat}} ✓ so it's {{a}}. {{Il va à Paris}} → {{Il va avait Paris}} ✗ so it's {{à}}."},{"type":"dictation","items":[{"t":"Il a un chat.","tr":"eel ah uhn SHAH","mean":"He has a cat."},{"t":"Je vais à Paris.","tr":"zhuh veh ah pah-REE","mean":"I'm going to Paris."},{"t":"Léa est grande.","tr":"lay-AH eh GRAHND","mean":"Léa is tall."},{"t":"Où est le café ?","tr":"oo eh luh kah-FAY","mean":"Where is the café?"},{"t":"Les enfants jouent dans le jardin.","tr":"lay-zahn-FAHN zhoo dahn luh zhar-DAN","mean":"The children are playing in the garden."}],"title":"Level 3: sentences"},{"type":"tip","kind":"warn","text":"In {{jouent}}, the -ent is silent, but you must write it. The sound tells you the word; grammar tells you the ending."},{"type":"selfcheck","title":"After each dictation","items":["I listen once before writing.","I check plural s and feminine e.","I check every accent.","I use the swap test for a/à, et/est, ou/où."]},{"type":"practice","text":"Read your answers aloud and compare them with the audio.","lines":["Il a un chat.","Je vais à Paris.","Léa est grande.","Où est le café ?"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Listen. Write it in your head, then choose.","say":"bateau","options":["batteau","bateau","bâtot","batau"],"answer":1},{"q":"Listen. Which spelling is right?","say":"les amis","options":["les amis","lézamis","les zamis","l'es amis"],"answer":0},{"q":"{{Il ___ à Paris.}} (He is in Paris.)","options":["et","es","est","ai"],"answer":2},{"q":"{{Tu viens ___ pas ?}} (Are you coming or not?)","options":["où","oû","houx","ou"],"answer":3},{"q":"{{Je vais ___ l'école.}}","options":["à","a","as","ah"],"answer":0},{"q":"Listen. Which spelling is right?","say":"une maison blanche","options":["une maison blanc","une maison blanche","un maison blanche","une maisson blanche"],"answer":1},{"q":"{{Les enfants jou___.}} Which ending is silent but needed?","options":["-ont","-ez","-ent","-es"],"answer":2}]}]},{"id":"u2-first-sentences","icon":"Je","title":"Your First Sentences","subtitle":"Write about yourself in French","minutes":15,"goals":["Copy five useful sentence patterns","Write three sentences about yourself","Check spelling, accents and punctuation"],"blocks":[{"type":"text","text":"This is a big moment: your first real French sentences! We'll copy useful patterns, then change one word to talk about you. Write slowly and neatly. Every sentence you write is a step forward."},{"type":"sentence","t":"Je m'appelle Léa.","tr":"zhuh mah-pel lay-AH","mean":"My name is Léa.","words":[{"t":"Je","mean":"I"},{"t":"m'appelle","mean":"call myself"},{"t":"Léa","mean":"Léa"}],"note":"Word for word: 'I call myself Léa'."},{"type":"sentence","t":"J'ai seize ans.","tr":"zhay seh-ZAHN","mean":"I am sixteen.","words":[{"t":"J'ai","mean":"I have"},{"t":"seize","mean":"sixteen"},{"t":"ans","mean":"years"}],"note":"French says 'I have 16 years'."},{"type":"sentence","t":"J'habite à Londres.","tr":"zhah-beet ah LOHNDR","mean":"I live in London.","words":[{"t":"J'habite","mean":"I live"},{"t":"à","mean":"in"},{"t":"Londres","mean":"London"}]},{"type":"sentence","t":"Je parle anglais.","tr":"zhuh parl ahn-GLEH","mean":"I speak English.","words":[{"t":"Je","mean":"I"},{"t":"parle","mean":"speak"},{"t":"anglais","mean":"English"}]},{"type":"sentence","t":"J'aime la musique.","tr":"zhem lah mew-ZEEK","mean":"I like music.","words":[{"t":"J'aime","mean":"I like"},{"t":"la","mean":"the"},{"t":"musique","mean":"music"}],"note":"French keeps {{la}} (the) here: 'I like the music'."},{"type":"vocab","items":[{"t":"le football","tr":"luh foot-BOL","mean":"football, soccer"},{"t":"la lecture","tr":"lah lek-TEWR","mean":"reading"},{"t":"le chocolat","tr":"luh shoh-koh-LAH","mean":"chocolate"},{"t":"les animaux","tr":"lay-zah-nee-MOH","mean":"animals"},{"t":"le cinéma","tr":"luh see-nay-MAH","mean":"cinema, films"}],"title":"Things you might like"},{"type":"tip","kind":"tip","text":"Remember: {{anglais}} has a small a (it's a language), but {{Londres}} has a capital (it's a place)."},{"type":"write","level":"line","items":["Je m'appelle Léa.","J'ai seize ans.","J'habite à Londres.","Je parle anglais.","J'aime la musique."],"note":"Copy each line neatly. Check the apostrophes and accents.","title":"Copywork"},{"type":"write","level":"line","items":["Je m'appelle …","J'ai … ans.","J'habite à …","J'aime …"],"note":"Now write about you: fill each gap with your own word.","title":"Your turn"},{"type":"tip","kind":"memory","text":"Use the 3-check rule before you finish: 1. a capital at the start, 2. a full stop at the end, 3. every accent in place."},{"type":"examples","items":[{"t":"Bonjour ! Je m'appelle Hugo.","tr":"bohn-ZHOOR! zhuh mah-pel ew-GOH","mean":"Hello! My name is Hugo."},{"t":"J'ai quatorze ans et j'habite à Québec.","tr":"zhay kah-tor-ZAHN ay zhah-beet ah kay-BEK","mean":"I'm fourteen and I live in Quebec City."},{"t":"Je parle français et anglais.","tr":"zhuh parl frahn-SEH ay ahn-GLEH","mean":"I speak French and English."},{"t":"J'aime le football et le chocolat !","tr":"zhem luh foot-BOL ay luh shoh-koh-LAH","mean":"I love football and chocolate!"}],"title":"A model introduction"},{"type":"practice","text":"Read the model aloud, then read your own sentences aloud.","lines":["Bonjour ! Je m'appelle Hugo.","J'ai quatorze ans et j'habite à Québec.","Je parle français et anglais.","J'aime le football et le chocolat !"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"How do you write 'My name is Tom'?","options":["Je appelle Tom.","J'appelle Tom.","Je m'appelle Tom.","Je m'apelle Tom."],"answer":2},{"q":"'I am sixteen' in French is…","options":["J'ai seize ans.","Je suis seize.","Je seize ans.","J'ai ans seize."],"answer":0},{"q":"Which sentence is correct?","options":["Je parle Anglais.","je parle anglais.","Je parle anglais .","Je parle anglais."],"answer":3},{"q":"{{J'aime la musique}} means…","options":["I am the music.","I like music.","I make music.","I hear music."],"answer":1},{"q":"Listen. Which sentence do you hear?","say":"J'habite à Londres.","options":["J'habite à Londres.","J'habite à Lyon.","J'aime Londres.","Je suis à Londres."],"answer":0},{"q":"Which is the 3-check rule?","options":["Nouns, verbs, plurals","Read, sing, repeat","Capital, full stop, accents","Spaces, colours, numbers"],"answer":2}]}]}]});
LC.units.push({"id":"words","order":3,"icon":"Bon","color":"emerald","title":"First Words & Phrases","subtitle":"Greetings, numbers, time, family, food and everyday life","lessons":[{"id":"u3-greetings","icon":"Bon","title":"Hello, Goodbye & Please","subtitle":"Greet people and be polite, the French way","minutes":12,"goals":["Say hello and goodbye at any time of day","Use please, thank you and sorry","Choose between tu and vous"],"blocks":[{"type":"text","text":"In France, you say **hello** before anything else: in shops, in lifts, on the bus. A simple {{Bonjour !}} opens every door. Let's learn the words people use every day."},{"type":"vocab","items":[{"t":"Bonjour","tr":"bohn-ZHOOR","mean":"Hello / Good morning (daytime)","example":{"t":"Bonjour, madame !","tr":"bohn-ZHOOR, mah-DAHM","mean":"Hello, madam!"}},{"t":"Bonsoir","tr":"bohn-SWAHR","mean":"Good evening","example":{"t":"Bonsoir, monsieur.","tr":"bohn-SWAHR, muh-SYUH","mean":"Good evening, sir."}},{"t":"Salut","tr":"sah-LEW","mean":"Hi / Bye (with friends)","example":{"t":"Salut, Léa !","tr":"sah-LEW, lay-AH","mean":"Hi, Léa!"}},{"t":"Au revoir","tr":"oh ruh-VWAHR","mean":"Goodbye"},{"t":"À bientôt","tr":"ah byan-TOH","mean":"See you soon"},{"t":"À demain","tr":"ah duh-MAN","mean":"See you tomorrow"},{"t":"Bonne journée","tr":"bun zhoor-NAY","mean":"Have a good day"},{"t":"Bonne soirée","tr":"bun swah-RAY","mean":"Have a good evening"},{"t":"Bonne nuit","tr":"bun NWEE","mean":"Good night (at bedtime)"}],"title":"Hello & goodbye"},{"type":"tip","kind":"culture","text":"Say {{Bonjour}} until late afternoon, then switch to {{Bonsoir}} (from about 6 pm). {{Bonne nuit}} is only for going to bed: never use it to say hello."},{"type":"vocab","items":[{"t":"S'il vous plaît","tr":"seel voo PLEH","mean":"Please (polite)"},{"t":"S'il te plaît","tr":"seel tuh PLEH","mean":"Please (to a friend)"},{"t":"Merci","tr":"mehr-SEE","mean":"Thank you"},{"t":"Merci beaucoup","tr":"mehr-SEE boh-KOO","mean":"Thank you very much"},{"t":"De rien","tr":"duh RYAN","mean":"You're welcome"},{"t":"Pardon","tr":"par-DOHN","mean":"Sorry / Excuse me (if you bump into someone)"},{"t":"Excusez-moi","tr":"ex-kew-zay-MWAH","mean":"Excuse me (to get attention)"},{"t":"Désolé / Désolée","tr":"day-zoh-LAY","mean":"I'm sorry (said by a man / a woman)"},{"t":"Oui","tr":"WEE","mean":"Yes"},{"t":"Non","tr":"NOHN","mean":"No"}],"title":"Magic words"},{"type":"text","text":"French has two words for **you**. {{tu}} is friendly: for family, friends, children and pets. {{vous}} is polite: for strangers, shop staff, older people and anyone at work. {{vous}} is also the plural **you** for a group.","title":"Tu or vous?"},{"type":"compare","items":[{"t":"tu","label":"Friendly you","desc":"Family, friends, children, classmates. Relaxed and close."},{"t":"vous","label":"Polite or plural you","desc":"Strangers, shops, teachers, colleagues, or any group of people."}]},{"type":"tip","kind":"memory","text":"When in doubt, use {{vous}}. A French person will tell you when they want {{tu}}. You may hear {{On se tutoie ?}}, which means 'Shall we say tu?'"},{"type":"examples","items":[{"t":"Comment allez-vous ?","tr":"koh-mahn tah-lay-VOO","mean":"How are you? (polite)"},{"t":"Ça va ?","tr":"sah VAH","mean":"How's it going? (friendly)"},{"t":"Ça va bien, merci.","tr":"sah vah BYAN, mehr-SEE","mean":"I'm fine, thanks."},{"t":"Très bien, et vous ?","tr":"treh BYAN, ay VOO","mean":"Very well, and you?"},{"t":"Pas mal.","tr":"pah MAHL","mean":"Not bad."},{"t":"Bof...","tr":"BOF","mean":"Meh... so-so.","note":"Very casual. A little shrug helps!"}],"title":"How are you?"},{"type":"sentence","t":"Bonjour, comment allez-vous ?","tr":"bohn-ZHOOR, koh-mahn tah-lay-VOO","mean":"Hello, how are you?","words":[{"t":"Bonjour","mean":"hello"},{"t":"comment","mean":"how"},{"t":"allez-vous","mean":"go you (are you)"}],"note":"French literally asks 'How do you go?'. The T of {{comment}} links to {{allez}}."},{"type":"dialogue","lines":[{"who":"Client","t":"Bonjour, madame !","tr":"bohn-ZHOOR, mah-DAHM","mean":"Hello, madam!"},{"who":"Baker","t":"Bonjour, monsieur. Vous désirez ?","tr":"bohn-ZHOOR, muh-SYUH. voo day-zee-RAY","mean":"Hello, sir. What would you like?"},{"who":"Client","t":"Une baguette, s'il vous plaît.","tr":"ewn bah-GET, seel voo PLEH","mean":"A baguette, please."},{"who":"Baker","t":"Voilà. Un euro vingt, s'il vous plaît.","tr":"vwah-LAH. an nuh-roh VAN, seel voo PLEH","mean":"Here you are. One euro twenty, please."},{"who":"Client","t":"Merci. Bonne journée !","tr":"mehr-SEE. bun zhoor-NAY","mean":"Thanks. Have a good day!"},{"who":"Baker","t":"Merci, vous aussi ! Au revoir !","tr":"mehr-SEE, voo-zoh-SEE. oh ruh-VWAHR","mean":"Thanks, you too! Goodbye!"}],"title":"At the bakery"},{"type":"tip","kind":"culture","text":"Friends and family often greet each other with **la bise**: light kisses on the cheeks (usually two, but it depends on the region). With strangers and at work, a handshake is normal."},{"type":"practice","text":"Read each line aloud. Smile: it really helps the sound!","lines":["Bonjour !","Bonsoir, madame.","Salut, ça va ?","Merci beaucoup !","De rien.","S'il vous plaît.","Au revoir, à bientôt !"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"It's 8 pm and you walk into a restaurant. What do you say?","options":["Bonne nuit !","À demain !","Bonsoir !"],"answer":2,"explain":"{{Bonsoir}} is the evening greeting. {{Bonne nuit}} is only for bedtime."},{"q":"Which 'you' do you use with a shop assistant?","options":["tu","vous","toi"],"answer":1,"explain":"Use polite {{vous}} with people you don't know."},{"q":"Listen. What does it mean?","say":"Merci beaucoup !","options":["Thank you very much","You're welcome","See you very soon","Excuse me, please"],"answer":0},{"q":"Someone says {{Merci !}} What do you answer?","options":["S'il vous plaît.","De rien.","Pardon.","Bonne nuit."],"answer":1,"explain":"{{De rien}} = it's nothing / you're welcome."},{"q":"How do you say 'please' to a friend?","options":["S'il vous plaît","Merci bien","De rien","S'il te plaît"],"answer":3,"explain":"{{te}} goes with {{tu}}, {{vous}} with {{vous}}."},{"q":"Listen. When will you see this person again?","say":"À demain !","options":["This evening","Very soon","Tomorrow","Next week"],"answer":2},{"q":"What does this mean?","t":"Ça va ?","options":["Where are you going?","What's your name?","How's it going?","Is it far?"],"answer":2}]}]},{"id":"u3-introductions","icon":"Moi","title":"Introducing Yourself","subtitle":"Your name, your country, your age","minutes":12,"goals":["Say your name and ask someone else's","Say where you're from and your nationality","Say how old you are"],"blocks":[{"type":"text","text":"Let's talk about **you**! With a few short phrases you can give your name, your country and your age, and ask the same questions back."},{"type":"sentence","t":"Je m'appelle Sophie.","tr":"zhuh mah-PEL soh-FEE","mean":"My name is Sophie.","words":[{"t":"Je","mean":"I"},{"t":"m'appelle","mean":"call myself"},{"t":"Sophie","mean":"Sophie"}],"note":"Literally 'I call myself Sophie'. You can also say {{Je suis Sophie}} (I am Sophie)."},{"type":"examples","items":[{"t":"Comment vous appelez-vous ?","tr":"koh-mahn voo-zah-play-VOO","mean":"What's your name? (polite)"},{"t":"Tu t'appelles comment ?","tr":"tew tah-PEL koh-MAHN","mean":"What's your name? (friendly)"},{"t":"Je m'appelle Tom.","tr":"zhuh mah-PEL TOM","mean":"My name is Tom."},{"t":"Moi, c'est Sam.","tr":"mwah, seh SAM","mean":"I'm Sam.","note":"Relaxed and very common."},{"t":"Enchanté. / Enchantée.","tr":"ahn-shahn-TAY","mean":"Nice to meet you.","note":"Women add -e in writing. It sounds the same."}],"title":"Names"},{"type":"tip","kind":"memory","text":"{{appeler}} means 'to call'. It's in the same family as the English word **appellation**, a name."},{"type":"vocab","items":[{"t":"la France","tr":"lah FRAHNS","mean":"France"},{"t":"français / française","tr":"frahn-SEH / frahn-SEZ","mean":"French (man / woman)"},{"t":"l'Angleterre","tr":"lahn-gluh-TEHR","mean":"England"},{"t":"anglais / anglaise","tr":"ahn-GLEH / ahn-GLEZ","mean":"English (man / woman)"},{"t":"les États-Unis","tr":"lay-zay-tah-zew-NEE","mean":"the United States"},{"t":"américain / américaine","tr":"ah-may-ree-KAN / ah-may-ree-KEN","mean":"American (man / woman)"},{"t":"le Canada","tr":"luh kah-nah-DAH","mean":"Canada"},{"t":"canadien / canadienne","tr":"kah-nah-DYAN / kah-nah-DYEN","mean":"Canadian (man / woman)"},{"t":"l'Inde","tr":"LAND","mean":"India"},{"t":"indien / indienne","tr":"an-DYAN / an-DYEN","mean":"Indian (man / woman)"},{"t":"l'Australie","tr":"loh-strah-LEE","mean":"Australia"},{"t":"australien / australienne","tr":"oh-strah-LYAN / oh-strah-LYEN","mean":"Australian (man / woman)"}],"title":"Countries & nationalities"},{"type":"tip","kind":"warn","text":"Nationalities take **no capital letter** after {{être}}: {{Je suis anglais}}. Countries do: {{l'Angleterre}}."},{"type":"examples","items":[{"t":"Vous venez d'où ?","tr":"voo vuh-nay DOO","mean":"Where are you from? (polite)"},{"t":"Tu viens d'où ?","tr":"tew vyan DOO","mean":"Where are you from? (friendly)"},{"t":"Je viens de Londres.","tr":"zhuh vyan duh LOHNDR","mean":"I'm from London."},{"t":"Je suis américaine.","tr":"zhuh swee-zah-may-ree-KEN","mean":"I'm American. (woman)"},{"t":"J'habite à Paris.","tr":"zhah-BEET ah pah-REE","mean":"I live in Paris."}],"title":"Where are you from?"},{"type":"sentence","t":"J'ai vingt-cinq ans.","tr":"zhay van-san-KAHN","mean":"I'm twenty-five.","words":[{"t":"J'ai","mean":"I have"},{"t":"vingt-cinq","mean":"twenty-five"},{"t":"ans","mean":"years"}],"note":"In French you **have** your age: 'I have 25 years'. Never say {{je suis 25}}."},{"type":"examples","items":[{"t":"Tu as quel âge ?","tr":"tew ah kel AHZH","mean":"How old are you?"},{"t":"J'ai seize ans.","tr":"zhay seh-ZAHN","mean":"I'm sixteen."},{"t":"J'ai trente ans.","tr":"zhay trahn-TAHN","mean":"I'm thirty."}],"title":"Your age"},{"type":"dialogue","lines":[{"who":"Léa","t":"Salut ! Je m'appelle Léa. Et toi ?","tr":"sah-LEW. zhuh mah-PEL lay-AH. ay TWAH","mean":"Hi! My name's Léa. And you?"},{"who":"Sam","t":"Moi, c'est Sam. Enchanté !","tr":"mwah, seh SAM. ahn-shahn-TAY","mean":"I'm Sam. Nice to meet you!"},{"who":"Léa","t":"Tu viens d'où, Sam ?","tr":"tew vyan DOO, SAM","mean":"Where are you from, Sam?"},{"who":"Sam","t":"Je suis canadien. J'habite à Toronto.","tr":"zhuh swee kah-nah-DYAN. zhah-BEET ah toh-rohn-TOH","mean":"I'm Canadian. I live in Toronto."},{"who":"Léa","t":"Moi, je suis française, de Lyon.","tr":"mwah, zhuh swee frahn-SEZ, duh lee-OHN","mean":"I'm French, from Lyon."},{"who":"Sam","t":"Super ! Tu as quel âge ?","tr":"sew-PEHR. tew ah kel AHZH","mean":"Great! How old are you?"},{"who":"Léa","t":"J'ai dix-neuf ans.","tr":"zhay deez-nuh-VAHN","mean":"I'm nineteen."}],"title":"At a language café"},{"type":"tip","kind":"tip","text":"{{Et toi ?}} and {{Et vous ?}} (and you?) are the easiest way to keep a conversation going."},{"type":"practice","text":"Say these lines aloud, then make them true for you.","lines":["Bonjour, je m'appelle Alex.","Enchanté !","Je viens de Manchester.","Je suis anglaise.","J'ai dix-huit ans.","J'habite à Bruxelles."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"How do you say 'My name is Tom'?","options":["Je m'appelle Tom.","Je suis appelle Tom.","Mon appelle Tom.","J'ai nom Tom."],"answer":0},{"q":"How do you say 'I'm 20 years old'?","options":["Je suis vingt ans.","Je vingt ans.","J'ai vingt ans.","J'ai vingt années."],"answer":2,"explain":"Use {{avoir}} for age: I **have** 20 years."},{"q":"Listen. What is this person saying?","say":"Enchantée !","options":["See you later.","Nice to meet you.","I'm very sorry.","Where are you from?"],"answer":1},{"q":"A woman from France says: Je suis ___.","options":["française","français","France","Française"],"answer":0,"explain":"Feminine ending -e, and no capital letter."},{"q":"What does this mean?","t":"Tu viens d'où ?","options":["Where are you going?","Where do you work?","Where are you from?","How old are you?"],"answer":2},{"q":"Listen. What does the speaker tell you?","say":"J'habite à Paris.","options":["Their name","Their age","Their nationality","Where they live"],"answer":3}]}]},{"id":"u3-numbers-20","icon":"20","title":"Numbers 0–20","subtitle":"Count, listen and use your first numbers","minutes":12,"goals":["Count from 0 to 20","Recognise numbers when you hear them","Use numbers in short phrases"],"blocks":[{"type":"text","text":"Numbers are everywhere: prices, phone numbers, ages, bus lines. The good news: 0 to 16 are single words you simply learn, and 17 to 19 build themselves."},{"type":"vocab","items":[{"t":"zéro","tr":"zay-ROH","mean":"0 (zero)"},{"t":"un / une","tr":"AN / EWN","mean":"1 (one), masculine / feminine","example":{"t":"une pomme","tr":"ewn POM","mean":"one apple"}},{"t":"deux","tr":"DUH","mean":"2 (two)"},{"t":"trois","tr":"TRWAH","mean":"3 (three)"},{"t":"quatre","tr":"KAHTR","mean":"4 (four)"},{"t":"cinq","tr":"SANK","mean":"5 (five)"},{"t":"six","tr":"SEESS","mean":"6 (six)"},{"t":"sept","tr":"SET","mean":"7 (seven)","root":"The P is silent"},{"t":"huit","tr":"WEET","mean":"8 (eight)"},{"t":"neuf","tr":"NUHF","mean":"9 (nine)"},{"t":"dix","tr":"DEESS","mean":"10 (ten)"}],"title":"0 to 10"},{"type":"tip","kind":"warn","text":"The last sound of {{six, huit, dix}} changes before a noun: {{six}} alone is 'seess', but {{six livres}} is 'see LEEVR' and {{six amis}} is 'see-zah-MEE'. Don't worry: people understand you either way."},{"type":"vocab","items":[{"t":"onze","tr":"OHNZ","mean":"11 (eleven)"},{"t":"douze","tr":"DOOZ","mean":"12 (twelve)"},{"t":"treize","tr":"TREZ","mean":"13 (thirteen)"},{"t":"quatorze","tr":"kah-TORZ","mean":"14 (fourteen)"},{"t":"quinze","tr":"KANZ","mean":"15 (fifteen)"},{"t":"seize","tr":"SEZ","mean":"16 (sixteen)"}],"title":"11 to 16"},{"type":"vocab","items":[{"t":"dix-sept","tr":"dee-SET","mean":"17 (ten-seven)"},{"t":"dix-huit","tr":"dee-ZWEET","mean":"18 (ten-eight)"},{"t":"dix-neuf","tr":"deez-NUHF","mean":"19 (ten-nine)"},{"t":"vingt","tr":"VAN","mean":"20 (twenty)","root":"The G and T are silent"}],"title":"17 to 20"},{"type":"tip","kind":"memory","text":"17, 18 and 19 are simple maths: {{dix-sept}} = ten-seven, {{dix-huit}} = ten-eight, {{dix-neuf}} = ten-nine."},{"type":"compare","items":[{"t":"deux","label":"2: short 'uh'","desc":"No sound at the end. Round your lips and say 'duh'."},{"t":"douze","label":"12: 'oo' + z","desc":"An 'oo' sound with a buzzing z at the end."},{"t":"seize","label":"16: 'eh' + z","desc":"Rhymes with {{treize}} (13). Don't confuse it with {{six}} (6)."}],"title":"Don't mix them up"},{"type":"examples","items":[{"t":"J'ai deux frères.","tr":"zhay duh FREHR","mean":"I have two brothers."},{"t":"Le bus numéro douze.","tr":"luh bewss new-may-roh DOOZ","mean":"The number 12 bus."},{"t":"Elle a dix-sept ans.","tr":"el ah dee-seh-TAHN","mean":"She's seventeen."},{"t":"Il y a onze joueurs.","tr":"eel-yah ohnz zhoo-UHR","mean":"There are eleven players."}],"title":"Numbers in action"},{"type":"tip","kind":"fun","text":"{{neuf}} means both **nine** and **new**! Before {{ans}} (years) and {{heures}} (hours), its F sounds like a V: {{neuf ans}} = 'nuh-VAHN'."},{"type":"practice","text":"Count aloud from 0 to 20, then try it backwards!","lines":["zéro, un, deux, trois, quatre, cinq","six, sept, huit, neuf, dix","onze, douze, treize, quatorze, quinze, seize","dix-sept, dix-huit, dix-neuf, vingt"]},{"type":"dictation","items":[{"t":"quatorze","tr":"kah-TORZ","mean":"14"},{"t":"onze","tr":"OHNZ","mean":"11"},{"t":"dix-neuf","tr":"deez-NUHF","mean":"19"},{"t":"six","tr":"SEESS","mean":"6"},{"t":"treize","tr":"TREZ","mean":"13"}],"title":"Listen and write"},{"type":"quiz","title":"Quick quiz","items":[{"q":"Listen. Which number do you hear?","say":"quinze","options":["5","50","15","14"],"answer":2},{"q":"How do you write 12 in French?","options":["deux","treize","douze","doux"],"answer":2},{"q":"What number is this?","t":"dix-huit","options":["18","10","8","19"],"answer":0},{"q":"Listen. Which number?","say":"seize","options":["16","6","7","13"],"answer":0},{"q":"What is {{trois + quatre}}?","options":["six","huit","cinq","sept"],"answer":3},{"q":"What number is {{vingt}}?","options":["12","2","20","15"],"answer":2},{"q":"How do you say 'I'm nine years old'?","options":["Je suis neuf ans.","J'ai neuf ans.","Je neuf ans.","J'ai ans neuf."],"answer":1}]}]},{"id":"u3-numbers-100","icon":"€","title":"Numbers to 100 & Prices","subtitle":"Tens, the famous 70-80-90, and euros","minutes":15,"goals":["Count by tens up to 100","Understand 70, 80 and 90","Read and say prices in euros"],"blocks":[{"type":"text","text":"From 20 to 69, French numbers are regular. Then come 70, 80 and 90, where French does a little maths. Once you see the trick, you can read any price."},{"type":"vocab","items":[{"t":"vingt","tr":"VAN","mean":"20"},{"t":"trente","tr":"TRAHNT","mean":"30"},{"t":"quarante","tr":"kah-RAHNT","mean":"40"},{"t":"cinquante","tr":"san-KAHNT","mean":"50"},{"t":"soixante","tr":"swah-SAHNT","mean":"60"},{"t":"soixante-dix","tr":"swah-sahnt-DEESS","mean":"70 (sixty-ten)"},{"t":"quatre-vingts","tr":"kah-truh-VAN","mean":"80 (four twenties)"},{"t":"quatre-vingt-dix","tr":"kah-truh-van-DEESS","mean":"90 (four twenties + ten)"},{"t":"cent","tr":"SAHN","mean":"100"}],"title":"The tens"},{"type":"rule","name":"Building 21 to 69","color":"blue","desc":"Tens + hyphen + units. For 21, 31, 41, 51 and 61, say {{et un}} (and one) instead.","examples":[{"t":"vingt et un","tr":"van-tay-AN"},{"t":"vingt-deux","tr":"vant-DUH"},{"t":"trente-cinq","tr":"trahnt-SANK"},{"t":"quarante-huit","tr":"kah-rahn-TWEET"},{"t":"soixante et un","tr":"swah-sahn-tay-AN"}]},{"type":"examples","items":[{"t":"soixante-dix","tr":"swah-sahnt-DEESS","mean":"70 = 60 + 10"},{"t":"soixante et onze","tr":"swah-sahn-tay-OHNZ","mean":"71 = 60 + 11"},{"t":"soixante-quinze","tr":"swah-sahnt-KANZ","mean":"75 = 60 + 15"},{"t":"quatre-vingts","tr":"kah-truh-VAN","mean":"80 = 4 × 20"},{"t":"quatre-vingt-un","tr":"kah-truh-van-AN","mean":"81 = 4 × 20 + 1","note":"No {{et}} here!"},{"t":"quatre-vingt-dix-sept","tr":"kah-truh-van-dee-SET","mean":"97 = 4 × 20 + 17"}],"title":"70 to 99: French maths"},{"type":"tip","kind":"memory","text":"After 60, keep counting with 10 to 19: {{soixante-dix, soixante et onze, soixante-douze...}} After 80, do it again: {{quatre-vingt-dix, quatre-vingt-onze...}}"},{"type":"tip","kind":"warn","text":"{{quatre-vingts}} (80) has an **s**, but it drops when another number follows: {{quatre-vingt-trois}} (83)."},{"type":"tip","kind":"culture","text":"In Belgium and Switzerland people say {{septante}} (70) and {{nonante}} (90), and in parts of Switzerland {{huitante}} (80). Much easier! In France, use the forms above."},{"type":"vocab","items":[{"t":"un euro","tr":"an nuh-ROH","mean":"one euro"},{"t":"un centime","tr":"an sahn-TEEM","mean":"one cent"},{"t":"C'est combien ?","tr":"seh kohm-BYAN","mean":"How much is it?"},{"t":"Ça coûte...","tr":"sah KOOT","mean":"It costs..."},{"t":"Ça fait...","tr":"sah FEH","mean":"That comes to..."},{"t":"cher / chère","tr":"SHEHR","mean":"expensive"},{"t":"pas cher","tr":"pah SHEHR","mean":"cheap, not expensive"},{"t":"l'addition","tr":"lah-dee-SYOHN","mean":"the bill (in a restaurant)"}],"title":"Money words"},{"type":"tip","kind":"tip","text":"French prices use a comma: {{2,50 €}}. Say it as {{deux euros cinquante}}. People usually drop the word {{centimes}}."},{"type":"examples","items":[{"t":"deux euros cinquante","tr":"duh-zuh-roh san-KAHNT","mean":"€2.50"},{"t":"un euro vingt","tr":"an nuh-roh VAN","mean":"€1.20"},{"t":"quinze euros","tr":"kan-zuh-ROH","mean":"€15"},{"t":"neuf euros quatre-vingt-dix-neuf","tr":"nuh-fuh-roh kah-truh-van-deez-NUHF","mean":"€9.99"},{"t":"soixante-quatorze euros","tr":"swah-sahnt-kah-tor-zuh-ROH","mean":"€74"}],"title":"Prices"},{"type":"sentence","t":"C'est combien, le croissant ?","tr":"seh kohm-BYAN, luh krwah-SAHN","mean":"How much is the croissant?","words":[{"t":"C'est","mean":"it is"},{"t":"combien","mean":"how much"},{"t":"le","mean":"the"},{"t":"croissant","mean":"croissant"}]},{"type":"dialogue","lines":[{"who":"Client","t":"Bonjour ! Les tomates, c'est combien ?","tr":"bohn-ZHOOR. lay toh-MAHT, seh kohm-BYAN","mean":"Hello! How much are the tomatoes?"},{"who":"Seller","t":"Trois euros le kilo.","tr":"trwah-zuh-ROH luh kee-LOH","mean":"Three euros a kilo."},{"who":"Client","t":"Un kilo, s'il vous plaît. Et deux citrons.","tr":"an kee-LOH, seel voo PLEH. ay duh see-TROHN","mean":"One kilo, please. And two lemons."},{"who":"Seller","t":"Ça fait quatre euros vingt.","tr":"sah feh kah-truh-roh VAN","mean":"That's €4.20."},{"who":"Client","t":"Voilà cinq euros.","tr":"vwah-LAH san-kuh-ROH","mean":"Here's five euros."},{"who":"Seller","t":"Et quatre-vingts centimes. Merci !","tr":"ay kah-truh-van sahn-TEEM. mehr-SEE","mean":"And 80 cents change. Thank you!"}],"title":"At the market"},{"type":"practice","text":"Read these numbers and prices aloud.","lines":["trente, quarante, cinquante, soixante","soixante-dix, quatre-vingts, quatre-vingt-dix, cent","vingt et un, trente-deux, quarante-trois","C'est combien ?","Ça fait douze euros cinquante."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"What number is {{quatre-vingts}}?","options":["24","84","90","80"],"answer":3,"explain":"4 × 20 = 80."},{"q":"Listen. Which number?","say":"soixante-quinze","options":["75","65","60","57"],"answer":0,"explain":"60 + 15 = 75."},{"q":"How do you say 71?","options":["soixante-dix-un","soixante et onze","septante-un-dix","sept et dix"],"answer":1},{"q":"What does this mean?","t":"C'est combien ?","options":["What is it?","Is it far?","Who is it?","How much is it?"],"answer":3},{"q":"Listen. What's the price?","say":"douze euros cinquante","options":["€2.50","€12.15","€12.50","€20.50"],"answer":2},{"q":"How is 99 built in French?","options":["4 × 20 + 19","9 × 11","90 + 9","100 − 1"],"answer":0},{"q":"Which word means 'the bill' in a restaurant?","options":["le centime","la monnaie","l'addition","le prix"],"answer":2}]}]},{"id":"u3-dates","icon":"Lun","title":"Days, Months & Dates","subtitle":"Make plans and talk about birthdays","minutes":12,"goals":["Name the days of the week","Name the twelve months","Say today's date and your birthday"],"blocks":[{"type":"text","text":"Making plans? You need days, months and dates. Good news: French dates are simpler than English ones."},{"type":"vocab","items":[{"t":"lundi","tr":"lun-DEE","mean":"Monday","root":"Moon (lune)"},{"t":"mardi","tr":"mar-DEE","mean":"Tuesday","root":"Mars"},{"t":"mercredi","tr":"mehr-kruh-DEE","mean":"Wednesday","root":"Mercury"},{"t":"jeudi","tr":"zhuh-DEE","mean":"Thursday","root":"Jupiter"},{"t":"vendredi","tr":"vahn-druh-DEE","mean":"Friday","root":"Venus"},{"t":"samedi","tr":"sahm-DEE","mean":"Saturday"},{"t":"dimanche","tr":"dee-MAHNSH","mean":"Sunday"}],"title":"Days of the week"},{"type":"tip","kind":"memory","text":"Most days come from the planets: {{lundi}} Moon, {{mardi}} Mars, {{mercredi}} Mercury, {{jeudi}} Jupiter, {{vendredi}} Venus. All but {{dimanche}} end in **-di**, from Latin *dies* (day)."},{"type":"tip","kind":"warn","text":"Days and months take **no capital letter** in French: {{lundi}}, {{janvier}}."},{"type":"vocab","items":[{"t":"janvier","tr":"zhahn-VYAY","mean":"January"},{"t":"février","tr":"fay-vree-YAY","mean":"February"},{"t":"mars","tr":"MARSS","mean":"March"},{"t":"avril","tr":"ah-VREEL","mean":"April"},{"t":"mai","tr":"MEH","mean":"May"},{"t":"juin","tr":"ZHWAN","mean":"June"},{"t":"juillet","tr":"zhwee-YEH","mean":"July"},{"t":"août","tr":"OOT","mean":"August","root":"Often just 'oo'"},{"t":"septembre","tr":"sep-TAHMBR","mean":"September"},{"t":"octobre","tr":"ok-TOBR","mean":"October"},{"t":"novembre","tr":"noh-VAHMBR","mean":"November"},{"t":"décembre","tr":"day-SAHMBR","mean":"December"}],"title":"Months"},{"type":"tip","kind":"warn","text":"{{juin}} (June) and {{juillet}} (July) sound close. Listen to the end: 'zhwan' versus 'zhwee-YEH'."},{"type":"rule","name":"Saying the date","color":"green","desc":"{{le}} + number + month. Use ordinary numbers, except for the 1st: {{le premier}}.","how":"Today is... = {{On est le...}} or {{Nous sommes le...}}","examples":[{"t":"le quatorze juillet","tr":"luh kah-torz zhwee-YEH"},{"t":"le premier mai","tr":"luh pruh-myay MEH"},{"t":"le vingt-cinq décembre","tr":"luh vant-sank day-SAHMBR"},{"t":"le trois mars","tr":"luh trwah MARSS"}]},{"type":"vocab","items":[{"t":"aujourd'hui","tr":"oh-zhoor-DWEE","mean":"today"},{"t":"demain","tr":"duh-MAN","mean":"tomorrow"},{"t":"hier","tr":"ee-YEHR","mean":"yesterday"},{"t":"la semaine","tr":"lah suh-MEN","mean":"the week"},{"t":"le week-end","tr":"luh wee-KEND","mean":"the weekend"},{"t":"le mois","tr":"luh MWAH","mean":"the month"},{"t":"l'année","tr":"lah-NAY","mean":"the year"}],"title":"Useful time words"},{"type":"sentence","t":"Mon anniversaire, c'est le dix mai.","tr":"moh-nah-nee-vehr-SEHR, seh luh dee MEH","mean":"My birthday is on the tenth of May.","words":[{"t":"Mon","mean":"my"},{"t":"anniversaire","mean":"birthday"},{"t":"c'est","mean":"it is"},{"t":"le","mean":"the"},{"t":"dix","mean":"ten"},{"t":"mai","mean":"May"}]},{"type":"examples","items":[{"t":"Le lundi, j'ai sport.","tr":"luh lun-DEE, zhay SPOR","mean":"On Mondays, I have sport.","note":"{{le}} + day = every Monday."},{"t":"Lundi, je vais à Paris.","tr":"lun-DEE, zhuh veh ah pah-REE","mean":"On Monday, I'm going to Paris.","note":"No article = this coming Monday."}],"title":"Le lundi or lundi?"},{"type":"dialogue","lines":[{"who":"Anna","t":"On est le combien aujourd'hui ?","tr":"ohn-neh luh kohm-BYAN oh-zhoor-DWEE","mean":"What's the date today?"},{"who":"Marc","t":"On est le premier avril.","tr":"ohn-neh luh pruh-myay-rah-VREEL","mean":"It's the first of April."},{"who":"Anna","t":"Le premier avril ? C'est mon anniversaire !","tr":"luh pruh-myay-rah-VREEL? seh moh-nah-nee-vehr-SEHR","mean":"The first of April? It's my birthday!"},{"who":"Marc","t":"Vraiment ? Ce n'est pas un poisson d'avril ?","tr":"vreh-MAHN? suh neh pah-zan pwah-sohn dah-VREEL","mean":"Really? It's not an April Fool's joke?"},{"who":"Anna","t":"Non ! Je suis née le premier avril.","tr":"NOHN. zhuh swee NAY luh pruh-myay-rah-VREEL","mean":"No! I was born on the first of April."},{"who":"Marc","t":"Alors, joyeux anniversaire !","tr":"ah-LOR, zhwah-yuh-zah-nee-vehr-SEHR","mean":"Well then, happy birthday!"}]},{"type":"tip","kind":"culture","text":"On 1 April, French children try to stick a paper fish on people's backs without being noticed: a {{poisson d'avril}} (April fish)!"},{"type":"practice","text":"Say the days and months in order, then the dates.","lines":["lundi, mardi, mercredi, jeudi, vendredi, samedi, dimanche","janvier, février, mars, avril, mai, juin","juillet, août, septembre, octobre, novembre, décembre","Aujourd'hui, on est le premier juin.","Mon anniversaire, c'est le vingt mars."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Which day comes after {{mardi}}?","options":["jeudi","lundi","mercredi","dimanche"],"answer":2},{"q":"Listen. Which day is it?","say":"jeudi","options":["Tuesday","Thursday","Wednesday","Saturday"],"answer":1},{"q":"How do you say 'the 1st of May'?","options":["le premier mai","le un mai","le une mai","la première mai"],"answer":0,"explain":"Only the 1st uses {{premier}}; all other dates use plain numbers."},{"q":"Which month is {{août}}?","options":["April","October","August","July"],"answer":2},{"q":"What does {{demain}} mean?","options":["tomorrow","yesterday","today","next week"],"answer":0},{"q":"Which is written correctly in a French sentence?","options":["le 3 Mars","le Mars 3","Le 3 de Mars","le 3 mars"],"answer":3,"explain":"No capital letters for months."},{"q":"Listen. Which date is it?","say":"le quatorze juillet","options":["14 July","4 July","14 June","24 July"],"answer":0,"explain":"France's national day!"}]}]},{"id":"u3-time","icon":"h","title":"Telling the Time","subtitle":"Hours, quarters, halves and the 24-hour clock","minutes":14,"goals":["Ask and say the time","Use et quart, et demie and moins le quart","Understand the 24-hour clock"],"blocks":[{"type":"text","text":"{{Quelle heure est-il ?}} means 'What time is it?'. French uses {{heure}} (hour) for every time, and the 24-hour clock is very common for trains, shops and TV."},{"type":"sentence","t":"Il est trois heures.","tr":"eel eh trwah-ZUHR","mean":"It's three o'clock.","words":[{"t":"Il","mean":"it"},{"t":"est","mean":"is"},{"t":"trois","mean":"three"},{"t":"heures","mean":"hours"}],"note":"Always say {{heures}}, even when English says nothing: 'It is three hours'."},{"type":"examples","items":[{"t":"Quelle heure est-il ?","tr":"kel uh-reh-TEEL","mean":"What time is it?"},{"t":"Il est quelle heure ?","tr":"eel eh kel UHR","mean":"What time is it? (relaxed)"},{"t":"Vous avez l'heure ?","tr":"voo-zah-vay LUHR","mean":"Do you have the time?"}],"title":"Asking the time"},{"type":"examples","items":[{"t":"Il est une heure.","tr":"eel eh-tew-NUHR","mean":"It's one o'clock.","note":"{{une}}, because {{heure}} is feminine."},{"t":"Il est deux heures.","tr":"eel eh duh-ZUHR","mean":"It's two o'clock."},{"t":"Il est midi.","tr":"eel eh mee-DEE","mean":"It's noon."},{"t":"Il est minuit.","tr":"eel eh mee-NWEE","mean":"It's midnight."}],"title":"On the hour"},{"type":"examples","items":[{"t":"Il est trois heures dix.","tr":"eel eh trwah-zuhr DEESS","mean":"3:10"},{"t":"Il est trois heures et quart.","tr":"eel eh trwah-zuhr ay KAR","mean":"3:15 (quarter past)"},{"t":"Il est trois heures et demie.","tr":"eel eh trwah-zuhr ay duh-MEE","mean":"3:30 (half past)"},{"t":"Il est quatre heures moins le quart.","tr":"eel eh kah-truhr mwan luh KAR","mean":"3:45 (quarter to four)"},{"t":"Il est quatre heures moins dix.","tr":"eel eh kah-truhr mwan DEESS","mean":"3:50 (ten to four)"}],"title":"Minutes, quarters and halves"},{"type":"tip","kind":"memory","text":"{{moins}} means **minus**: {{quatre heures moins dix}} = four o'clock minus ten = 3:50."},{"type":"table","head":["Time","Everyday French","Official (trains, shops)"],"rows":[["8:00 am","{{huit heures (du matin)}}","{{huit heures}}"],["2:00 pm","{{deux heures (de l'après-midi)}}","{{quatorze heures}}"],["6:30 pm","{{six heures et demie (du soir)}}","{{dix-huit heures trente}}"],["9:15 pm","{{neuf heures et quart (du soir)}}","{{vingt et une heures quinze}}"]],"title":"The 24-hour clock"},{"type":"tip","kind":"tip","text":"With the 24-hour clock, use plain minutes: {{trente}} (30) and {{quinze}} (15), not {{et demie}} or {{et quart}}."},{"type":"vocab","items":[{"t":"le matin","tr":"luh mah-TAN","mean":"the morning"},{"t":"l'après-midi","tr":"lah-preh-mee-DEE","mean":"the afternoon"},{"t":"le soir","tr":"luh SWAHR","mean":"the evening"},{"t":"la nuit","tr":"lah NWEE","mean":"the night"},{"t":"tôt","tr":"TOH","mean":"early"},{"t":"tard","tr":"TAR","mean":"late"},{"t":"en retard","tr":"ahn ruh-TAR","mean":"late (for something)","example":{"t":"Je suis en retard !","tr":"zhuh swee-zahn ruh-TAR","mean":"I'm late!"}},{"t":"à l'heure","tr":"ah LUHR","mean":"on time"},{"t":"une demi-heure","tr":"ewn duh-mee-UHR","mean":"half an hour"}],"title":"Time words"},{"type":"sentence","t":"Le train part à dix-huit heures.","tr":"luh tran par ah dee-zwee-TUHR","mean":"The train leaves at 6 pm.","words":[{"t":"Le","mean":"the"},{"t":"train","mean":"train"},{"t":"part","mean":"leaves"},{"t":"à","mean":"at"},{"t":"dix-huit","mean":"eighteen"},{"t":"heures","mean":"hours"}],"note":"Use {{à}} for 'at' a time."},{"type":"dialogue","lines":[{"who":"Tom","t":"Excusez-moi, vous avez l'heure ?","tr":"ex-kew-zay-MWAH, voo-zah-vay LUHR","mean":"Excuse me, do you have the time?"},{"who":"Woman","t":"Oui, il est midi moins le quart.","tr":"WEE, eel eh mee-dee mwan luh KAR","mean":"Yes, it's quarter to twelve."},{"who":"Tom","t":"Merci ! Le musée ferme à quelle heure ?","tr":"mehr-SEE. luh mew-ZAY fehrm ah kel UHR","mean":"Thanks! What time does the museum close?"},{"who":"Woman","t":"À dix-sept heures trente, je crois.","tr":"ah dee-seh-tuhr TRAHNT, zhuh KRWAH","mean":"At 5:30 pm, I think."},{"who":"Tom","t":"Parfait, j'ai le temps !","tr":"par-FEH, zhay luh TAHN","mean":"Perfect, I have time!"}]},{"type":"practice","text":"Read the times aloud.","lines":["Quelle heure est-il ?","Il est une heure.","Il est six heures et quart.","Il est neuf heures et demie.","Il est midi moins le quart.","Le film commence à vingt heures."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"How do you say 'It's 2:30'?","options":["Il est deux heures et quart.","Il est deux heures moins le quart.","Il est deux heures et demie.","Il est demie deux heures."],"answer":2},{"q":"Listen. What time is it?","say":"Il est huit heures moins le quart.","options":["8:15","8:45","7:45","7:15"],"answer":2,"explain":"Eight o'clock minus a quarter = 7:45."},{"q":"{{dix-neuf heures}} is...","options":["9 pm","9 am","10 pm","7 pm"],"answer":3,"explain":"19 − 12 = 7, so 7 pm."},{"q":"Why do we say {{une heure}}, not {{un heure}}?","options":["Un is only used for money.","Une is the plural of un.","Heure is a feminine noun."],"answer":2},{"q":"Listen. What does it mean?","say":"minuit","options":["noon","one o'clock","midnight","half past"],"answer":2},{"q":"What does {{le soir}} mean?","options":["the morning","the afternoon","the evening","the weekend"],"answer":2},{"q":"How do you say 'at five o'clock'?","options":["dans cinq heures","en cinq heures","à cinq heures","il cinq heures"],"answer":2,"explain":"{{dans cinq heures}} means 'in five hours' (from now)."}]}]},{"id":"u3-family","icon":"Pa","title":"Family","subtitle":"Talk about the people closest to you","minutes":12,"goals":["Name family members","Say 'my' with mon, ma and mes","Describe your family in a few sentences"],"blocks":[{"type":"text","text":"Family is a favourite topic in any first conversation. Learn the words, then use {{mon}}, {{ma}} and {{mes}} (my) to talk about your own."},{"type":"vocab","items":[{"t":"la famille","tr":"lah fah-MEEY","mean":"the family"},{"t":"le père","tr":"luh PEHR","mean":"the father"},{"t":"la mère","tr":"lah MEHR","mean":"the mother"},{"t":"les parents","tr":"lay pah-RAHN","mean":"the parents (also: relatives)"},{"t":"le frère","tr":"luh FREHR","mean":"the brother"},{"t":"la sœur","tr":"lah SUHR","mean":"the sister"},{"t":"le fils","tr":"luh FEESS","mean":"the son"},{"t":"la fille","tr":"lah FEEY","mean":"the daughter / the girl"},{"t":"l'enfant","tr":"lahn-FAHN","mean":"the child"},{"t":"le mari","tr":"luh mah-REE","mean":"the husband"},{"t":"la femme","tr":"lah FAHM","mean":"the wife / the woman"}],"title":"Close family"},{"type":"tip","kind":"warn","text":"{{fils}} (son) sounds like 'feess': the L is silent and the S is pronounced. {{fille}} (daughter) sounds like 'feey': the double L sounds like 'y'."},{"type":"vocab","items":[{"t":"le grand-père","tr":"luh grahn-PEHR","mean":"the grandfather"},{"t":"la grand-mère","tr":"lah grahn-MEHR","mean":"the grandmother"},{"t":"les grands-parents","tr":"lay grahn-pah-RAHN","mean":"the grandparents"},{"t":"l'oncle","tr":"LOHNKL","mean":"the uncle"},{"t":"la tante","tr":"lah TAHNT","mean":"the aunt"},{"t":"le cousin / la cousine","tr":"luh koo-ZAN / lah koo-ZEEN","mean":"the cousin (male / female)"},{"t":"le neveu","tr":"luh nuh-VUH","mean":"the nephew"},{"t":"la nièce","tr":"lah NYESS","mean":"the niece"}],"title":"The wider family"},{"type":"tip","kind":"fun","text":"Children call their parents {{papa}} and {{maman}}, and their grandparents {{papi}} and {{mamie}}."},{"type":"table","head":["Before...","'my' is...","Example"],"rows":[["a masculine noun","{{mon}}","{{mon père}} (my father)"],["a feminine noun","{{ma}}","{{ma mère}} (my mother)"],["a plural noun","{{mes}}","{{mes parents}} (my parents)"],["a feminine noun starting with a vowel","{{mon}}","{{mon amie}} (my friend, female)"]],"title":"My: mon, ma, mes"},{"type":"tip","kind":"tip","text":"'Your' (friendly) works the same way: {{ton frère, ta sœur, tes cousins}}. You'll meet all the possessives in Unit 4."},{"type":"sentence","t":"J'ai une sœur et deux frères.","tr":"zhay ewn SUHR ay duh FREHR","mean":"I have one sister and two brothers.","words":[{"t":"J'ai","mean":"I have"},{"t":"une","mean":"one / a"},{"t":"sœur","mean":"sister"},{"t":"et","mean":"and"},{"t":"deux","mean":"two"},{"t":"frères","mean":"brothers"}]},{"type":"examples","items":[{"t":"Tu as des frères et sœurs ?","tr":"tew ah day frehr ay SUHR","mean":"Do you have brothers and sisters?"},{"t":"Je suis fils unique.","tr":"zhuh swee fee-sew-NEEK","mean":"I'm an only child. (boy)"},{"t":"Je suis fille unique.","tr":"zhuh swee fee-yew-NEEK","mean":"I'm an only child. (girl)"},{"t":"Ma mère s'appelle Claire.","tr":"mah mehr sah-pel KLEHR","mean":"My mother's name is Claire."},{"t":"Mes grands-parents habitent à Nice.","tr":"may grahn-pah-RAHN ah-beet ah NEESS","mean":"My grandparents live in Nice."}]},{"type":"dialogue","lines":[{"who":"Inès","t":"C'est qui, sur la photo ?","tr":"seh KEE, sewr lah foh-TOH","mean":"Who's that in the photo?"},{"who":"Ben","t":"C'est ma famille. Voici mon père et ma mère.","tr":"seh mah fah-MEEY. vwah-SEE mohn pehr ay mah MEHR","mean":"That's my family. Here are my father and my mother."},{"who":"Inès","t":"Et la petite fille ?","tr":"ay lah puh-teet FEEY","mean":"And the little girl?"},{"who":"Ben","t":"C'est ma sœur, Zoé. Elle a six ans.","tr":"seh mah SUHR, zoh-AY. el ah see-ZAHN","mean":"That's my sister, Zoé. She's six."},{"who":"Inès","t":"Elle est mignonne ! Tu as des cousins ?","tr":"el eh mee-NYON. tew ah day koo-ZAN","mean":"She's cute! Do you have cousins?"},{"who":"Ben","t":"Oui, beaucoup ! Ma tante a cinq enfants.","tr":"WEE, boh-KOO. mah tahnt ah san-kahn-FAHN","mean":"Yes, lots! My aunt has five children."}]},{"type":"practice","text":"Describe this family aloud, then your own.","lines":["Voici ma famille.","Mon père s'appelle Paul.","Ma sœur a douze ans.","J'ai deux cousins et une cousine.","Mes grands-parents habitent à Lyon."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"How do you say 'my mother'?","options":["mon mère","mes mère","ma mère","me mère"],"answer":2},{"q":"Listen. Who is it?","say":"mon grand-père","options":["my grandfather","my grandmother","my big brother","my uncle"],"answer":0},{"q":"{{la sœur de ma mère}} is my...","options":["cousin","aunt","sister","niece"],"answer":1},{"q":"Which word means 'son'?","options":["la fille","le frère","le neveu","le fils"],"answer":3},{"q":"Complete (my): ___ parents sont sympas.","options":["Mon","Mes","Ma"],"answer":1,"explain":"{{parents}} is plural, so use {{mes}}."},{"q":"Listen. What is the question?","say":"Tu as des frères et sœurs ?","options":["Do you have brothers and sisters?","Are your parents at home today?","Is your sister older than you?","How old is your brother?"],"answer":0},{"q":"How does a girl say 'I'm an only child'?","options":["J'ai une seule fille.","Je suis fille unique.","Je suis la fille.","Je suis une fille seule."],"answer":1}]}]},{"id":"u3-food","icon":"Thé","title":"Food & Drinks","subtitle":"Order in a café and say what you like","minutes":14,"goals":["Name everyday foods and drinks","Order politely in a café","Say what you like and don't like"],"blocks":[{"type":"text","text":"Food is at the heart of French life. Learn the basics and you're ready for a café, a bakery or a market."},{"type":"vocab","items":[{"t":"le pain","tr":"luh PAN","mean":"bread"},{"t":"la baguette","tr":"lah bah-GET","mean":"baguette (long loaf)"},{"t":"le croissant","tr":"luh krwah-SAHN","mean":"croissant"},{"t":"le fromage","tr":"luh froh-MAHZH","mean":"cheese"},{"t":"le beurre","tr":"luh BUHR","mean":"butter"},{"t":"l'œuf","tr":"LUHF","mean":"egg","example":{"t":"des œufs","tr":"day-ZUH","mean":"(some) eggs"}},{"t":"la viande","tr":"lah VYAHND","mean":"meat"},{"t":"le poulet","tr":"luh poo-LEH","mean":"chicken"},{"t":"le poisson","tr":"luh pwah-SOHN","mean":"fish"},{"t":"les légumes","tr":"lay lay-GEWM","mean":"vegetables"},{"t":"les frites","tr":"lay FREET","mean":"chips / fries"},{"t":"le riz","tr":"luh REE","mean":"rice"},{"t":"les pâtes","tr":"lay PAHT","mean":"pasta"},{"t":"la pomme","tr":"lah POM","mean":"apple"},{"t":"la salade","tr":"lah sah-LAHD","mean":"salad / lettuce"}],"title":"Food"},{"type":"tip","kind":"warn","text":"{{poisson}} (fish) is 'pwah-SOHN' with a hissing S. {{poison}} (poison) is 'pwah-ZOHN' with a buzzing Z. One S or two makes a big difference!"},{"type":"vocab","items":[{"t":"l'eau","tr":"LOH","mean":"water"},{"t":"le café","tr":"luh kah-FAY","mean":"coffee"},{"t":"le thé","tr":"luh TAY","mean":"tea"},{"t":"le lait","tr":"luh LEH","mean":"milk"},{"t":"le jus d'orange","tr":"luh zhew doh-RAHNZH","mean":"orange juice"},{"t":"le vin","tr":"luh VAN","mean":"wine"},{"t":"la bière","tr":"lah BYEHR","mean":"beer"},{"t":"le chocolat chaud","tr":"luh shoh-koh-lah SHOH","mean":"hot chocolate"}],"title":"Drinks"},{"type":"tip","kind":"culture","text":"In a French café, {{un café}} is a small espresso. Want it with milk? Ask for {{un café crème}} (or just {{un crème}})."},{"type":"rule","name":"I'd like...","color":"green","desc":"To order politely, say {{Je voudrais...}} (I would like...). It's softer than {{Je veux}} (I want).","examples":[{"t":"Je voudrais un café, s'il vous plaît.","tr":"zhuh voo-DREH an kah-FAY, seel voo PLEH"},{"t":"Je voudrais de l'eau.","tr":"zhuh voo-dreh duh LOH"},{"t":"Pour moi, un thé.","tr":"poor MWAH, an TAY"}]},{"type":"examples","items":[{"t":"J'aime le chocolat.","tr":"zhem luh shoh-koh-LAH","mean":"I like chocolate."},{"t":"J'adore les frites !","tr":"zhah-dor lay FREET","mean":"I love fries!"},{"t":"Je n'aime pas le poisson.","tr":"zhuh nem pah luh pwah-SOHN","mean":"I don't like fish."},{"t":"Je préfère le thé.","tr":"zhuh pray-fehr luh TAY","mean":"I prefer tea."}],"title":"Likes and dislikes"},{"type":"tip","kind":"tip","text":"After {{aimer}}, {{adorer}} and {{préférer}}, use {{le / la / les}}: {{J'aime le fromage}} = I like cheese (in general)."},{"type":"sentence","t":"Je voudrais un croissant et un café, s'il vous plaît.","tr":"zhuh voo-DREH an krwah-SAHN ay an kah-FAY, seel voo PLEH","mean":"I'd like a croissant and a coffee, please.","words":[{"t":"Je","mean":"I"},{"t":"voudrais","mean":"would like"},{"t":"un","mean":"a"},{"t":"croissant","mean":"croissant"},{"t":"et","mean":"and"},{"t":"un","mean":"a"},{"t":"café","mean":"coffee"},{"t":"s'il","mean":"if it"},{"t":"vous","mean":"you"},{"t":"plaît","mean":"pleases"}],"note":"{{s'il vous plaît}} literally means 'if it pleases you'."},{"type":"dialogue","lines":[{"who":"Waiter","t":"Bonjour ! Qu'est-ce que je vous sers ?","tr":"bohn-ZHOOR. kes-kuh zhuh voo SEHR","mean":"Hello! What can I get you?"},{"who":"Emma","t":"Je voudrais un chocolat chaud, s'il vous plaît.","tr":"zhuh voo-DREH an shoh-koh-lah SHOH, seel voo PLEH","mean":"I'd like a hot chocolate, please."},{"who":"Waiter","t":"Et pour monsieur ?","tr":"ay poor muh-SYUH","mean":"And for you, sir?"},{"who":"Léo","t":"Pour moi, un café et un croissant.","tr":"poor MWAH, an kah-FAY ay an krwah-SAHN","mean":"For me, a coffee and a croissant."},{"who":"Waiter","t":"Très bien. Et avec ceci ?","tr":"treh BYAN. ay ah-vek suh-SEE","mean":"Very good. Anything else?"},{"who":"Léo","t":"Une carafe d'eau, s'il vous plaît.","tr":"ewn kah-rahf DOH, seel voo PLEH","mean":"A jug of tap water, please."},{"who":"Waiter","t":"Avec plaisir !","tr":"ah-vek pleh-ZEER","mean":"With pleasure!"}],"title":"At the café"},{"type":"tip","kind":"culture","text":"{{Une carafe d'eau}} is free tap water in French restaurants and cafés. Just ask!"},{"type":"practice","text":"Order these aloud, as if you're in a café.","lines":["Je voudrais un thé, s'il vous plaît.","Pour moi, un jus d'orange.","J'adore le fromage !","Je n'aime pas le café.","L'addition, s'il vous plaît."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Listen. What is it?","say":"le fromage","options":["bread","cheese","butter","milk"],"answer":1},{"q":"Which is the most polite way to order?","options":["Je veux un thé, moi.","Donne-moi un thé !","Un thé. Vite !","Je voudrais un thé."],"answer":3},{"q":"What does {{l'eau}} mean?","options":["water","milk","wine","juice"],"answer":0},{"q":"How do you say 'I don't like fish'?","options":["Je n'aime pas le poison.","Je ne pas aime le poisson.","Je n'aime pas le poisson.","Je aime ne le poisson."],"answer":2,"explain":"Careful: {{poison}} means poison!"},{"q":"In a French café, {{un café}} is...","options":["a big mug of filter coffee","a coffee with lots of milk","a small espresso","an iced coffee"],"answer":2},{"q":"Listen. What is the waiter asking?","say":"Et avec ceci ?","options":["Is that to take away?","Anything else?","Did you enjoy it?","Cash or card?"],"answer":1},{"q":"What does {{les légumes}} mean?","options":["the vegetables","the meat","the fruit","the drinks"],"answer":0}]}]},{"id":"u3-colours-clothes","icon":"Or","title":"Colours & Clothes","subtitle":"Describe what people wear","minutes":13,"goals":["Name the main colours","Name everyday clothes","Make colours agree with the noun"],"blocks":[{"type":"text","text":"Shopping for clothes or describing what someone is wearing? You need colours. In French, colours usually come **after** the noun."},{"type":"vocab","items":[{"t":"rouge","tr":"ROOZH","mean":"red"},{"t":"bleu / bleue","tr":"BLUH","mean":"blue"},{"t":"vert / verte","tr":"VEHR / VEHRT","mean":"green"},{"t":"jaune","tr":"ZHOHN","mean":"yellow"},{"t":"noir / noire","tr":"NWAHR","mean":"black"},{"t":"blanc / blanche","tr":"BLAHN / BLAHNSH","mean":"white"},{"t":"gris / grise","tr":"GREE / GREEZ","mean":"grey"},{"t":"rose","tr":"ROHZ","mean":"pink"},{"t":"violet / violette","tr":"vyoh-LEH / vyoh-LET","mean":"purple"},{"t":"orange","tr":"oh-RAHNZH","mean":"orange"},{"t":"marron","tr":"mah-ROHN","mean":"brown"}],"title":"Colours"},{"type":"rule","name":"Colours agree","color":"purple","desc":"Most colours add **-e** for feminine and **-s** for plural, like other adjectives. Colours already ending in -e ({{rouge, jaune, rose}}) don't change for feminine.","how":"{{orange}} and {{marron}} never change at all: {{des chaussures marron}}.","examples":[{"t":"un pull vert","tr":"an pewl VEHR"},{"t":"une robe verte","tr":"ewn rob VEHRT"},{"t":"des chaussettes noires","tr":"day shoh-set NWAHR"},{"t":"une chemise blanche","tr":"ewn shuh-meez BLAHNSH"},{"t":"des chaussures marron","tr":"day shoh-sewr mah-ROHN"}]},{"type":"tip","kind":"memory","text":"Noun first, colour second: {{une voiture rouge}} = 'a car red'. Name the thing, then describe it."},{"type":"vocab","items":[{"t":"le pantalon","tr":"luh pahn-tah-LOHN","mean":"trousers / pants","example":{"t":"un pantalon noir","tr":"an pahn-tah-lohn NWAHR","mean":"(a pair of) black trousers"}},{"t":"le jean","tr":"luh DJEEN","mean":"jeans"},{"t":"la chemise","tr":"lah shuh-MEEZ","mean":"shirt"},{"t":"le tee-shirt","tr":"luh tee-SHUHRT","mean":"T-shirt"},{"t":"le pull","tr":"luh PEWL","mean":"jumper / sweater"},{"t":"la robe","tr":"lah ROB","mean":"dress"},{"t":"la jupe","tr":"lah ZHEWP","mean":"skirt"},{"t":"la veste","tr":"lah VEST","mean":"jacket"},{"t":"le manteau","tr":"luh mahn-TOH","mean":"coat"},{"t":"les chaussures","tr":"lay shoh-SEWR","mean":"shoes"},{"t":"les chaussettes","tr":"lay shoh-SET","mean":"socks"},{"t":"le chapeau","tr":"luh shah-POH","mean":"hat"}],"title":"Clothes"},{"type":"tip","kind":"warn","text":"False friend! {{la veste}} is a **jacket**, not a vest. And {{un pantalon}} is one pair of trousers: it's singular in French."},{"type":"examples","items":[{"t":"Je porte un jean bleu.","tr":"zhuh port an djeen BLUH","mean":"I'm wearing blue jeans."},{"t":"Elle porte une robe rouge.","tr":"el port ewn rob ROOZH","mean":"She's wearing a red dress."},{"t":"Il a un manteau noir.","tr":"eel ah an mahn-toh NWAHR","mean":"He has a black coat."},{"t":"Tu aimes ma veste ?","tr":"tew em mah VEST","mean":"Do you like my jacket?"}],"title":"What are you wearing?"},{"type":"sentence","t":"Je cherche une chemise blanche.","tr":"zhuh shehrsh ewn shuh-meez BLAHNSH","mean":"I'm looking for a white shirt.","words":[{"t":"Je","mean":"I"},{"t":"cherche","mean":"am looking for"},{"t":"une","mean":"a"},{"t":"chemise","mean":"shirt"},{"t":"blanche","mean":"white"}],"note":"{{chemise}} is feminine, so {{blanc}} becomes {{blanche}}."},{"type":"dialogue","lines":[{"who":"Assistant","t":"Bonjour ! Je peux vous aider ?","tr":"bohn-ZHOOR. zhuh puh voo-zeh-DAY","mean":"Hello! Can I help you?"},{"who":"Client","t":"Oui, je cherche un pull.","tr":"WEE, zhuh shehrsh an PEWL","mean":"Yes, I'm looking for a jumper."},{"who":"Assistant","t":"De quelle couleur ?","tr":"duh kel koo-LUHR","mean":"What colour?"},{"who":"Client","t":"Bleu ou gris.","tr":"bluh oo GREE","mean":"Blue or grey."},{"who":"Assistant","t":"Vous faites quelle taille ?","tr":"voo fet kel TAHY","mean":"What size are you?"},{"who":"Client","t":"Du M. Je peux l'essayer ?","tr":"dew EM. zhuh puh leh-seh-YAY","mean":"Medium. Can I try it on?"},{"who":"Assistant","t":"Bien sûr, la cabine est là-bas.","tr":"byan SEWR, lah kah-BEEN eh lah-BAH","mean":"Of course, the fitting room is over there."}],"title":"In a shop"},{"type":"practice","text":"Describe each outfit aloud.","lines":["un tee-shirt blanc et un jean bleu","une robe verte et des chaussures noires","un manteau gris et un chapeau rouge","Je porte une veste marron.","Ma sœur porte une jupe jaune."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"How do you say 'a green dress'?","options":["une verte robe","une robe verte","une robe vert","un robe verte"],"answer":1},{"q":"Listen. Which colour?","say":"noir","options":["white","brown","grey","black"],"answer":3},{"q":"What is {{la veste}}?","options":["a vest","a skirt","a jacket","a scarf"],"answer":2,"explain":"False friend: {{veste}} = jacket."},{"q":"Which colour never changes its form?","options":["marron","vert","blanc","gris"],"answer":0},{"q":"How do you say 'white shoes'?","options":["des chaussures blancs","des blanches chaussures","des chaussures blanches","des chaussures blanc"],"answer":2},{"q":"Listen. What does the shop assistant ask?","say":"Quelle taille ?","options":["What size?","What colour?","How much?","Which shop?"],"answer":0},{"q":"What does {{Je porte}} mean here: {{Je porte un pull}}?","options":["I'm buying","I'm selling","I'm washing","I'm wearing"],"answer":3}]}]},{"id":"u3-home","icon":"Lit","title":"Home & Everyday Objects","subtitle":"Rooms, furniture and il y a","minutes":13,"goals":["Name the rooms of a home","Name everyday objects","Say what there is with il y a"],"blocks":[{"type":"text","text":"{{Bienvenue chez moi !}} Welcome to my home! Let's name the rooms and the things you use every day."},{"type":"vocab","items":[{"t":"la maison","tr":"lah meh-ZOHN","mean":"house / home"},{"t":"l'appartement","tr":"lah-par-tuh-MAHN","mean":"flat / apartment"},{"t":"la pièce","tr":"lah PYESS","mean":"room"},{"t":"la cuisine","tr":"lah kwee-ZEEN","mean":"kitchen (also: cooking)"},{"t":"le salon","tr":"luh sah-LOHN","mean":"living room"},{"t":"la chambre","tr":"lah SHAHMBR","mean":"bedroom"},{"t":"la salle de bains","tr":"lah sahl duh BAN","mean":"bathroom"},{"t":"les toilettes","tr":"lay twah-LET","mean":"toilet"},{"t":"le jardin","tr":"luh zhar-DAN","mean":"garden"},{"t":"l'escalier","tr":"les-kah-LYAY","mean":"stairs"}],"title":"Rooms"},{"type":"tip","kind":"warn","text":"False friend: {{une chambre}} is a **bedroom**. Any room in general is {{une pièce}}."},{"type":"vocab","items":[{"t":"la table","tr":"lah TAHBL","mean":"table"},{"t":"la chaise","tr":"lah SHEZ","mean":"chair"},{"t":"le lit","tr":"luh LEE","mean":"bed"},{"t":"le canapé","tr":"luh kah-nah-PAY","mean":"sofa"},{"t":"la porte","tr":"lah PORT","mean":"door"},{"t":"la fenêtre","tr":"lah fuh-NETR","mean":"window"},{"t":"la lampe","tr":"lah LAHMP","mean":"lamp"},{"t":"le frigo","tr":"luh free-GOH","mean":"fridge"},{"t":"le téléphone","tr":"luh tay-lay-FON","mean":"phone"},{"t":"l'ordinateur","tr":"lor-dee-nah-TUHR","mean":"computer"},{"t":"la clé","tr":"lah KLAY","mean":"key"},{"t":"le livre","tr":"luh LEEVR","mean":"book"}],"title":"Everyday objects"},{"type":"rule","name":"There is / there are: il y a","color":"blue","desc":"{{il y a}} means both **there is** and **there are**. It never changes.","how":"Negative: {{il n'y a pas de...}} = there isn't any / there are no...","examples":[{"t":"Il y a un lit.","tr":"eel-yah an LEE"},{"t":"Il y a deux chaises.","tr":"eel-yah duh SHEZ"},{"t":"Il n'y a pas de télé.","tr":"eel nyah pah duh tay-LAY"}]},{"type":"examples","items":[{"t":"Le livre est sur la table.","tr":"luh leevr eh sewr lah TAHBL","mean":"The book is on the table."},{"t":"Le chat est sous le lit.","tr":"luh shah eh soo luh LEE","mean":"The cat is under the bed."},{"t":"Les clés sont dans la cuisine.","tr":"lay klay sohn dahn lah kwee-ZEEN","mean":"The keys are in the kitchen."}],"title":"Where is it?"},{"type":"tip","kind":"tip","text":"Three tiny words go a long way: {{sur}} (on), {{sous}} (under) and {{dans}} (in). You'll learn more in Unit 4."},{"type":"sentence","t":"Dans ma chambre, il y a un lit et une fenêtre.","tr":"dahn mah SHAHMBR, eel-yah an lee ay ewn fuh-NETR","mean":"In my bedroom, there is a bed and a window.","words":[{"t":"Dans","mean":"in"},{"t":"ma","mean":"my"},{"t":"chambre","mean":"bedroom"},{"t":"il","mean":"it"},{"t":"y","mean":"there"},{"t":"a","mean":"has"},{"t":"un","mean":"a"},{"t":"lit","mean":"bed"},{"t":"et","mean":"and"},{"t":"une","mean":"a"},{"t":"fenêtre","mean":"window"}],"note":"{{il y a}} is literally 'it there has'."},{"type":"dialogue","lines":[{"who":"Agent","t":"Voici le salon. Il est grand, non ?","tr":"vwah-SEE luh sah-LOHN. eel eh GRAHN, NOHN","mean":"Here's the living room. It's big, isn't it?"},{"who":"Julie","t":"Oui, très ! Il y a combien de chambres ?","tr":"WEE, TREH. eel-yah kohm-byan duh SHAHMBR","mean":"Yes, very! How many bedrooms are there?"},{"who":"Agent","t":"Il y a deux chambres et une salle de bains.","tr":"eel-yah duh SHAHMBR ay ewn sahl duh BAN","mean":"There are two bedrooms and a bathroom."},{"who":"Julie","t":"Et la cuisine ?","tr":"ay lah kwee-ZEEN","mean":"And the kitchen?"},{"who":"Agent","t":"Elle est à côté du salon. Il y a un frigo neuf.","tr":"el eh-tah koh-TAY dew sah-LOHN. eel-yah an free-goh NUHF","mean":"It's next to the living room. There's a new fridge."},{"who":"Julie","t":"Parfait ! Il y a un jardin ?","tr":"par-FEH. eel-yah an zhar-DAN","mean":"Perfect! Is there a garden?"},{"who":"Agent","t":"Non, mais il y a un grand balcon.","tr":"NOHN, meh eel-yah an grahn bal-KOHN","mean":"No, but there's a big balcony."}],"title":"Flat hunting"},{"type":"practice","text":"Describe a home aloud.","lines":["Bienvenue chez moi !","Il y a trois pièces.","Dans le salon, il y a un canapé et une lampe.","Il n'y a pas de jardin.","Mes clés sont sur la table."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"What is {{la chambre}}?","options":["the kitchen","the bedroom","the bathroom","the living room"],"answer":1},{"q":"Listen. What do you hear?","say":"Il y a deux chaises.","options":["There are two cats.","I have two chairs.","There are two chairs.","Two chairs are missing."],"answer":2},{"q":"How do you say 'There's no fridge'?","options":["Il n'y a pas de frigo.","Il ne pas y a frigo.","Il y a non frigo.","Pas il y a de frigo."],"answer":0},{"q":"{{Le chat est sous le lit.}} Where is the cat?","options":["on the bed","next to the bed","under the bed","in the bedroom"],"answer":2},{"q":"Listen. What is it?","say":"la fenêtre","options":["the door","the window","the sofa","the lamp"],"answer":1},{"q":"Which word means 'key'?","options":["la chaise","la cuisine","la clé","le lit"],"answer":2},{"q":"Which room do you cook in?","options":["le salon","la salle de bains","la chambre","la cuisine"],"answer":3}]}]}]});
LC.units.push({"id":"grammar","order":4,"icon":"le","color":"indigo","title":"Grammar Made Easy","subtitle":"The patterns behind French, explained simply","lessons":[{"id":"u4-gender","icon":"le","title":"Nouns & Gender","subtitle":"Masculine, feminine and plural nouns","minutes":13,"goals":["Know that every noun is masculine or feminine","Spot typical masculine and feminine endings","Make nouns plural"],"blocks":[{"type":"text","text":"In French, every noun has a gender: **masculine** or **feminine**. Even tables and chairs! It isn't about meaning: it's simply part of the word. So learn each noun **with its article**."},{"type":"examples","items":[{"t":"le livre","tr":"luh LEEVR","mean":"the book (masculine)"},{"t":"la table","tr":"lah TAHBL","mean":"the table (feminine)"},{"t":"le soleil","tr":"luh soh-LEY","mean":"the sun (masculine)"},{"t":"la lune","tr":"lah LEWN","mean":"the moon (feminine)"},{"t":"le problème","tr":"luh proh-BLEM","mean":"the problem (masculine!)"},{"t":"la voiture","tr":"lah vwah-TEWR","mean":"the car (feminine)"}],"title":"Every noun has a gender"},{"type":"tip","kind":"memory","text":"Learn {{une table}}, not just {{table}}. The article is the word's gender label: {{le / un}} = masculine, {{la / une}} = feminine."},{"type":"table","head":["Usually masculine","Example","Usually feminine","Example"],"rows":[["-ment","{{le moment}}","-tion / -sion","{{la nation}}"],["-age","{{le fromage}}","-té","{{la liberté}}"],["-eau","{{le bateau}}","-ette","{{la baguette}}"],["-isme","{{le tourisme}}","-ure","{{la voiture}}"],["-er / -ier","{{le cahier}}","-ance / -ence","{{la chance}}"]],"title":"Endings that give a clue"},{"type":"tip","kind":"warn","text":"These are strong hints, not laws. {{la plage}} (beach), {{la page}} and {{l'eau}} (water) are feminine; {{le silence}} and {{l'été}} (summer) are masculine."},{"type":"vocab","items":[{"t":"un ami / une amie","tr":"an-nah-MEE / ew-nah-MEE","mean":"a friend (male / female)"},{"t":"un étudiant / une étudiante","tr":"an-nay-tew-DYAHN / ew-nay-tew-DYAHNT","mean":"a student (male / female)"},{"t":"un acteur / une actrice","tr":"an-nak-TUHR / ew-nak-TREESS","mean":"an actor / an actress"},{"t":"un chanteur / une chanteuse","tr":"an shahn-TUHR / ewn shahn-TUHZ","mean":"a singer (male / female)"},{"t":"un boulanger / une boulangère","tr":"an boo-lahn-ZHAY / ewn boo-lahn-ZHEHR","mean":"a baker (male / female)"}],"title":"People: gender follows the person"},{"type":"rule","name":"Plurals: add -s","color":"green","desc":"Most nouns add a silent **-s**. You hear the plural in the article: {{le / la}} becomes {{les}}, {{un / une}} becomes {{des}}.","how":"Words in {{-eau}} and most in {{-eu}} add {{-x}}. Most words in {{-al}} change to {{-aux}}.","examples":[{"t":"un livre, des livres","tr":"an LEEVR, day LEEVR"},{"t":"le gâteau, les gâteaux","tr":"luh gah-TOH, lay gah-TOH"},{"t":"le jeu, les jeux","tr":"luh ZHUH, lay ZHUH"},{"t":"le cheval, les chevaux","tr":"luh shuh-VAL, lay shuh-VOH"}]},{"type":"tip","kind":"tip","text":"The final -s and -x are silent: {{livre}} and {{livres}} sound the same. Listen to the article instead: {{le}} ('luh') versus {{les}} ('lay')."},{"type":"sentence","t":"Les gâteaux sont sur la table.","tr":"lay gah-TOH sohn sewr lah TAHBL","mean":"The cakes are on the table.","words":[{"t":"Les","mean":"the (plural)"},{"t":"gâteaux","mean":"cakes"},{"t":"sont","mean":"are"},{"t":"sur","mean":"on"},{"t":"la","mean":"the (fem.)"},{"t":"table","mean":"table"}]},{"type":"practice","text":"Read each noun with its article. Feel the gender!","lines":["le livre, la table","le moment, la nation","le fromage, la liberté","le bateau, les bateaux","un ami, une amie","le cheval, les chevaux"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Which noun is most likely feminine?","options":["situation","fromage","moment","bateau"],"answer":0,"explain":"Nouns ending in {{-tion}} are feminine."},{"q":"What is the plural of {{le bateau}}?","options":["les bateaus","les bateau","les bateaux","la bateaux"],"answer":2},{"q":"Why learn nouns with {{le}} or {{la}}?","options":["To spell the plural","To know their gender","To make them louder","To show they're plural"],"answer":1},{"q":"Listen. Singular or plural?","say":"les livres","options":["Singular: you hear 'luh'","Plural: you hear 'lay'","You can't tell at all"],"answer":1},{"q":"Which ending usually means a masculine noun?","options":["-tion","-té","-ment","-ure"],"answer":2},{"q":"The feminine of {{un acteur}} is...","options":["une acteure","une actrice","une acteuse","un actrice"],"answer":1},{"q":"Which word is feminine even though it ends in -age?","options":["fromage","voyage","plage","garage"],"answer":2,"explain":"{{la plage}} (beach) is a famous exception."}]}]},{"id":"u4-articles","icon":"un","title":"Articles: the, a, some","subtitle":"le, la, les · un, une, des · du, de la","minutes":15,"goals":["Use le, la, l' and les (the)","Use un, une and des (a, some)","Use du, de la and de l' (some) with food and drink"],"blocks":[{"type":"text","text":"English has 'the', 'a' and 'some'. French has a few more forms, because articles change with **gender** and **number**. Here's the whole set in three small tables."},{"type":"table","head":["","Masculine","Feminine","Plural"],"rows":[["the","{{le livre}}","{{la table}}","{{les livres}}"],["the (before a vowel or silent h)","{{l'ami}}","{{l'eau}}","{{les amis}}"]],"title":"The: le, la, l', les"},{"type":"tip","kind":"tip","text":"{{le}} and {{la}} shorten to {{l'}} before a vowel or a silent h: {{l'hôtel}}, {{l'école}}. This is called elision, and it makes French flow."},{"type":"table","head":["","Masculine","Feminine","Plural"],"rows":[["a / some","{{un livre}}","{{une pomme}}","{{des amis}}"],["meaning","a book","an apple","(some) friends"]],"title":"A / some: un, une, des"},{"type":"tip","kind":"memory","text":"English often drops 'some', but French needs {{des}}: {{J'ai des amis}} = I have (some) friends. A French noun almost never stands alone."},{"type":"table","head":["Masculine","Feminine","Before a vowel","Plural"],"rows":[["{{du pain}}","{{de la confiture}}","{{de l'eau}}","{{des pâtes}}"],["some bread","some jam","some water","some pasta"]],"title":"Some: du, de la, de l', des"},{"type":"rule","name":"When to use du / de la","color":"blue","desc":"Use {{du, de la, de l'}} for an amount of something you don't count: food, drinks, money, time, courage.","examples":[{"t":"Je mange du pain.","tr":"zhuh mahnzh dew PAN"},{"t":"Tu veux de la salade ?","tr":"tew vuh duh lah sah-LAHD"},{"t":"Il boit de l'eau.","tr":"eel bwah duh LOH"},{"t":"Elle a du courage.","tr":"el ah dew koo-RAHZH"}]},{"type":"compare","items":[{"t":"J'aime le fromage.","label":"In general: le, la, les","desc":"Use after {{aimer, adorer, détester, préférer}}: cheese as a whole."},{"t":"Je mange du fromage.","label":"An amount: du, de la","desc":"Use when you eat, drink, buy or have **some** of it."}]},{"type":"rule","name":"After a negative: de","color":"red","desc":"After {{ne... pas}}, the articles {{un, une, des, du, de la}} all become {{de}} (or {{d'}}).","examples":[{"t":"Je n'ai pas de chien.","tr":"zhuh neh pah duh SHYAN"},{"t":"Il ne boit pas d'eau.","tr":"eel nuh bwah pah DOH"},{"t":"Nous n'avons pas de pain.","tr":"noo nah-vohn pah duh PAN"}]},{"type":"tip","kind":"warn","text":"One exception: with {{être}} the article stays. {{C'est un chat}} becomes {{Ce n'est pas un chat}}."},{"type":"sentence","t":"Je voudrais du pain et de la confiture.","tr":"zhuh voo-dreh dew PAN ay duh lah kohn-fee-TEWR","mean":"I'd like some bread and some jam.","words":[{"t":"Je","mean":"I"},{"t":"voudrais","mean":"would like"},{"t":"du","mean":"some"},{"t":"pain","mean":"bread"},{"t":"et","mean":"and"},{"t":"de","mean":"some (of)"},{"t":"la","mean":"the"},{"t":"confiture","mean":"jam"}],"note":"{{de la}} works as one unit: 'some' for a feminine noun."},{"type":"practice","text":"Read aloud and notice each article.","lines":["le pain, la confiture, l'eau, les pâtes","un croissant, une pomme, des fraises","Je mange du fromage.","Tu bois de l'eau ?","Je n'ai pas de voiture."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Complete (the school): ___ école","options":["la","le","les","l'"],"answer":3,"explain":"{{école}} starts with a vowel, so {{la}} becomes {{l'}}."},{"q":"Complete (some milk): Je bois ___ lait.","options":["de la","du","des"],"answer":1,"explain":"{{lait}} is masculine: {{du lait}}."},{"q":"Complete: Je n'ai pas ___ voiture.","options":["une","des","de"],"answer":2,"explain":"After {{ne... pas}}, use {{de}}."},{"q":"Complete: J'adore ___ chocolat.","options":["le","du","de"],"answer":0,"explain":"After {{adorer}}, use {{le / la / les}}."},{"q":"Listen. What does it mean?","say":"des pommes","options":["an apple","some apples","the apple"],"answer":1},{"q":"Which sentence is correct?","options":["J'ai des amis à Paris.","J'ai amis à Paris.","J'ai de amis à Paris.","J'ai un amis à Paris."],"answer":0},{"q":"What does {{de l'eau}} mean?","options":["the water","water's","some water","a waterfall"],"answer":2}]}]},{"id":"u4-etre","icon":"est","title":"Être: to be","subtitle":"The most important verb in French","minutes":12,"goals":["Conjugate être in the present","Describe people and say jobs with être","Choose between c'est and il est / elle est"],"blocks":[{"type":"text","text":"{{être}} (to be) is the most important verb in French. It's irregular, so learn it like a little song: {{je suis, tu es, il est...}}"},{"type":"table","head":["Pronoun","être","Say it","Meaning"],"rows":[["{{je}}","{{suis}}","zhuh SWEE","I am"],["{{tu}}","{{es}}","tew EH","you are (friendly)"],["{{il / elle / on}}","{{est}}","eel / el / ohn EH","he / she / one is"],["{{nous}}","{{sommes}}","noo SOM","we are"],["{{vous}}","{{êtes}}","voo-ZET","you are (polite / plural)"],["{{ils / elles}}","{{sont}}","eel / el SOHN","they are"]],"title":"être (to be): present"},{"type":"tip","kind":"tip","text":"{{on}} literally means 'one', but in everyday French it usually means **we**: {{On est en retard !}} = We're late!"},{"type":"tip","kind":"warn","text":"{{ils}} = they (all male, or a mixed group). {{elles}} = they (all female). One man in a group of women? It's {{ils}}."},{"type":"examples","items":[{"t":"Je suis étudiant.","tr":"zhuh swee-zay-tew-DYAHN","mean":"I'm a student.","note":"No 'a' before a job after {{être}}."},{"t":"Tu es fatigué ?","tr":"tew eh fah-tee-GAY","mean":"Are you tired?"},{"t":"Elle est médecin.","tr":"el eh mayd-SAN","mean":"She's a doctor."},{"t":"Nous sommes en France.","tr":"noo som-zahn FRAHNS","mean":"We're in France."},{"t":"Vous êtes très gentil.","tr":"voo-zet treh zhahn-TEE","mean":"You're very kind."},{"t":"Ils sont à la maison.","tr":"eel sohn-tah lah meh-ZOHN","mean":"They're at home."}]},{"type":"tip","kind":"memory","text":"Jobs after {{être}} drop the article: {{Il est professeur}} = 'He is teacher'. Think of the job as a description, like 'He is tall'."},{"type":"compare","items":[{"t":"C'est...","label":"It's / he's / she's + a noun","desc":"Use with an article or a name: {{C'est un ami.}} {{C'est ma sœur.}} {{C'est Paris.}}"},{"t":"Il est / Elle est...","label":"+ an adjective or a bare job","desc":"{{Il est grand.}} {{Elle est avocate.}}"}],"title":"C'est or il est?"},{"type":"sentence","t":"Nous sommes contents d'être ici.","tr":"noo som kohn-TAHN DETR ee-SEE","mean":"We're happy to be here.","words":[{"t":"Nous","mean":"we"},{"t":"sommes","mean":"are"},{"t":"contents","mean":"happy"},{"t":"d'être","mean":"to be"},{"t":"ici","mean":"here"}]},{"type":"dialogue","lines":[{"who":"Teacher","t":"Vous êtes nouveau ?","tr":"voo-zet noo-VOH","mean":"Are you new?"},{"who":"Raj","t":"Oui, je suis Raj. Je suis indien.","tr":"WEE, zhuh swee RAHDJ. zhuh swee-zan-DYAN","mean":"Yes, I'm Raj. I'm Indian."},{"who":"Teacher","t":"Bienvenue ! Les étudiants sont sympas ici.","tr":"byan-vuh-NEW. lay-zay-tew-DYAHN sohn san-PAH ee-SEE","mean":"Welcome! The students are nice here."},{"who":"Raj","t":"C'est super. Vous êtes professeur de maths ?","tr":"seh sew-PEHR. voo-zet proh-feh-suhr duh MAHT","mean":"That's great. Are you the maths teacher?"},{"who":"Teacher","t":"Non, je suis professeur de français !","tr":"NOHN, zhuh swee proh-feh-suhr duh frahn-SEH","mean":"No, I'm the French teacher!"}],"title":"First day"},{"type":"practice","text":"Chant être three times, faster each time!","lines":["je suis, tu es, il est, elle est, on est","nous sommes, vous êtes, ils sont, elles sont","Je suis content.","C'est mon frère. Il est grand."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"nous ___ (être)","options":["êtes","sont","est","sommes"],"answer":3},{"q":"vous ___ (être)","options":["es","êtes","sommes","sont"],"answer":1},{"q":"Listen. Who is tired?","say":"Ils sont fatigués.","options":["They are.","We are.","You are.","He is."],"answer":0},{"q":"How do you say 'She's a doctor'?","options":["Elle est un médecin.","C'est médecin.","Elle a médecin.","Elle est médecin."],"answer":3,"explain":"No article before a job after {{il est / elle est}}."},{"q":"Complete: ___ un bon livre.","options":["Il est","C'est","Elle est"],"answer":1,"explain":"Before an article + noun, use {{c'est}}."},{"q":"What does {{On est prêts !}} usually mean?","options":["One is ready.","They're ready!","We're ready!","You're ready!"],"answer":2},{"q":"je ___ (être)","options":["es","est","sommes","suis"],"answer":3}]}]},{"id":"u4-avoir","icon":"ai","title":"Avoir: to have","subtitle":"Having things, and saying how you feel","minutes":13,"goals":["Conjugate avoir in the present","Use avoir for age, hunger, thirst and more","Hear the difference between ils sont and ils ont"],"blocks":[{"type":"text","text":"{{avoir}} (to have) is the second key verb. French also uses it where English uses 'to be': for age, hunger, thirst, fear and more."},{"type":"table","head":["Pronoun","avoir","Say it","Meaning"],"rows":[["{{j'}}","{{ai}}","zhay","I have"],["{{tu}}","{{as}}","tew AH","you have"],["{{il / elle / on}}","{{a}}","eel / el / ohn AH","he / she / one has"],["{{nous}}","{{avons}}","noo-zah-VOHN","we have"],["{{vous}}","{{avez}}","voo-zah-VAY","you have"],["{{ils / elles}}","{{ont}}","eel-ZOHN / el-ZOHN","they have"]],"title":"avoir (to have): present"},{"type":"compare","items":[{"t":"ils sont","label":"they are: S sound","desc":"'eel SOHN', a hissing S."},{"t":"ils ont","label":"they have: Z sound","desc":"'eel ZOHN', the S of {{ils}} links with a buzzing Z."}],"title":"Listen carefully"},{"type":"examples","items":[{"t":"J'ai deux sœurs.","tr":"zhay duh SUHR","mean":"I have two sisters."},{"t":"Tu as un stylo ?","tr":"tew ah an stee-LOH","mean":"Do you have a pen?"},{"t":"Nous avons un chien.","tr":"noo-zah-vohn an SHYAN","mean":"We have a dog."},{"t":"Elles ont dix-huit ans.","tr":"el-zohn dee-zwee-TAHN","mean":"They're eighteen."}]},{"type":"rule","name":"Avoir where English says 'to be'","color":"orange","desc":"French says 'I **have** hunger', not 'I am hungry'. Learn these as fixed phrases.","examples":[{"t":"J'ai faim.","tr":"zhay FAN"},{"t":"J'ai froid.","tr":"zhay FRWAH"}]},{"type":"vocab","items":[{"t":"avoir faim","tr":"ah-vwahr FAN","mean":"to be hungry","example":{"t":"J'ai faim !","tr":"zhay FAN","mean":"I'm hungry!"}},{"t":"avoir soif","tr":"ah-vwahr SWAHF","mean":"to be thirsty"},{"t":"avoir chaud","tr":"ah-vwahr SHOH","mean":"to be hot / warm"},{"t":"avoir froid","tr":"ah-vwahr FRWAH","mean":"to be cold"},{"t":"avoir peur (de)","tr":"ah-vwahr PUHR","mean":"to be afraid (of)","example":{"t":"Il a peur des chiens.","tr":"eel ah puhr day SHYAN","mean":"He's afraid of dogs."}},{"t":"avoir sommeil","tr":"ah-vwahr soh-MEY","mean":"to be sleepy"},{"t":"avoir raison","tr":"ah-vwahr reh-ZOHN","mean":"to be right"},{"t":"avoir tort","tr":"ah-vwahr TOR","mean":"to be wrong"},{"t":"avoir besoin de","tr":"ah-vwahr buh-ZWAN duh","mean":"to need","example":{"t":"J'ai besoin d'aide.","tr":"zhay buh-zwan DED","mean":"I need help."}},{"t":"avoir ... ans","tr":"ah-vwahr ... AHN","mean":"to be ... years old"}],"title":"Avoir expressions"},{"type":"tip","kind":"warn","text":"For temperature, never say {{Je suis chaud}}: it sounds like slang for 'I'm all fired up!'. Say {{J'ai chaud}}."},{"type":"sentence","t":"J'ai très faim et un peu froid.","tr":"zhay treh FAN ay an puh FRWAH","mean":"I'm very hungry and a bit cold.","words":[{"t":"J'ai","mean":"I have"},{"t":"très","mean":"very"},{"t":"faim","mean":"hunger"},{"t":"et","mean":"and"},{"t":"un","mean":"a"},{"t":"peu","mean":"little"},{"t":"froid","mean":"cold"}]},{"type":"dialogue","lines":[{"who":"Lucas","t":"Tu as faim ?","tr":"tew ah FAN","mean":"Are you hungry?"},{"who":"Chloé","t":"Oui, j'ai très faim ! Et j'ai soif aussi.","tr":"WEE, zhay treh FAN. ay zhay swahf oh-SEE","mean":"Yes, I'm starving! And I'm thirsty too."},{"who":"Lucas","t":"On a des sandwichs dans le sac, non ?","tr":"ohn-nah day sahnd-WEETSH dahn luh SAK, NOHN","mean":"We've got sandwiches in the bag, haven't we?"},{"who":"Chloé","t":"Ah oui, tu as raison !","tr":"ah WEE, tew ah reh-ZOHN","mean":"Oh yes, you're right!"},{"who":"Lucas","t":"Tu as froid ? Tu veux ma veste ?","tr":"tew ah FRWAH? tew vuh mah VEST","mean":"Are you cold? Do you want my jacket?"},{"who":"Chloé","t":"Non merci, j'ai chaud maintenant !","tr":"nohn mehr-SEE, zhay shoh mant-NAHN","mean":"No thanks, I'm warm now!"}],"title":"A picnic"},{"type":"practice","text":"Say each line aloud with feeling!","lines":["j'ai, tu as, il a, elle a, on a","nous avons, vous avez, ils ont, elles ont","J'ai faim !","Tu as raison.","Nous avons froid.","Ils ont peur."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"nous ___ (avoir)","options":["avez","avons","ont","sommes"],"answer":1},{"q":"How do you say 'I'm cold'?","options":["Je suis froid.","J'ai chaud.","J'ai froid.","Je froid."],"answer":2},{"q":"Listen. What does it mean?","say":"Ils ont faim.","options":["They're thirsty.","They're hungry.","They're famous.","We're hungry."],"answer":1},{"q":"What does {{avoir besoin de}} mean?","options":["to be busy","to be afraid of","to need","to be sleepy"],"answer":2},{"q":"Listen. Which verb is it?","say":"Elles ont vingt ans.","options":["avoir (they have)","être (they are)","aller (they go)"],"answer":0,"explain":"You hear a Z sound: {{elles ont}}."},{"q":"What does {{Tu as tort}} mean?","options":["You're wrong.","You're right.","You're tired.","You're late."],"answer":0},{"q":"Complete: j'___ (avoir)","options":["ai","as","a","es"],"answer":0}]}]},{"id":"u4-er-verbs","icon":"-er","title":"Regular -er Verbs","subtitle":"One pattern, hundreds of verbs","minutes":15,"goals":["Recognise -er verbs","Conjugate them in the present","Know which endings are silent"],"blocks":[{"type":"text","text":"Most French verbs end in **-er**, and almost all of them follow one pattern. Learn it once and you can use hundreds of verbs: {{parler}} (to speak), {{aimer}} (to like), {{habiter}} (to live)..."},{"type":"steps","items":[{"title":"Start with the infinitive","t":"parler","tr":"par-LAY","mean":"to speak"},{"title":"Remove -er to find the stem","t":"parl-","desc":"This part never changes."},{"title":"Add the ending for the person","t":"je parle","tr":"zhuh PARL","mean":"I speak"}],"title":"How to conjugate"},{"type":"table","head":["Pronoun","Ending","parler","Say it"],"rows":[["{{je}}","-e","{{je parle}}","zhuh PARL"],["{{tu}}","-es","{{tu parles}}","tew PARL"],["{{il / elle / on}}","-e","{{il parle}}","eel PARL"],["{{nous}}","-ons","{{nous parlons}}","noo par-LOHN"],["{{vous}}","-ez","{{vous parlez}}","voo par-LAY"],["{{ils / elles}}","-ent","{{ils parlent}}","eel PARL"]],"title":"parler (to speak)"},{"type":"tip","kind":"memory","text":"Four forms, one sound: {{je parle, tu parles, il parle, ils parlent}} all sound like 'parl'. Only {{nous}} (-ons) and {{vous}} (-ez) sound different."},{"type":"tip","kind":"warn","text":"The {{-ent}} of {{ils parlent}} is **silent**. Never say 'parl-ENT'!"},{"type":"vocab","items":[{"t":"parler","tr":"par-LAY","mean":"to speak","example":{"t":"Tu parles anglais ?","tr":"tew parl ahn-GLEH","mean":"Do you speak English?"}},{"t":"aimer","tr":"eh-MAY","mean":"to like / to love"},{"t":"habiter","tr":"ah-bee-TAY","mean":"to live (somewhere)"},{"t":"travailler","tr":"trah-vah-YAY","mean":"to work"},{"t":"manger","tr":"mahn-ZHAY","mean":"to eat"},{"t":"regarder","tr":"ruh-gar-DAY","mean":"to watch / to look at","example":{"t":"Elle regarde un film.","tr":"el ruh-gard an FEELM","mean":"She's watching a film."}},{"t":"écouter","tr":"ay-koo-TAY","mean":"to listen (to)"},{"t":"jouer","tr":"zhoo-AY","mean":"to play"},{"t":"chercher","tr":"shehr-SHAY","mean":"to look for"},{"t":"acheter","tr":"ash-TAY","mean":"to buy"},{"t":"étudier","tr":"ay-tew-DYAY","mean":"to study"},{"t":"adorer","tr":"ah-doh-RAY","mean":"to love / to adore"}],"title":"Useful -er verbs"},{"type":"rule","name":"Before a vowel: j'","color":"gray","desc":"{{je}} becomes {{j'}} before a vowel or a silent h.","examples":[{"t":"j'aime","tr":"ZHEM"},{"t":"j'habite","tr":"zhah-BEET"},{"t":"j'écoute","tr":"zhay-KOOT"}]},{"type":"tip","kind":"warn","text":"Small spelling changes keep the sound right: {{nous mangeons}} keeps an E so the G stays soft, and {{j'achète}} gets an accent. The sound is your guide."},{"type":"tip","kind":"tip","text":"One French present = three English ones. {{Je parle}} means 'I speak', 'I'm speaking' and 'I do speak'."},{"type":"examples","items":[{"t":"Vous aimez le jazz ?","tr":"voo-zeh-may luh DJAZZ","mean":"Do you like jazz?"},{"t":"Ils écoutent de la musique.","tr":"eel-zay-koot duh lah mew-ZEEK","mean":"They're listening to music."},{"t":"Je cherche mes clés.","tr":"zhuh shehrsh may KLAY","mean":"I'm looking for my keys."},{"t":"On joue au tennis ?","tr":"ohn zhoo oh teh-NEESS","mean":"Shall we play tennis?"}]},{"type":"sentence","t":"Nous habitons à Lyon et nous travaillons ensemble.","tr":"noo-zah-bee-TOHN ah lee-OHN ay noo trah-vah-YOHN ahn-SAHMBL","mean":"We live in Lyon and we work together.","words":[{"t":"Nous","mean":"we"},{"t":"habitons","mean":"live"},{"t":"à","mean":"in"},{"t":"Lyon","mean":"Lyon"},{"t":"et","mean":"and"},{"t":"nous","mean":"we"},{"t":"travaillons","mean":"work"},{"t":"ensemble","mean":"together"}]},{"type":"dialogue","lines":[{"who":"Nina","t":"Tu habites où ?","tr":"tew ah-beet OO","mean":"Where do you live?"},{"who":"Hugo","t":"J'habite à Marseille. Je travaille dans un restaurant.","tr":"zhah-beet ah mar-SEY. zhuh trah-vahy dahn-zan res-toh-RAHN","mean":"I live in Marseille. I work in a restaurant."},{"who":"Nina","t":"Tu cuisines bien ?","tr":"tew kwee-zeen BYAN","mean":"Are you a good cook?"},{"who":"Hugo","t":"Oui ! Et le soir, je joue de la guitare.","tr":"WEE. ay luh SWAHR, zhuh zhoo duh lah gee-TAR","mean":"Yes! And in the evening, I play the guitar."},{"who":"Nina","t":"Génial ! Nous adorons la musique aussi.","tr":"zhay-NYAL. noo-zah-doh-rohn lah mew-ZEEK oh-SEE","mean":"Great! We love music too."}]},{"type":"practice","text":"Conjugate aloud, then read the sentences.","lines":["je parle, tu parles, il parle","nous parlons, vous parlez, ils parlent","J'aime le cinéma.","Nous regardons la télé.","Vous travaillez où ?","Elles écoutent la radio."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"tu ___ (parler)","options":["parle","parlez","parles","parlons"],"answer":2},{"q":"nous ___ (aimer)","options":["aimez","aimons","aiment","aimes"],"answer":1},{"q":"Listen to the verb. How is the ending -ent said?","say":"Ils regardent la télé.","options":["It is silent","Like English 'ant'","Like the 'on' of nous"],"answer":0},{"q":"Which two forms sound exactly the same?","options":["nous parlons and vous parlez","je parle and ils parlent","tu parles and vous parlez"],"answer":1},{"q":"How do you say 'I'm listening to music'?","options":["Je suis écoute la musique.","Je écoute de la musique.","J'écoute de la musique.","J'écoutons la musique."],"answer":2},{"q":"vous ___ (habiter)","options":["habitons","habitent","habitez","habites"],"answer":2},{"q":"{{Elle travaille}} can mean...","options":["she works / she's working","only: she worked","only: she will work"],"answer":0}]}]},{"id":"u4-negation","icon":"pas","title":"Saying No: ne… pas","subtitle":"Negative sentences, never, nothing, nobody","minutes":13,"goals":["Make sentences negative with ne… pas","Use n' before a vowel","Use jamais, plus, rien and personne"],"blocks":[{"type":"text","text":"To make a sentence negative, French wraps the verb in two little words: {{ne}} before it and {{pas}} after it. Think of it as a sandwich, with the verb as the filling."},{"type":"rule","name":"The ne… pas sandwich","color":"red","desc":"{{ne}} + verb + {{pas}}.","how":"{{ne}} becomes {{n'}} before a vowel or a silent h.","examples":[{"t":"Je ne parle pas allemand.","tr":"zhuh nuh parl pah-zahl-MAHN"},{"t":"Il n'aime pas le café.","tr":"eel nem pah luh kah-FAY"},{"t":"Nous ne sommes pas fatigués.","tr":"noo nuh som pah fah-tee-GAY"},{"t":"Tu n'habites pas ici ?","tr":"tew nah-beet pah-zee-SEE"}]},{"type":"sentence","t":"Je ne mange pas de viande.","tr":"zhuh nuh mahnzh pah duh VYAHND","mean":"I don't eat meat.","words":[{"t":"Je","mean":"I"},{"t":"ne","mean":"(not)"},{"t":"mange","mean":"eat"},{"t":"pas","mean":"not"},{"t":"de","mean":"any"},{"t":"viande","mean":"meat"}],"note":"Remember: after {{pas}}, {{du, de la, des, un, une}} become {{de}}."},{"type":"tip","kind":"culture","text":"In relaxed speech, people often drop the {{ne}}: {{Je sais pas}} (Dunno). Understand it when you hear it, but write the full {{ne... pas}}."},{"type":"table","head":["French","Meaning","Example"],"rows":[["{{ne... jamais}}","never","{{Je ne mange jamais de viande.}}"],["{{ne... plus}}","no longer, not any more","{{Il n'habite plus ici.}}"],["{{ne... rien}}","nothing, not anything","{{Je ne vois rien.}}"],["{{ne... personne}}","nobody, not anyone","{{Je ne connais personne.}}"]],"title":"Other negatives"},{"type":"tip","kind":"warn","text":"On its own, {{une personne}} means 'a person'. With {{ne}}, {{personne}} means **nobody**!"},{"type":"rule","name":"Two verbs together","color":"blue","desc":"With two verbs, the sandwich goes around the first (conjugated) one.","examples":[{"t":"Je ne veux pas partir.","tr":"zhuh nuh vuh pah par-TEER"},{"t":"Elle ne va pas venir.","tr":"el nuh vah pah vuh-NEER"}]},{"type":"examples","items":[{"t":"Non, pas du tout.","tr":"nohn, pah dew TOO","mean":"No, not at all."},{"t":"Non, jamais !","tr":"nohn, zhah-MEH","mean":"No, never!"},{"t":"Moi non plus.","tr":"mwah nohn PLEW","mean":"Me neither."},{"t":"Pas encore.","tr":"pah-zahn-KOR","mean":"Not yet."}],"title":"Short answers"},{"type":"dialogue","lines":[{"who":"Max","t":"Tu aimes le foot ?","tr":"tew em luh FOOT","mean":"Do you like football?"},{"who":"Sara","t":"Non, je n'aime pas le sport.","tr":"NOHN, zhuh nem pah luh SPOR","mean":"No, I don't like sport."},{"who":"Max","t":"Tu ne regardes jamais les matchs ?","tr":"tew nuh ruh-gard zhah-meh lay MATSH","mean":"You never watch the matches?"},{"who":"Sara","t":"Jamais ! Je ne comprends rien aux règles.","tr":"zhah-MEH. zhuh nuh kohm-prahn ryan oh REGL","mean":"Never! I don't understand anything about the rules."},{"who":"Max","t":"Moi non plus, en fait !","tr":"mwah nohn PLEW, ahn FET","mean":"Me neither, actually!"}]},{"type":"practice","text":"Make each sentence negative aloud, then check with the line below it.","lines":["Je parle chinois.","Je ne parle pas chinois.","Il aime le thé.","Il n'aime pas le thé.","Nous avons une voiture.","Nous n'avons pas de voiture."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Make it negative: {{Je parle chinois.}}","options":["Je parle ne pas chinois.","Je ne parle pas chinois.","Je pas parle chinois.","Ne je parle pas chinois."],"answer":1},{"q":"Complete: Il ___ aime pas le thé.","options":["ne","n'","pas","non"],"answer":1,"explain":"{{aime}} starts with a vowel, so {{ne}} becomes {{n'}}."},{"q":"What does {{Je ne mange jamais de poisson}} mean?","options":["I don't eat fish any more.","I eat nothing at all.","I never eat fish.","Nobody eats fish."],"answer":2},{"q":"Listen. What does it mean?","say":"Il n'habite plus ici.","options":["He has never lived here.","He doesn't live here any more.","He lives here now.","Nobody lives here."],"answer":1},{"q":"Which sentence is correct?","options":["Je n'ai pas des voiture.","Je n'ai pas de voiture.","Je ne pas ai de voiture.","Je n'ai de pas voiture."],"answer":1},{"q":"What does {{Moi non plus}} mean?","options":["Me too","Me neither","Not any more","No more for me"],"answer":1},{"q":"Make it negative: {{Je veux partir.}}","options":["Je ne veux partir pas.","Je veux partir pas.","Ne je veux partir pas.","Je ne veux pas partir."],"answer":3}]}]},{"id":"u4-questions","icon":"?","title":"Asking Questions","subtitle":"Three ways to ask, plus who, what, where...","minutes":15,"goals":["Ask yes/no questions in three ways","Use the question words","Ask natural everyday questions"],"blocks":[{"type":"text","text":"French gives you three ways to ask a yes/no question, from relaxed to formal. Start with the easiest: you probably know it already!"},{"type":"steps","items":[{"title":"1. Raise your voice (relaxed)","t":"Tu parles anglais ?","tr":"tew parl ahn-GLEH?","mean":"Do you speak English?","desc":"Just say the sentence with a rising tone. Very common in speech."},{"title":"2. Add est-ce que (neutral)","t":"Est-ce que tu parles anglais ?","tr":"ess-kuh tew parl ahn-GLEH?","mean":"Do you speak English?","desc":"Put {{est-ce que}} at the front. It works everywhere."},{"title":"3. Swap verb and subject (formal)","t":"Parles-tu anglais ?","tr":"parl-tew ahn-GLEH?","mean":"Do you speak English?","desc":"Join them with a hyphen. Common in writing and polite speech."}],"title":"Three ways to ask"},{"type":"tip","kind":"tip","text":"{{est-ce que}} sounds like 'ESS-kuh'. It literally means 'is it that...?'. Before a vowel it becomes {{est-ce qu'}}: {{Est-ce qu'il vient ?}}"},{"type":"rule","name":"Inversion with il / elle / on","color":"purple","desc":"If the verb ends in a vowel, add {{-t-}} between the verb and {{il, elle, on}} so it sounds smooth.","examples":[{"t":"Parle-t-il français ?","tr":"parl-teel frahn-SEH"},{"t":"A-t-elle un chien ?","tr":"ah-tel an SHYAN"},{"t":"Va-t-on au cinéma ?","tr":"vah-tohn oh see-nay-MAH"}]},{"type":"vocab","items":[{"t":"qui","tr":"KEE","mean":"who","example":{"t":"Qui est-ce ?","tr":"kee ESS","mean":"Who is it?"}},{"t":"qu'est-ce que","tr":"KESS-kuh","mean":"what","example":{"t":"Qu'est-ce que tu manges ?","tr":"kess-kuh tew MAHNZH","mean":"What are you eating?"}},{"t":"quoi","tr":"KWAH","mean":"what (at the end)","example":{"t":"Tu manges quoi ?","tr":"tew mahnzh KWAH","mean":"You're eating what?"}},{"t":"où","tr":"OO","mean":"where","example":{"t":"Où est la gare ?","tr":"oo eh lah GAR","mean":"Where is the station?"}},{"t":"quand","tr":"KAHN","mean":"when","example":{"t":"Tu pars quand ?","tr":"tew par KAHN","mean":"When are you leaving?"}},{"t":"comment","tr":"koh-MAHN","mean":"how","example":{"t":"Comment tu t'appelles ?","tr":"koh-mahn tew tah-PEL","mean":"What's your name?"}},{"t":"pourquoi","tr":"poor-KWAH","mean":"why","example":{"t":"Pourquoi tu ris ?","tr":"poor-kwah tew REE","mean":"Why are you laughing?"}},{"t":"combien","tr":"kohm-BYAN","mean":"how much / how many","example":{"t":"Combien de frères as-tu ?","tr":"kohm-byan duh frehr ah-TEW","mean":"How many brothers do you have?"}},{"t":"quel / quelle","tr":"KEL","mean":"which / what","example":{"t":"Quel âge as-tu ?","tr":"kel ahzh ah-TEW","mean":"How old are you?"}}],"title":"Question words"},{"type":"tip","kind":"memory","text":"{{pourquoi}} (why) is answered with {{parce que}} (because): {{Pourquoi tu ris ? Parce que c'est drôle !}}"},{"type":"table","head":["Relaxed","Neutral","Formal"],"rows":[["{{Tu vas où ?}}","{{Où est-ce que tu vas ?}}","{{Où vas-tu ?}}"],["{{Il arrive quand ?}}","{{Quand est-ce qu'il arrive ?}}","{{Quand arrive-t-il ?}}"],["{{Vous voulez quoi ?}}","{{Qu'est-ce que vous voulez ?}}","{{Que voulez-vous ?}}"]],"title":"Same question, three styles"},{"type":"sentence","t":"Qu'est-ce que tu fais ce soir ?","tr":"kess-kuh tew feh suh SWAHR","mean":"What are you doing tonight?","words":[{"t":"Qu'est-ce","mean":"what is it"},{"t":"que","mean":"that"},{"t":"tu","mean":"you"},{"t":"fais","mean":"do"},{"t":"ce","mean":"this"},{"t":"soir","mean":"evening"}]},{"type":"dialogue","lines":[{"who":"Yasmine","t":"Salut ! Qu'est-ce que tu fais ce week-end ?","tr":"sah-LEW. kess-kuh tew feh suh wee-KEND","mean":"Hi! What are you doing this weekend?"},{"who":"Noah","t":"Je vais à la plage. Tu veux venir ?","tr":"zhuh veh ah lah PLAHZH. tew vuh vuh-NEER","mean":"I'm going to the beach. Do you want to come?"},{"who":"Yasmine","t":"Oui ! Quand est-ce que tu pars ?","tr":"WEE. kahn-tess-kuh tew PAR","mean":"Yes! When are you leaving?"},{"who":"Noah","t":"Samedi matin.","tr":"sahm-dee mah-TAN","mean":"Saturday morning."},{"who":"Yasmine","t":"Et comment on y va ?","tr":"ay koh-mahn ohn-nee VAH","mean":"And how do we get there?"},{"who":"Noah","t":"En train. Ce n'est pas cher !","tr":"ahn TRAN. suh neh pah SHEHR","mean":"By train. It isn't expensive!"}]},{"type":"practice","text":"Ask each question aloud. Let your voice go up at the end of yes/no questions.","lines":["Tu parles anglais ?","Est-ce que tu as faim ?","Parlez-vous français ?","Où est la gare ?","Pourquoi tu ris ?","Combien ça coûte ?"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Which question is the most formal?","options":["Vous parlez anglais ?","Est-ce que vous parlez anglais ?","Parlez-vous anglais ?"],"answer":2},{"q":"What does {{où}} mean?","options":["where","when","who","why"],"answer":0},{"q":"Listen. What is the question?","say":"Pourquoi tu pars ?","options":["When are you leaving?","Where are you going?","How are you leaving?","Why are you leaving?"],"answer":3},{"q":"Complete (neutral style): ___ tu habites à Paris ?","options":["Est-ce que","Qu'est-ce que","Pourquoi que","Quoi"],"answer":0},{"q":"Turn into an inversion question: {{Il parle français.}}","options":["Parle-il français ?","Parle-t-il français ?","Il parle-t-il français ?","Parle français-il ?"],"answer":1},{"q":"How do you start an answer to {{Pourquoi ?}}","options":["Pour quoi...","Quand...","Parce que...","Comme..."],"answer":2},{"q":"Listen. What is the question?","say":"Combien ça coûte ?","options":["How does it work?","When does it close?","How much does it cost?","What is that thing?"],"answer":2}]}]},{"id":"u4-adjectives","icon":"bel","title":"Adjectives: Agreement & Placement","subtitle":"Match the noun, and find the right spot","minutes":15,"goals":["Make adjectives agree in gender and number","Put most adjectives after the noun","Know the BAGS adjectives that go before"],"blocks":[{"type":"text","text":"French adjectives are like chameleons: they change to match their noun, masculine or feminine, singular or plural. And most of them come **after** the noun."},{"type":"table","head":["","Singular","Plural"],"rows":[["Masculine","{{petit}}","{{petits}}"],["Feminine","{{petite}}","{{petites}}"]],"title":"Agreement: petit (small)"},{"type":"tip","kind":"tip","text":"Adding -e often makes the last consonant heard: {{petit}} is 'puh-TEE', {{petite}} is 'puh-TEET'. The plural -s stays silent."},{"type":"tip","kind":"warn","text":"Adjectives that already end in -e don't change for feminine: {{un homme calme, une femme calme}}."},{"type":"examples","items":[{"t":"heureux, heureuse","tr":"uh-RUH, uh-RUHZ","mean":"happy (-eux becomes -euse)"},{"t":"sportif, sportive","tr":"spor-TEEF, spor-TEEV","mean":"sporty (-f becomes -ve)"},{"t":"bon, bonne","tr":"BOHN, BUN","mean":"good (double the N)"},{"t":"gentil, gentille","tr":"zhahn-TEE, zhahn-TEEY","mean":"kind (double the L)"},{"t":"cher, chère","tr":"SHEHR, SHEHR","mean":"dear / expensive (add an accent)"},{"t":"blanc, blanche","tr":"BLAHN, BLAHNSH","mean":"white (fully irregular)"}],"title":"Special feminine forms"},{"type":"rule","name":"Most adjectives go after the noun","color":"blue","desc":"Colours, nationalities, shapes and most descriptions follow the noun.","examples":[{"t":"un film français","tr":"an feelm frahn-SEH"},{"t":"une voiture rouge","tr":"ewn vwah-tewr ROOZH"},{"t":"des gens sympas","tr":"day zhahn san-PAH"},{"t":"une idée intéressante","tr":"ew-nee-day an-tay-reh-SAHNT"}]},{"type":"rule","name":"BAGS adjectives go before","color":"green","desc":"Short, common adjectives of **B**eauty, **A**ge, **G**oodness and **S**ize come before the noun.","how":"Beauty: {{beau, joli}} · Age: {{jeune, vieux, nouveau}} · Good/bad: {{bon, mauvais}} · Size: {{petit, grand, gros}}","examples":[{"t":"un beau jardin","tr":"an boh zhar-DAN"},{"t":"une jolie maison","tr":"ewn zhoh-lee meh-ZOHN"},{"t":"un vieux livre","tr":"an vyuh LEEVR"},{"t":"une bonne idée","tr":"ewn bun-nee-DAY"},{"t":"un petit chat","tr":"an puh-tee SHAH"},{"t":"un grand appartement","tr":"an grahn-tah-par-tuh-MAHN"}]},{"type":"tip","kind":"memory","text":"BAGS = **B**eauty, **A**ge, **G**ood or bad, **S**ize. If the adjective fits in a BAG, it goes before the noun!"},{"type":"table","head":["Masculine","Masculine before a vowel","Feminine"],"rows":[["{{beau}}","{{bel}}: {{un bel homme}}","{{belle}}"],["{{nouveau}}","{{nouvel}}: {{un nouvel ami}}","{{nouvelle}}"],["{{vieux}}","{{vieil}}: {{un vieil ami}}","{{vieille}}"]],"title":"Three special adjectives"},{"type":"sentence","t":"J'ai une petite voiture rouge.","tr":"zhay ewn puh-teet vwah-tewr ROOZH","mean":"I have a small red car.","words":[{"t":"J'ai","mean":"I have"},{"t":"une","mean":"a"},{"t":"petite","mean":"small"},{"t":"voiture","mean":"car"},{"t":"rouge","mean":"red"}],"note":"{{petite}} (size) goes before the noun, {{rouge}} (colour) goes after."},{"type":"examples","items":[{"t":"Il est grand et sportif.","tr":"eel eh grahn ay spor-TEEF","mean":"He's tall and sporty."},{"t":"Elle est intelligente et drôle.","tr":"el eh-tan-teh-lee-ZHAHNT ay DROHL","mean":"She's clever and funny."},{"t":"Mes amis sont sympas.","tr":"may-zah-mee sohn san-PAH","mean":"My friends are nice."},{"t":"Ma grand-mère est petite mais très active.","tr":"mah grahn-mehr eh puh-TEET meh treh-zak-TEEV","mean":"My grandmother is small but very active."}],"title":"Describing people"},{"type":"practice","text":"Read aloud and listen for the feminine endings.","lines":["un garçon grand, une fille grande","un chat noir, une chemise noire","un homme heureux, une femme heureuse","un beau jardin, une belle maison","un vieil ami, une vieille amie"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Complete: une maison ___ (blanc)","options":["blanche","blanc","blance","blanches"],"answer":0},{"q":"How do you say 'an interesting book'?","options":["un livre intéressant","un intéressant livre","intéressant un livre"],"answer":0},{"q":"Which adjective goes BEFORE the noun?","options":["rouge","française","jolie","intéressante"],"answer":2,"explain":"{{joli}} is a Beauty adjective: BAGS."},{"q":"Listen. What does it mean?","say":"une bonne idée","options":["a good idea","a nice house","a new idea","a bad idea"],"answer":0},{"q":"Complete (old): un ___ ami","options":["vieux","vieille","vieil"],"answer":2,"explain":"Before a masculine noun starting with a vowel, {{vieux}} becomes {{vieil}}."},{"q":"Complete (happy): Elles sont ___.","options":["heureuses","heureux","heureuse","heureuxes"],"answer":0},{"q":"How do you say 'a big red car'?","options":["une grande voiture rouge","une voiture grande rouge","une rouge grande voiture","un grand voiture rouge"],"answer":0}]}]},{"id":"u4-possessives","icon":"mon","title":"Possessives: my, your, his, her","subtitle":"Match the thing, not the owner","minutes":13,"goals":["Use all the possessive adjectives","Choose the right form for gender and number","Avoid the his/her trap"],"blocks":[{"type":"text","text":"In French, 'my', 'your', 'his' and 'her' agree with the **thing owned**, not with the owner. This one idea makes everything click."},{"type":"table","head":["Owner","Masculine noun","Feminine noun","Plural noun"],"rows":[["my","{{mon}}","{{ma}}","{{mes}}"],["your (tu)","{{ton}}","{{ta}}","{{tes}}"],["his / her / its","{{son}}","{{sa}}","{{ses}}"],["our","{{notre}}","{{notre}}","{{nos}}"],["your (vous)","{{votre}}","{{votre}}","{{vos}}"],["their","{{leur}}","{{leur}}","{{leurs}}"]],"title":"Possessive adjectives"},{"type":"rule","name":"His or her? Same word!","color":"red","desc":"{{son, sa, ses}} agree with the noun, not the owner. So {{sa mère}} can mean **his** mother or **her** mother.","examples":[{"t":"Paul aime sa mère.","tr":"pohl em sah MEHR"},{"t":"Julie aime son père.","tr":"zhew-lee em sohn PEHR"}]},{"type":"tip","kind":"memory","text":"Look at the thing, not the person. {{voiture}} is feminine, so it's always {{sa voiture}}: his car or her car. The context tells you which."},{"type":"rule","name":"mon, ton, son before a vowel","color":"orange","desc":"Before a feminine noun starting with a vowel or silent h, use {{mon, ton, son}} so the words flow.","examples":[{"t":"mon amie","tr":"moh-nah-MEE"},{"t":"ton école","tr":"toh-nay-KOL"},{"t":"son histoire","tr":"soh-nees-TWAHR"}]},{"type":"examples","items":[{"t":"Voici notre maison.","tr":"vwah-see noh-truh meh-ZOHN","mean":"Here's our house."},{"t":"Où sont vos clés ?","tr":"oo sohn voh KLAY","mean":"Where are your keys?"},{"t":"Leurs enfants sont gentils.","tr":"luhr-zahn-FAHN sohn zhahn-TEE","mean":"Their children are kind."},{"t":"C'est ton sac ?","tr":"seh tohn SAK","mean":"Is this your bag?"}]},{"type":"tip","kind":"tip","text":"French has no apostrophe-s. 'My brother's jumper' is {{le pull de mon frère}}: 'the jumper of my brother'."},{"type":"sentence","t":"Marc cherche ses clés et son téléphone.","tr":"mark shehrsh say KLAY ay sohn tay-lay-FON","mean":"Marc is looking for his keys and his phone.","words":[{"t":"Marc","mean":"Marc"},{"t":"cherche","mean":"is looking for"},{"t":"ses","mean":"his (plural)"},{"t":"clés","mean":"keys"},{"t":"et","mean":"and"},{"t":"son","mean":"his (masc.)"},{"t":"téléphone","mean":"phone"}]},{"type":"dialogue","lines":[{"who":"Mum","t":"Lina, c'est ton pull ?","tr":"lee-NAH, seh tohn PEWL","mean":"Lina, is this your jumper?"},{"who":"Lina","t":"Non, c'est le pull de mon frère.","tr":"NOHN, seh luh pewl duh mohn FREHR","mean":"No, it's my brother's jumper."},{"who":"Mum","t":"Et ces chaussures ?","tr":"ay say shoh-SEWR","mean":"And these shoes?"},{"who":"Lina","t":"Ce sont ses chaussures aussi !","tr":"suh sohn say shoh-sewr oh-SEE","mean":"They're his shoes too!"},{"who":"Mum","t":"Les enfants, votre chambre est un désastre !","tr":"lay-zahn-FAHN, voh-truh shahmbr eh-tan day-ZASTR","mean":"Kids, your room is a disaster!"}],"title":"Whose is it?"},{"type":"practice","text":"Read aloud. Point at the thing, not the owner!","lines":["mon frère, ma sœur, mes parents","ton livre, ta clé, tes amis","son chat, sa maison, ses enfants","notre ville, votre voiture, leurs vacances"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Complete (my): ___ sœur","options":["mon","mes","ma"],"answer":2},{"q":"{{Il aime sa voiture.}} Whose car is it?","options":["His car","Her car","Your car"],"answer":0,"explain":"{{sa}} agrees with {{voiture}} (feminine). The owner is {{il}}, so: his car."},{"q":"Complete (my): ___ amie Léa","options":["mon","ma","m'"],"answer":0,"explain":"Before a vowel, use {{mon}} even for a feminine noun."},{"q":"How do you say 'their parents'?","options":["leur parents","ses parents","son parents","leurs parents"],"answer":3},{"q":"Listen. What does it mean?","say":"nos enfants","options":["your children","their children","no children","our children"],"answer":3},{"q":"How do you say 'Anna's book'?","options":["Anna's livre","le livre d'Anna","le Anna livre","livre de l'Anna"],"answer":1},{"q":"Complete (your, polite): Vous avez ___ passeport ?","options":["votre","vos","ton"],"answer":0}]}]},{"id":"u4-aller","icon":"va","title":"Aller & the Near Future","subtitle":"Going places and talking about plans","minutes":14,"goals":["Conjugate aller","Use au, à la, à l' and aux","Talk about plans with aller + infinitive"],"blocks":[{"type":"text","text":"{{aller}} (to go) is irregular but super useful. Bonus: it also builds the easiest future tense in French, the **futur proche** (near future)."},{"type":"table","head":["Pronoun","aller","Say it","Meaning"],"rows":[["{{je}}","{{vais}}","zhuh VEH","I go / I'm going"],["{{tu}}","{{vas}}","tew VAH","you go"],["{{il / elle / on}}","{{va}}","eel / el / ohn VAH","he / she / one goes"],["{{nous}}","{{allons}}","noo-zah-LOHN","we go"],["{{vous}}","{{allez}}","voo-zah-LAY","you go"],["{{ils / elles}}","{{vont}}","eel / el VOHN","they go"]],"title":"aller (to go): present"},{"type":"table","head":["à +","becomes","Example"],"rows":[["{{le}}","{{au}}","{{Je vais au parc.}}"],["{{la}}","{{à la}}","{{Je vais à la gare.}}"],["{{l'}}","{{à l'}}","{{Je vais à l'hôpital.}}"],["{{les}}","{{aux}}","{{Je vais aux magasins.}}"]],"title":"Going to: à + the"},{"type":"tip","kind":"warn","text":"Never say {{à le}} or {{à les}}: they always merge into {{au}} and {{aux}}."},{"type":"tip","kind":"tip","text":"Going to someone's place? Use {{chez}}: {{Je vais chez Marie}} (to Marie's), {{chez le médecin}} (to the doctor's)."},{"type":"rule","name":"The near future: aller + infinitive","color":"green","desc":"Present of {{aller}} + a verb in the infinitive = 'going to do'. It's the everyday way to talk about plans.","examples":[{"t":"Je vais manger.","tr":"zhuh veh mahn-ZHAY"},{"t":"Tu vas voir !","tr":"tew vah VWAHR"},{"t":"Nous allons voyager en Italie.","tr":"noo-zah-lohn vwah-yah-ZHAY ahn-nee-tah-LEE"},{"t":"Ils vont arriver demain.","tr":"eel vohn-tah-ree-VAY duh-MAN"}]},{"type":"tip","kind":"memory","text":"Just like English: 'I'm going to eat' = {{Je vais manger}}. Just don't add a word for 'to'!"},{"type":"rule","name":"Negative: wrap aller","color":"red","desc":"{{ne... pas}} goes around {{aller}}, not around the infinitive.","examples":[{"t":"Je ne vais pas travailler demain.","tr":"zhuh nuh veh pah trah-vah-YAY duh-MAN"},{"t":"Il ne va pas pleuvoir.","tr":"eel nuh vah pah pluh-VWAHR"}]},{"type":"vocab","items":[{"t":"ce soir","tr":"suh SWAHR","mean":"tonight / this evening"},{"t":"demain","tr":"duh-MAN","mean":"tomorrow"},{"t":"après-demain","tr":"ah-preh-duh-MAN","mean":"the day after tomorrow"},{"t":"ce week-end","tr":"suh wee-KEND","mean":"this weekend"},{"t":"la semaine prochaine","tr":"lah suh-men proh-SHEN","mean":"next week"},{"t":"l'année prochaine","tr":"lah-nay proh-SHEN","mean":"next year"},{"t":"bientôt","tr":"byan-TOH","mean":"soon"},{"t":"plus tard","tr":"plew TAR","mean":"later"}],"title":"Future time words"},{"type":"sentence","t":"Ce soir, je vais regarder un film.","tr":"suh SWAHR, zhuh veh ruh-gar-DAY an FEELM","mean":"Tonight, I'm going to watch a film.","words":[{"t":"Ce","mean":"this"},{"t":"soir","mean":"evening"},{"t":"je","mean":"I"},{"t":"vais","mean":"am going"},{"t":"regarder","mean":"to watch"},{"t":"un","mean":"a"},{"t":"film","mean":"film"}]},{"type":"dialogue","lines":[{"who":"Zoé","t":"Qu'est-ce que tu vas faire ce week-end ?","tr":"kess-kuh tew vah fehr suh wee-KEND","mean":"What are you going to do this weekend?"},{"who":"Adam","t":"Je vais aller à la montagne avec mes parents.","tr":"zhuh veh-zah-LAY ah lah mohn-TANY ah-vek may pah-RAHN","mean":"I'm going to go to the mountains with my parents."},{"who":"Zoé","t":"Vous allez faire du ski ?","tr":"voo-zah-lay fehr dew SKEE","mean":"Are you going to ski?"},{"who":"Adam","t":"Non, on va faire de la randonnée. Et toi ?","tr":"NOHN, ohn vah fehr duh lah rahn-doh-NAY. ay TWAH","mean":"No, we're going to go hiking. And you?"},{"who":"Zoé","t":"Moi, je vais rester à la maison et dormir !","tr":"MWAH, zhuh veh res-TAY ah lah meh-ZOHN ay dor-MEER","mean":"Me? I'm going to stay at home and sleep!"}],"title":"Weekend plans"},{"type":"practice","text":"Say your plans aloud.","lines":["je vais, tu vas, il va, nous allons, vous allez, ils vont","Je vais au cinéma ce soir.","Nous allons à la plage demain.","Elle va étudier ce week-end.","Je ne vais pas sortir."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"nous ___ (aller)","options":["allez","vont","vais","allons"],"answer":3},{"q":"Complete: Je vais ___ cinéma.","options":["à le","à la","aux","au"],"answer":3,"explain":"{{cinéma}} is masculine: {{à + le = au}}."},{"q":"How do you say 'I'm going to eat'?","options":["Je vais à manger.","Je mange aller.","Je vais manger.","Je vais mange."],"answer":2},{"q":"Listen. When will they leave?","say":"Ils vont partir demain.","options":["yesterday","right now","every day","tomorrow"],"answer":3},{"q":"Make it negative: {{Je vais travailler.}}","options":["Je vais travailler pas.","Je ne vais travailler pas.","Je ne vais pas travailler.","Ne je vais pas travailler."],"answer":2},{"q":"Complete: Elle va ___ États-Unis.","options":["au","aux","à les","à la"],"answer":1,"explain":"{{les États-Unis}} is plural: {{à + les = aux}}."},{"q":"What does {{la semaine prochaine}} mean?","options":["last week","this week","every week","next week"],"answer":3}]}]},{"id":"u4-irregular","icon":"fait","title":"Key Irregular Verbs","subtitle":"faire, prendre, vouloir, pouvoir, venir","minutes":18,"goals":["Conjugate faire, prendre, vouloir, pouvoir and venir","Use them in everyday phrases","Spot the patterns they share"],"blocks":[{"type":"text","text":"A handful of irregular verbs turn up in almost every conversation. Learn these five and you can **do**, **take**, **want**, **be able to** and **come**!"},{"type":"table","head":["Pronoun","faire","Say it"],"rows":[["{{je}}","{{fais}}","zhuh FEH"],["{{tu}}","{{fais}}","tew FEH"],["{{il / elle / on}}","{{fait}}","eel FEH"],["{{nous}}","{{faisons}}","noo fuh-ZOHN"],["{{vous}}","{{faites}}","voo FET"],["{{ils / elles}}","{{font}}","eel FOHN"]],"title":"faire (to do / to make)"},{"type":"vocab","items":[{"t":"faire les courses","tr":"fehr lay KOORS","mean":"to do the shopping"},{"t":"faire la cuisine","tr":"fehr lah kwee-ZEEN","mean":"to cook"},{"t":"faire du sport","tr":"fehr dew SPOR","mean":"to do sport"},{"t":"faire une promenade","tr":"fehr ewn prom-NAHD","mean":"to go for a walk"},{"t":"Il fait beau.","tr":"eel feh BOH","mean":"The weather's nice."},{"t":"Il fait froid.","tr":"eel feh FRWAH","mean":"It's cold (weather)."}],"title":"Everyday faire"},{"type":"tip","kind":"warn","text":"{{faisons}} is said 'fuh-ZOHN', not 'fay-ZOHN'. And it's {{vous faites}}, never 'vous faisez'!"},{"type":"table","head":["Pronoun","prendre","Say it"],"rows":[["{{je}}","{{prends}}","zhuh PRAHN"],["{{tu}}","{{prends}}","tew PRAHN"],["{{il / elle / on}}","{{prend}}","eel PRAHN"],["{{nous}}","{{prenons}}","noo pruh-NOHN"],["{{vous}}","{{prenez}}","voo pruh-NAY"],["{{ils / elles}}","{{prennent}}","eel PREN"]],"title":"prendre (to take)"},{"type":"tip","kind":"tip","text":"Use {{prendre}} for food, drinks and transport: {{Je prends un café}} (I'll have a coffee), {{Je prends le bus}}. Its cousins follow the same pattern: {{apprendre}} (to learn), {{comprendre}} (to understand)."},{"type":"table","head":["Pronoun","vouloir (to want)","pouvoir (can, to be able to)"],"rows":[["{{je}}","{{veux}}","{{peux}}"],["{{tu}}","{{veux}}","{{peux}}"],["{{il / elle / on}}","{{veut}}","{{peut}}"],["{{nous}}","{{voulons}}","{{pouvons}}"],["{{vous}}","{{voulez}}","{{pouvez}}"],["{{ils / elles}}","{{veulent}}","{{peuvent}}"]],"title":"Twin verbs: vouloir & pouvoir"},{"type":"examples","items":[{"t":"Tu veux un café ?","tr":"tew vuh an kah-FAY","mean":"Do you want a coffee?"},{"t":"Je peux entrer ?","tr":"zhuh puh ahn-TRAY","mean":"Can I come in?"},{"t":"Vous pouvez répéter, s'il vous plaît ?","tr":"voo poo-vay ray-pay-TAY, seel voo PLEH","mean":"Could you repeat that, please?"},{"t":"Ils veulent partir.","tr":"eel vuhl par-TEER","mean":"They want to leave."}]},{"type":"tip","kind":"culture","text":"{{Je veux}} can sound blunt. Soften it with {{je voudrais}} (I would like) or ask {{Tu pourrais...?}} (Could you...?)."},{"type":"table","head":["Pronoun","venir","Say it"],"rows":[["{{je}}","{{viens}}","zhuh VYAN"],["{{tu}}","{{viens}}","tew VYAN"],["{{il / elle / on}}","{{vient}}","eel VYAN"],["{{nous}}","{{venons}}","noo vuh-NOHN"],["{{vous}}","{{venez}}","voo vuh-NAY"],["{{ils / elles}}","{{viennent}}","eel VYEN"]],"title":"venir (to come)"},{"type":"tip","kind":"memory","text":"Spot the 'boot' pattern in {{prendre, vouloir, pouvoir, venir}}: {{nous}} and {{vous}} keep the short stem from the infinitive ({{pren-, voul-, pouv-, ven-}}), while the other forms change."},{"type":"tip","kind":"tip","text":"{{venir de}} + infinitive = 'to have just done': {{Je viens de manger}} = I've just eaten."},{"type":"sentence","t":"Tu veux venir au cinéma avec nous ?","tr":"tew vuh vuh-NEER oh see-nay-MAH ah-vek NOO","mean":"Do you want to come to the cinema with us?","words":[{"t":"Tu","mean":"you"},{"t":"veux","mean":"want"},{"t":"venir","mean":"to come"},{"t":"au","mean":"to the"},{"t":"cinéma","mean":"cinema"},{"t":"avec","mean":"with"},{"t":"nous","mean":"us"}]},{"type":"dialogue","lines":[{"who":"Ana","t":"Qu'est-ce que tu fais ?","tr":"kess-kuh tew FEH","mean":"What are you doing?"},{"who":"Tom","t":"Je fais mes devoirs.","tr":"zhuh feh may duh-VWAHR","mean":"I'm doing my homework."},{"who":"Ana","t":"On va au parc. Tu veux venir ?","tr":"ohn vah oh PARK. tew vuh vuh-NEER","mean":"We're going to the park. Do you want to come?"},{"who":"Tom","t":"Je ne peux pas, je dois finir.","tr":"zhuh nuh puh PAH, zhuh dwah fee-NEER","mean":"I can't, I have to finish."},{"who":"Ana","t":"Dommage ! Tu viens demain, alors ?","tr":"doh-MAHZH. tew vyan duh-MAN, ah-LOR","mean":"Shame! Will you come tomorrow, then?"},{"who":"Tom","t":"Oui, je prends le bus à dix heures.","tr":"WEE, zhuh prahn luh bewss ah dee-ZUHR","mean":"Yes, I'll take the bus at ten."}]},{"type":"practice","text":"Conjugate each verb aloud.","lines":["je fais, tu fais, il fait, nous faisons, vous faites, ils font","je prends, nous prenons, ils prennent","je veux, nous voulons, ils veulent","je peux, nous pouvons, ils peuvent","je viens, nous venons, ils viennent"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"vous ___ (faire)","options":["faisez","faites","font","faisons"],"answer":1},{"q":"ils ___ (prendre)","options":["prendent","prenent","prennent","prends"],"answer":2},{"q":"Listen. What does it mean?","say":"Je peux entrer ?","options":["Do I want to come in?","Can I come in?","Can you come in?","Must I come in?"],"answer":1},{"q":"How do you say 'The weather is nice'?","options":["Il est beau temps.","C'est beau météo.","Il a beau.","Il fait beau."],"answer":3},{"q":"What does {{Je viens de manger}} mean?","options":["I've just eaten.","I'm about to eat.","I'm coming to eat."],"answer":0},{"q":"nous ___ (vouloir)","options":["veulons","voulez","voulons","veux"],"answer":2},{"q":"Which is the most polite?","options":["Je veux un café, moi.","Donne-moi un café !","Je voudrais un café."],"answer":2}]}]},{"id":"u4-pronouns","icon":"lui","title":"Pronouns: I, me, him, it","subtitle":"Subject, object and stressed pronouns","minutes":15,"goals":["Know all the subject pronouns","Use direct object pronouns: le, la, les","Use stressed pronouns: moi, toi, lui..."],"blocks":[{"type":"text","text":"Pronouns save you from repeating nouns. You already know the subject pronouns ({{je, tu, il}}...). Now meet the pronouns that replace objects, and find out where they hide in the sentence."},{"type":"table","head":["Subject","Object","Stressed","English"],"rows":[["{{je}}","{{me (m')}}","{{moi}}","I / me"],["{{tu}}","{{te (t')}}","{{toi}}","you"],["{{il}}","{{le (l')}}","{{lui}}","he / him / it"],["{{elle}}","{{la (l')}}","{{elle}}","she / her / it"],["{{nous}}","{{nous}}","{{nous}}","we / us"],["{{vous}}","{{vous}}","{{vous}}","you"],["{{ils}}","{{les}}","{{eux}}","they / them (m)"],["{{elles}}","{{les}}","{{elles}}","they / them (f)"]],"title":"Three kinds of pronoun"},{"type":"rule","name":"Object pronouns go BEFORE the verb","color":"purple","desc":"Unlike English, the object pronoun comes before the verb. {{le}} and {{la}} become {{l'}} before a vowel.","examples":[{"t":"Je le regarde.","tr":"zhuh luh ruh-GARD"},{"t":"Tu la connais ?","tr":"tew lah koh-NEH"},{"t":"Il les aime.","tr":"eel lay-ZEM"}]},{"type":"examples","items":[{"t":"Je le regarde.","tr":"zhuh luh ruh-GARD","mean":"I'm watching it.","note":"{{le}} = {{le film}}, from {{Je regarde le film.}}"},{"t":"Tu la connais ?","tr":"tew lah koh-NEH","mean":"Do you know her?","note":"{{la}} = {{Marie}}, from {{Tu connais Marie ?}}"},{"t":"Il les aime.","tr":"eel lay-ZEM","mean":"He likes them.","note":"{{les}} = {{les chats}}, from {{Il aime les chats.}}"},{"t":"Elle m'appelle ce soir.","tr":"el mah-pel suh SWAHR","mean":"She's calling me tonight."},{"t":"Je t'aime.","tr":"zhuh TEM","mean":"I love you."}],"title":"From noun to pronoun"},{"type":"tip","kind":"memory","text":"Think of a magnet: the object pronoun sticks to the **front** of the verb. {{Je t'aime}} is literally 'I you love'."},{"type":"rule","name":"With ne... pas and with two verbs","color":"blue","desc":"Negative: {{ne}} + pronoun + verb + {{pas}}. With two verbs, the pronoun goes before the infinitive.","examples":[{"t":"Je ne le vois pas.","tr":"zhuh nuh luh vwah PAH"},{"t":"Je vais le faire.","tr":"zhuh veh luh FEHR"},{"t":"Tu peux m'aider ?","tr":"tew puh meh-DAY"}]},{"type":"rule","name":"Stressed pronouns","color":"green","desc":"Use {{moi, toi, lui, elle, nous, vous, eux, elles}} after a preposition, for emphasis, and on their own.","examples":[{"t":"Moi, je suis prof.","tr":"MWAH, zhuh swee PROF"},{"t":"C'est pour toi.","tr":"seh poor TWAH"},{"t":"Il vient avec nous.","tr":"eel vyan ah-vek NOO"},{"t":"Et lui ?","tr":"ay LWEE"},{"t":"Chez eux.","tr":"sheh ZUH"}]},{"type":"tip","kind":"tip","text":"{{Moi aussi}} = Me too. {{Moi non plus}} = Me neither. {{C'est moi !}} = It's me!"},{"type":"sentence","t":"Ce livre, je le lis ce soir.","tr":"suh LEEVR, zhuh luh lee suh SWAHR","mean":"That book? I'm reading it tonight.","words":[{"t":"Ce","mean":"this"},{"t":"livre","mean":"book"},{"t":"je","mean":"I"},{"t":"le","mean":"it"},{"t":"lis","mean":"read"},{"t":"ce","mean":"this"},{"t":"soir","mean":"evening"}]},{"type":"dialogue","lines":[{"who":"Paul","t":"Tu connais Léa ?","tr":"tew koh-neh lay-AH","mean":"Do you know Léa?"},{"who":"Nora","t":"Oui, je la connais bien.","tr":"WEE, zhuh lah koh-neh BYAN","mean":"Yes, I know her well."},{"who":"Paul","t":"Tu peux l'inviter à ma fête ?","tr":"tew puh lan-vee-TAY ah mah FET","mean":"Can you invite her to my party?"},{"who":"Nora","t":"D'accord. Et ses frères ?","tr":"dah-KOR. ay say FREHR","mean":"OK. And her brothers?"},{"who":"Paul","t":"Non, je ne les invite pas. Ils sont pénibles !","tr":"NOHN, zhuh nuh lay-zan-veet PAH. eel sohn pay-NEEBL","mean":"No, I'm not inviting them. They're annoying!"},{"who":"Nora","t":"D'accord, pas eux !","tr":"dah-KOR, pah-ZUH","mean":"OK, not them!"}],"title":"Party plans"},{"type":"practice","text":"Replace the noun with a pronoun aloud, then check the second line.","lines":["Je mange la pomme.","Je la mange.","Tu regardes le match ?","Tu le regardes ?","Elle aime ses amis.","Elle les aime."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Replace the noun: Je mange la pomme. → Je ___ mange.","options":["le","lui","la","les"],"answer":2},{"q":"How do you say 'I see him'?","options":["Je le vois.","Je vois le.","Je vois lui.","Le je vois."],"answer":0,"explain":"The object pronoun goes before the verb."},{"q":"Listen. What does it mean?","say":"Je t'aime.","options":["I love you.","I like it.","I'm calling you.","You love me."],"answer":0},{"q":"Complete (me): C'est pour ___.","options":["me","moi","je","m'"],"answer":1,"explain":"After a preposition like {{pour}}, use a stressed pronoun."},{"q":"Replace the noun: {{Il regarde les photos.}}","options":["Il les regarde.","Il regarde les.","Il leur regarde.","Les il regarde."],"answer":0},{"q":"Make it negative: {{Je le vois.}}","options":["Je le ne vois pas.","Je ne le vois pas.","Je ne vois le pas.","Ne je le vois pas."],"answer":1},{"q":"What does {{Moi aussi}} mean?","options":["Me neither","Me too","Not me","Me first"],"answer":1}]}]},{"id":"u4-passe-avoir","icon":"vu","title":"The Past (1): Passé Composé with Avoir","subtitle":"Say what you did","minutes":16,"goals":["Form the passé composé with avoir","Make past participles of regular verbs","Use common irregular participles"],"blocks":[{"type":"text","text":"To say what you **did**, French uses the **passé composé** (compound past). It has two parts: a helper verb, usually {{avoir}}, plus a past participle. You already know {{avoir}}!"},{"type":"rule","name":"avoir + past participle","color":"green","desc":"Present of {{avoir}} + past participle = 'I did' or 'I have done'.","examples":[{"t":"J'ai mangé.","tr":"zhay mahn-ZHAY"},{"t":"Tu as fini ?","tr":"tew ah fee-NEE"},{"t":"Nous avons vendu la voiture.","tr":"noo-zah-vohn vahn-DEW lah vwah-TEWR"}]},{"type":"table","head":["Infinitive ends in","Participle ends in","Example"],"rows":[["-er","-é","{{parler}} → {{parlé}}"],["-ir","-i","{{finir}} → {{fini}}"],["-re","-u","{{vendre}} → {{vendu}}"]],"title":"Making the past participle"},{"type":"table","head":["French","Say it","English"],"rows":[["{{j'ai mangé}}","zhay mahn-ZHAY","I ate / I have eaten"],["{{tu as mangé}}","tew ah mahn-ZHAY","you ate"],["{{il / elle a mangé}}","eel ah mahn-ZHAY","he / she ate"],["{{nous avons mangé}}","noo-zah-vohn mahn-ZHAY","we ate"],["{{vous avez mangé}}","voo-zah-vay mahn-ZHAY","you ate"],["{{ils / elles ont mangé}}","eel-zohn mahn-ZHAY","they ate"]],"title":"manger in the passé composé"},{"type":"tip","kind":"tip","text":"One French form = two English ones: {{J'ai mangé}} means 'I ate' **and** 'I have eaten'."},{"type":"vocab","items":[{"t":"j'ai eu","tr":"zhay EW","mean":"I had (avoir)"},{"t":"j'ai été","tr":"zhay ay-TAY","mean":"I was / I have been (être)"},{"t":"j'ai fait","tr":"zhay FEH","mean":"I did / I made (faire)"},{"t":"j'ai pris","tr":"zhay PREE","mean":"I took (prendre)"},{"t":"j'ai vu","tr":"zhay VEW","mean":"I saw (voir)"},{"t":"j'ai bu","tr":"zhay BEW","mean":"I drank (boire)"},{"t":"j'ai lu","tr":"zhay LEW","mean":"I read (lire)"},{"t":"j'ai dit","tr":"zhay DEE","mean":"I said (dire)"},{"t":"j'ai écrit","tr":"zhay ay-KREE","mean":"I wrote (écrire)"},{"t":"j'ai voulu","tr":"zhay voo-LEW","mean":"I wanted (vouloir)"},{"t":"j'ai pu","tr":"zhay PEW","mean":"I was able to (pouvoir)"},{"t":"j'ai mis","tr":"zhay MEE","mean":"I put (mettre)"}],"title":"Irregular participles"},{"type":"rule","name":"Negative: wrap avoir","color":"red","desc":"{{ne... pas}} goes around {{avoir}} only. The participle stays outside.","examples":[{"t":"Je n'ai pas mangé.","tr":"zhuh neh pah mahn-ZHAY"},{"t":"Il n'a pas vu le film.","tr":"eel nah pah vew luh FEELM"},{"t":"Nous n'avons rien fait.","tr":"noo nah-vohn ryan FEH"}]},{"type":"tip","kind":"memory","text":"Sandwich again: {{ne + ai + pas}}, then the participle sits outside the bread: {{Je n'ai pas fini}}."},{"type":"vocab","items":[{"t":"hier","tr":"ee-YEHR","mean":"yesterday"},{"t":"hier soir","tr":"ee-yehr SWAHR","mean":"last night"},{"t":"ce matin","tr":"suh mah-TAN","mean":"this morning"},{"t":"la semaine dernière","tr":"lah suh-men dehr-NYEHR","mean":"last week"},{"t":"l'année dernière","tr":"lah-nay dehr-NYEHR","mean":"last year"},{"t":"il y a deux jours","tr":"eel-yah duh ZHOOR","mean":"two days ago"},{"t":"déjà","tr":"day-ZHAH","mean":"already"}],"title":"Past time words"},{"type":"sentence","t":"Hier soir, j'ai vu un film avec mes amis.","tr":"ee-yehr SWAHR, zhay vew an FEELM ah-vek may-zah-MEE","mean":"Last night, I saw a film with my friends.","words":[{"t":"Hier","mean":"yesterday"},{"t":"soir","mean":"evening"},{"t":"j'ai","mean":"I have"},{"t":"vu","mean":"seen"},{"t":"un","mean":"a"},{"t":"film","mean":"film"},{"t":"avec","mean":"with"},{"t":"mes","mean":"my"},{"t":"amis","mean":"friends"}]},{"type":"dialogue","lines":[{"who":"Clara","t":"Tu as passé un bon week-end ?","tr":"tew ah pah-SAY an bohn wee-KEND","mean":"Did you have a good weekend?"},{"who":"Omar","t":"Oui ! Samedi, j'ai joué au foot.","tr":"WEE. sahm-DEE, zhay zhoo-AY oh FOOT","mean":"Yes! On Saturday, I played football."},{"who":"Clara","t":"Et dimanche ?","tr":"ay dee-MAHNSH","mean":"And on Sunday?"},{"who":"Omar","t":"J'ai fait un gâteau et j'ai lu un livre.","tr":"zhay feh an gah-TOH ay zhay lew an LEEVR","mean":"I made a cake and I read a book."},{"who":"Clara","t":"Tu as fini le livre ?","tr":"tew ah fee-NEE luh LEEVR","mean":"Did you finish the book?"},{"who":"Omar","t":"Non, pas encore !","tr":"NOHN, pah-zahn-KOR","mean":"No, not yet!"}],"title":"Monday morning"},{"type":"practice","text":"Tell your last weekend aloud.","lines":["Samedi, j'ai regardé un film.","Dimanche, j'ai fait du sport.","J'ai mangé une pizza.","Je n'ai pas travaillé.","Hier soir, j'ai lu un livre."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"What is the past participle of {{finir}}?","options":["finé","finu","fini","finit"],"answer":2},{"q":"How do you say 'I ate'?","options":["Je suis mangé.","Je mangé.","J'ai mangé.","J'ai manger."],"answer":2},{"q":"What is the past participle of {{faire}}?","options":["faisé","fait","fairé","fu"],"answer":1},{"q":"Listen. What did they do?","say":"Nous avons vu la mer.","options":["We want the sea.","We saw the sea.","We'll see the sea.","We love the sea."],"answer":1},{"q":"Make it negative: {{J'ai fini.}}","options":["Je n'ai fini pas.","Je n'ai pas fini.","Je ne pas ai fini.","Je ai pas fini."],"answer":1},{"q":"What does {{J'ai pris le train}} mean?","options":["I take the train.","I took the train.","I'm going to take the train.","I missed the train."],"answer":1},{"q":"Complete: Ils ___ bu du thé.","options":["ont","sont","avons","a"],"answer":0}]}]},{"id":"u4-passe-etre","icon":"né","title":"The Past (2): Passé Composé with Être","subtitle":"Movement verbs and agreement","minutes":16,"goals":["Know which verbs use être","Make the participle agree with the subject","Tell a short story in the past"],"blocks":[{"type":"text","text":"About twenty verbs use {{être}} instead of {{avoir}} in the passé composé. Most are about **movement** or **change**: going, coming, arriving, leaving, being born, dying..."},{"type":"table","head":["Verb","Meaning","Participle"],"rows":[["{{aller}}","to go","{{allé}}"],["{{venir}}","to come","{{venu}}"],["{{arriver}}","to arrive","{{arrivé}}"],["{{partir}}","to leave","{{parti}}"],["{{entrer}}","to go in","{{entré}}"],["{{sortir}}","to go out","{{sorti}}"],["{{monter}}","to go up","{{monté}}"],["{{descendre}}","to go down","{{descendu}}"],["{{naître}}","to be born","{{né}}"],["{{mourir}}","to die","{{mort}}"],["{{rester}}","to stay","{{resté}}"],["{{tomber}}","to fall","{{tombé}}"],["{{rentrer}}","to come home","{{rentré}}"],["{{revenir}}","to come back","{{revenu}}"],["{{devenir}}","to become","{{devenu}}"],["{{retourner}}","to go back","{{retourné}}"]],"title":"The être verbs"},{"type":"tip","kind":"memory","text":"Picture the **House of Être**: you arrive ({{arriver}}), go in ({{entrer}}), go up the stairs ({{monter}}), come down ({{descendre}}), go out ({{sortir}}) and leave ({{partir}}). People are born ({{naître}}) and die ({{mourir}}) in it too!"},{"type":"rule","name":"Agreement with être","color":"purple","desc":"With {{être}}, the participle agrees with the subject, like an adjective: add **-e** for feminine and **-s** for plural.","examples":[{"t":"Il est allé.","tr":"eel eh-tah-LAY"},{"t":"Elle est allée.","tr":"el eh-tah-LAY"},{"t":"Ils sont allés.","tr":"eel sohn-tah-LAY"},{"t":"Elles sont allées.","tr":"el sohn-tah-LAY"}]},{"type":"tip","kind":"tip","text":"Good news: {{allé, allée, allés, allées}} all sound the same. The agreement usually shows only in writing."},{"type":"table","head":["French","Say it","English"],"rows":[["{{je suis allé(e)}}","zhuh swee-zah-LAY","I went"],["{{tu es allé(e)}}","tew eh-zah-LAY","you went"],["{{il est allé / elle est allée}}","eel eh-tah-LAY","he / she went"],["{{nous sommes allé(e)s}}","noo som-zah-LAY","we went"],["{{vous êtes allé(e)(s)}}","voo-zet-zah-LAY","you went"],["{{ils sont allés / elles sont allées}}","eel sohn-tah-LAY","they went"]],"title":"aller in the passé composé"},{"type":"compare","items":[{"t":"J'ai mangé.","label":"avoir: most verbs","desc":"No agreement with the subject: {{elle a mangé}}."},{"t":"Je suis parti(e).","label":"être: movement & change","desc":"Agrees with the subject: {{elle est partie}}."}],"title":"Avoir or être?"},{"type":"examples","items":[{"t":"Je suis né à Londres.","tr":"zhuh swee NAY ah LOHNDR","mean":"I was born in London."},{"t":"Elle est arrivée hier.","tr":"el eh-tah-ree-VAY ee-YEHR","mean":"She arrived yesterday."},{"t":"Nous sommes restés à la maison.","tr":"noo som res-TAY ah lah meh-ZOHN","mean":"We stayed at home."},{"t":"Tu es tombé ?","tr":"tew eh tohm-BAY","mean":"Did you fall?"},{"t":"Ils ne sont pas venus.","tr":"eel nuh sohn pah vuh-NEW","mean":"They didn't come."}]},{"type":"sentence","t":"Marie est partie en vacances lundi.","tr":"mah-REE eh par-TEE ahn vah-KAHNS lun-DEE","mean":"Marie went on holiday on Monday.","words":[{"t":"Marie","mean":"Marie"},{"t":"est","mean":"is"},{"t":"partie","mean":"left"},{"t":"en","mean":"on"},{"t":"vacances","mean":"holiday"},{"t":"lundi","mean":"Monday"}],"note":"{{partie}} has an extra -e because Marie is female."},{"type":"dialogue","lines":[{"who":"Hugo","t":"Qu'est-ce que tu as fait pendant les vacances ?","tr":"kess-kuh tew ah FEH pahn-dahn lay vah-KAHNS","mean":"What did you do during the holidays?"},{"who":"Lisa","t":"Je suis allée en Espagne avec ma sœur.","tr":"zhuh swee-zah-LAY ahn-nes-PANY ah-vek mah SUHR","mean":"I went to Spain with my sister."},{"who":"Hugo","t":"Super ! Vous êtes parties quand ?","tr":"sew-PEHR. voo-zet par-TEE KAHN","mean":"Great! When did you leave?"},{"who":"Lisa","t":"Nous sommes parties le deux août et nous sommes rentrées hier.","tr":"noo som par-TEE luh duh OOT ay noo som rahn-TRAY ee-YEHR","mean":"We left on 2 August and we came home yesterday."},{"who":"Hugo","t":"Et tu as aimé ?","tr":"ay tew ah eh-MAY","mean":"And did you like it?"},{"who":"Lisa","t":"J'ai adoré ! Mais ma sœur est tombée malade...","tr":"zhay ah-doh-RAY. meh mah suhr eh tohm-BAY mah-LAHD","mean":"I loved it! But my sister got ill..."}],"title":"Holiday story"},{"type":"practice","text":"Read the story aloud. Spot the être verbs.","lines":["Je suis né en avril.","Hier, je suis sorti avec mes amis.","Nous sommes allés au cinéma.","Ma sœur est arrivée en retard.","Nous sommes rentrés à minuit."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Which verb uses être in the passé composé?","options":["manger","regarder","finir","partir"],"answer":3},{"q":"Complete: Elle est ___ (arriver).","options":["arrivé","arrivés","arriver","arrivée"],"answer":3,"explain":"Feminine subject: add -e."},{"q":"Two men say 'We went to the cinema'. Which is correct?","options":["Nous sommes allés au cinéma.","Nous avons allé au cinéma.","Nous sommes allées au cinéma.","Nous allons au cinéma."],"answer":0},{"q":"Listen. What does it mean?","say":"Je suis né en avril.","options":["I was born in April.","I'm going in April.","I arrived in April.","I'll be back in April."],"answer":0},{"q":"Which sentence is correct?","options":["Il a tombé.","Il est tombée.","Il est tombé.","Il tombé."],"answer":2},{"q":"Make it negative: {{Ils sont venus.}}","options":["Ils ne sont pas venus.","Ils ne sont venus pas.","Ils sont ne pas venus.","Ils n'ont pas venus."],"answer":0},{"q":"Why does {{elles sont sorties}} end in -ies?","options":["The subject is feminine plural.","Sortir always ends like that.","It is the future tense."],"answer":0}]}]},{"id":"u4-prepositions","icon":"sur","title":"Prepositions of Place","subtitle":"Where things and places are","minutes":13,"goals":["Say where things and people are","Use du and des after près de, à côté de...","Use à, en, au and aux with cities and countries"],"blocks":[{"type":"text","text":"Where's my phone? Where's the station? Prepositions of place answer the question {{Où ?}} (Where?)."},{"type":"vocab","items":[{"t":"sur","tr":"SEWR","mean":"on","example":{"t":"Le chat est sur le lit.","tr":"luh shah eh sewr luh LEE","mean":"The cat is on the bed."}},{"t":"sous","tr":"SOO","mean":"under"},{"t":"dans","tr":"DAHN","mean":"in, inside"},{"t":"devant","tr":"duh-VAHN","mean":"in front of"},{"t":"derrière","tr":"deh-RYEHR","mean":"behind"},{"t":"entre","tr":"AHNTR","mean":"between"},{"t":"à côté de","tr":"ah koh-TAY duh","mean":"next to"},{"t":"près de","tr":"PREH duh","mean":"near"},{"t":"loin de","tr":"LWAN duh","mean":"far from"},{"t":"en face de","tr":"ahn FAHSS duh","mean":"opposite"},{"t":"à gauche (de)","tr":"ah GOHSH","mean":"on the left (of)"},{"t":"à droite (de)","tr":"ah DRWAHT","mean":"on the right (of)"}],"title":"Where is it?"},{"type":"tip","kind":"memory","text":"{{devant}} hides the word {{avant}} (before): in front of. {{derrière}} sounds a bit like 'derrière' in English, the thing behind you!"},{"type":"rule","name":"de + le = du","color":"orange","desc":"Prepositions ending in {{de}} follow the same rule as {{à}}: {{de + le = du}}, {{de + les = des}}. {{de la}} and {{de l'}} don't change.","examples":[{"t":"à côté du cinéma","tr":"ah koh-TAY dew see-nay-MAH"},{"t":"près de la gare","tr":"preh duh lah GAR"},{"t":"en face de l'hôtel","tr":"ahn fahss duh loh-TEL"},{"t":"loin des magasins","tr":"lwan day mah-gah-ZAN"}]},{"type":"table","head":["Place","Use","Example"],"rows":[["a city","{{à}}","{{J'habite à Rome.}}"],["a feminine country (most end in -e)","{{en}}","{{Je vais en France.}}"],["a masculine country","{{au}}","{{Il travaille au Canada.}}"],["a plural country","{{aux}}","{{Elle vit aux États-Unis.}}"]],"title":"Cities and countries"},{"type":"tip","kind":"warn","text":"Most countries ending in -e are feminine ({{la France, l'Italie}}); most others are masculine ({{le Japon, le Brésil}}). Watch out for {{le Mexique}}: masculine, so {{au Mexique}}."},{"type":"examples","items":[{"t":"La banque est entre la poste et le café.","tr":"lah bahnk eh ahntr lah POST ay luh kah-FAY","mean":"The bank is between the post office and the café."},{"t":"La pharmacie est en face de l'école.","tr":"lah far-mah-SEE eh-tahn fahss duh lay-KOL","mean":"The pharmacy is opposite the school."},{"t":"Mon appartement est près du parc.","tr":"moh-nah-par-tuh-MAHN eh preh dew PARK","mean":"My flat is near the park."},{"t":"Le vélo est derrière la maison.","tr":"luh vay-LOH eh deh-ryehr lah meh-ZOHN","mean":"The bike is behind the house."}],"title":"Around town"},{"type":"sentence","t":"La boulangerie est à côté de la pharmacie.","tr":"lah boo-lahn-ZHREE eh-tah koh-TAY duh lah far-mah-SEE","mean":"The bakery is next to the pharmacy.","words":[{"t":"La","mean":"the"},{"t":"boulangerie","mean":"bakery"},{"t":"est","mean":"is"},{"t":"à","mean":"at"},{"t":"côté","mean":"side"},{"t":"de","mean":"of"},{"t":"la","mean":"the"},{"t":"pharmacie","mean":"pharmacy"}],"note":"{{à côté de}} is literally 'at the side of'."},{"type":"dialogue","lines":[{"who":"Tourist","t":"Pardon, madame, où est la gare ?","tr":"par-DOHN, mah-DAHM, oo eh lah GAR","mean":"Excuse me, madam, where is the station?"},{"who":"Lady","t":"C'est tout droit, puis à gauche.","tr":"seh too DRWAH, pwee ah GOHSH","mean":"It's straight on, then left."},{"who":"Tourist","t":"C'est loin d'ici ?","tr":"seh lwan dee-SEE","mean":"Is it far from here?"},{"who":"Lady","t":"Non, c'est à cinq minutes. La gare est en face du musée.","tr":"NOHN, seh-tah sank mee-NEWT. lah gar eh-tahn fahss dew mew-ZAY","mean":"No, it's five minutes away. The station is opposite the museum."},{"who":"Tourist","t":"Merci beaucoup !","tr":"mehr-SEE boh-KOO","mean":"Thank you very much!"},{"who":"Lady","t":"Je vous en prie. Bonne journée !","tr":"zhuh voo-zahn PREE. bun zhoor-NAY","mean":"You're welcome. Have a good day!"}],"title":"Asking the way"},{"type":"tip","kind":"warn","text":"{{tout droit}} (straight on, 'too DRWAH') and {{à droite}} (on the right, 'ah DRWAHT') sound close. Listen for the final T!"},{"type":"practice","text":"Describe where things are, aloud.","lines":["Le livre est sur la table.","Le chien est sous la chaise.","La gare est près du centre.","J'habite à Paris, en France.","Mon frère travaille au Japon."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"What does {{sous}} mean?","options":["under","on","in","next to"],"answer":0},{"q":"Complete: La poste est à côté ___ cinéma.","options":["de le","de la","des","du"],"answer":3,"explain":"{{de + le = du}}."},{"q":"Listen. Where is it?","say":"derrière la maison","options":["in front of the house","behind the house","next to the house","inside the house"],"answer":1},{"q":"Complete: Je vais ___ Portugal.","options":["en","à","aux","au"],"answer":3,"explain":"{{le Portugal}} is masculine: {{au}}."},{"q":"Complete: Elle habite ___ Londres.","options":["en","à","au"],"answer":1,"explain":"Use {{à}} with cities."},{"q":"What does {{tout droit}} mean?","options":["on the right","all right","turn back","straight on"],"answer":3},{"q":"Complete: Nous allons ___ Italie.","options":["au","à la","aux","en"],"answer":3,"explain":"{{l'Italie}} is feminine: {{en}}."}]}]}]});
LC.units.push({"id":"talk","order":5,"icon":"Ça","color":"rose","title":"Everyday Conversations","subtitle":"Real French for cafés, shops, travel, health, the phone and friends","lessons":[{"id":"u5-cafe","icon":"Ca","title":"At the Café","subtitle":"Order a drink, ask for the bill and pay","minutes":12,"goals":["Order drinks and snacks politely","Ask for the bill and pay by card","Understand how French cafés work"],"blocks":[{"type":"text","text":"Cafés are at the heart of French daily life. In this lesson you will order a drink and a snack, ask for the bill and pay, all in polite, natural French."},{"type":"vocab","items":[{"t":"un café","tr":"uhn ka-FAY","mean":"an espresso (small black coffee)"},{"t":"un café crème","tr":"uhn ka-FAY KREM","mean":"a coffee with frothy milk"},{"t":"un thé","tr":"uhn TAY","mean":"a tea"},{"t":"un chocolat chaud","tr":"uhn sho-ko-LA SHOH","mean":"a hot chocolate"},{"t":"un jus d'orange","tr":"uhn zhew do-RAHNZH","mean":"an orange juice"},{"t":"un croissant","tr":"uhn krwah-SAHN","mean":"a croissant"},{"t":"une carafe d'eau","tr":"ewn ka-RAF DOH","mean":"a jug of tap water"},{"t":"l'addition","tr":"la-dee-SYOHN","mean":"the bill / the check"},{"t":"la terrasse","tr":"la teh-RASS","mean":"the outdoor seating area"},{"t":"Je voudrais…","tr":"zhuh voo-DRAY","mean":"I would like…","example":{"t":"Je voudrais un thé.","tr":"zhuh voo-DRAY uhn TAY.","mean":"I would like a tea."}}],"title":"Café words"},{"type":"dialogue","lines":[{"who":"Serveur","t":"Bonjour madame ! Vous avez choisi ?","tr":"bohn-ZHOOR ma-DAM ! voo za-vay shwa-ZEE ?","mean":"Hello madam! Have you chosen?"},{"who":"Léa","t":"Bonjour ! Je voudrais un café crème, s'il vous plaît.","tr":"bohn-ZHOOR ! zhuh voo-DRAY uhn ka-fay KREM, seel voo PLAY.","mean":"Hello! I'd like a coffee with milk, please."},{"who":"Serveur","t":"Très bien. Et avec ça ?","tr":"tray BYAN. ay ah-vek SA ?","mean":"Very good. Anything else? (lit. And with that?)"},{"who":"Léa","t":"Un croissant et une carafe d'eau, s'il vous plaît.","tr":"uhn krwah-SAHN ay ewn ka-raf DOH, seel voo PLAY.","mean":"A croissant and a jug of water, please."},{"who":"Serveur","t":"Je vous apporte ça tout de suite.","tr":"zhuh voo za-PORT sa toot SWEET.","mean":"I'll bring it right away."},{"who":"Léa","t":"Excusez-moi ! L'addition, s'il vous plaît.","tr":"ek-skew-zay-MWAH ! la-dee-SYOHN, seel voo PLAY.","mean":"Excuse me! The bill, please."},{"who":"Serveur","t":"Bien sûr. Ça fait six euros cinquante.","tr":"byan SEWR. sa feh see zuh-ROH san-KAHNT.","mean":"Of course. That's six euros fifty."},{"who":"Léa","t":"Je peux payer par carte ?","tr":"zhuh puh pay-yay par KART ?","mean":"Can I pay by card?"},{"who":"Serveur","t":"Oui, pas de problème. Voilà.","tr":"WEE, pahd pro-BLEM. vwah-LA.","mean":"Yes, no problem. Here you go."},{"who":"Léa","t":"Merci, bonne journée !","tr":"mair-SEE, bun zhoor-NAY !","mean":"Thanks, have a nice day!"}],"title":"On the terrace"},{"type":"sentence","t":"Je voudrais un café, s'il vous plaît.","tr":"zhuh voo-DRAY uhn ka-FAY, seel voo PLAY.","mean":"I would like a coffee, please.","words":[{"t":"Je","mean":"I"},{"t":"voudrais","mean":"would like"},{"t":"un","mean":"a"},{"t":"café","mean":"coffee"},{"t":"s'il","mean":"if it"},{"t":"vous","mean":"you"},{"t":"plaît","mean":"pleases"}],"note":"{{S'il vous plaît}} literally means 'if it pleases you'. With a friend, say {{s'il te plaît}}."},{"type":"sentence","t":"L'addition, s'il vous plaît.","tr":"la-dee-SYOHN, seel voo PLAY.","mean":"The bill, please.","words":[{"t":"L'addition","mean":"the bill"},{"t":"s'il","mean":"if it"},{"t":"vous","mean":"you"},{"t":"plaît","mean":"pleases"}]},{"type":"sentence","t":"Je peux payer par carte ?","tr":"zhuh puh pay-yay par KART ?","mean":"Can I pay by card?","words":[{"t":"Je","mean":"I"},{"t":"peux","mean":"can"},{"t":"payer","mean":"pay"},{"t":"par","mean":"by"},{"t":"carte","mean":"card"}],"note":"Just raise your voice at the end and a statement becomes a question."},{"type":"tip","kind":"culture","text":"In France, {{un café}} is a small, strong espresso. For a bigger coffee with milk, ask for {{un café crème}} (in Paris often just {{un crème}}). {{Café au lait}} is mostly something people make at home."},{"type":"tip","kind":"culture","text":"Service is included in the price by law ({{service compris}}). Leaving a few coins is a kind extra, never an obligation. To call the waiter, say {{Excusez-moi !}} or {{S'il vous plaît !}} Never shout {{Garçon !}}: it sounds rude today."},{"type":"tip","kind":"tip","text":"In many cafés a drink costs a little less at the counter ({{au comptoir}}) than at a table or on the terrace."},{"type":"steps","title":"Role-play: your turn","items":[{"title":"Greet the waiter","t":"Bonjour !","tr":"bohn-ZHOOR !","mean":"Hello!"},{"title":"Order a drink","t":"Je voudrais un thé, s'il vous plaît.","tr":"zhuh voo-DRAY uhn TAY, seel voo PLAY.","mean":"I'd like a tea, please."},{"title":"Add a snack","t":"Et un croissant, s'il vous plaît.","tr":"ay uhn krwah-SAHN, seel voo PLAY.","mean":"And a croissant, please."},{"title":"Ask for the bill","t":"L'addition, s'il vous plaît.","tr":"la-dee-SYOHN, seel voo PLAY.","mean":"The bill, please."},{"title":"Pay and leave","t":"Merci, bonne journée !","tr":"mair-SEE, bun zhoor-NAY !","mean":"Thanks, have a nice day!","desc":"In the evening, say {{Bonne soirée !}} (Have a nice evening!) instead."}]},{"type":"practice","text":"Read each line aloud. Then order your own favourite drink.","lines":["Bonjour ! Je voudrais un chocolat chaud, s'il vous plaît.","Et avec ça ?","Un croissant et une carafe d'eau, s'il vous plaît.","L'addition, s'il vous plaît.","Je peux payer par carte ?","Merci, bonne journée !"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"In a French café, what do you get if you order {{un café}}?","options":["A large filter coffee","A coffee with milk","A cup of tea","A small espresso"],"answer":3,"explain":"{{Un café}} is an espresso. For milk, ask for {{un café crème}}."},{"q":"Listen. What is the customer asking for?","say":"L'addition, s'il vous plaît.","options":["The menu","Some water","The bill","A table"],"answer":2,"explain":"{{L'addition}} = the bill."},{"q":"How do you say 'I would like a tea'?","options":["Je voudrais un thé.","Je voudrais une thé.","Je suis voudrais un thé.","J'ai un thé."],"answer":0,"explain":"{{Thé}} is masculine: {{un thé}}."},{"q":"What is the polite way to call the waiter?","options":["Garçon !","Hé, vous là-bas !","Excusez-moi !","Allô !"],"answer":2,"explain":"{{Excusez-moi}} or {{S'il vous plaît}} is polite. {{Allô}} is only for the phone."},{"q":"Listen. How much is it?","say":"Ça fait six euros cinquante.","options":["€5.60","€16.50","€6.15","€6.50"],"answer":3,"explain":"{{six euros cinquante}} = €6.50."},{"q":"Is service (the tip) included in a French café bill?","options":["No, always add 20%","Only on the terrace","Yes, by law","Only in Paris"],"answer":2,"explain":"{{Service compris}}: a tip is a kind extra, not required."}]}]},{"id":"u5-restaurant","icon":"À","title":"At the Restaurant","subtitle":"Book a table, order a meal and pay","minutes":14,"goals":["Book and ask for a table","Order a starter, main course and drinks","Avoid the menu / carte trap"],"blocks":[{"type":"text","text":"Eating out in France is a real pleasure, and a little French goes a long way. Learn how to get a table, order a full meal and say it was delicious."},{"type":"vocab","items":[{"t":"la carte","tr":"la KART","mean":"the menu (the full list of dishes)"},{"t":"le menu","tr":"luh muh-NEW","mean":"a set meal at a fixed price"},{"t":"l'entrée","tr":"lahn-TRAY","mean":"the starter"},{"t":"le plat principal","tr":"luh pla pran-see-PAL","mean":"the main course"},{"t":"le dessert","tr":"luh deh-SAIR","mean":"the dessert"},{"t":"le plat du jour","tr":"luh pla dew ZHOOR","mean":"today's special"},{"t":"l'eau gazeuse","tr":"loh ga-ZUHZ","mean":"sparkling water"},{"t":"l'eau plate","tr":"loh PLAT","mean":"still water"},{"t":"saignant / à point / bien cuit","tr":"seh-NYAHN / ah PWAN / byan KWEE","mean":"rare / medium / well done (meat)"},{"t":"C'était délicieux !","tr":"say-TAY day-lee-SYUH !","mean":"It was delicious!"}],"title":"Restaurant words"},{"type":"compare","title":"Watch out: false friends","items":[{"t":"la carte","label":"the menu","desc":"The full list of dishes. Ask: {{La carte, s'il vous plaît.}}"},{"t":"le menu","label":"a set meal","desc":"Two or three courses at one fixed price, e.g. {{entrée + plat}}."},{"t":"l'entrée","label":"the starter","desc":"In France the {{entrée}} comes first. It is not the main course."}]},{"type":"dialogue","lines":[{"who":"Serveuse","t":"Bonsoir ! Vous avez réservé ?","tr":"bohn-SWAR ! voo za-vay ray-zair-VAY ?","mean":"Good evening! Do you have a reservation?"},{"who":"Marc","t":"Oui, une table pour deux, au nom de Martin.","tr":"WEE, ewn TABL poor DUH, oh nohm duh mar-TAN.","mean":"Yes, a table for two, in the name of Martin."},{"who":"Serveuse","t":"Suivez-moi, s'il vous plaît. Voici la carte.","tr":"swee-vay-MWAH, seel voo PLAY. vwah-SEE la KART.","mean":"Follow me, please. Here is the menu."},{"who":"Marc","t":"Merci. Qu'est-ce que vous nous conseillez ?","tr":"mair-SEE. kess-kuh voo noo kohn-seh-YAY ?","mean":"Thank you. What do you recommend?"},{"who":"Serveuse","t":"Le plat du jour : un bœuf bourguignon maison.","tr":"luh pla dew ZHOOR : uhn buhf boor-gee-NYOHN meh-ZOHN.","mean":"Today's special: a homemade beef bourguignon."},{"who":"Marc","t":"Parfait ! Deux plats du jour, s'il vous plaît.","tr":"par-FAY ! duh pla dew ZHOOR, seel voo PLAY.","mean":"Perfect! Two of today's special, please."},{"who":"Serveuse","t":"Et comme boisson ?","tr":"ay kom bwah-SOHN ?","mean":"And to drink?"},{"who":"Marc","t":"Une bouteille d'eau gazeuse, s'il vous plaît.","tr":"ewn boo-TAY doh ga-ZUHZ, seel voo PLAY.","mean":"A bottle of sparkling water, please."},{"who":"Serveuse","t":"Tout s'est bien passé ?","tr":"too say byan pa-SAY ?","mean":"Was everything all right?"},{"who":"Marc","t":"Oui, c'était délicieux ! L'addition, s'il vous plaît.","tr":"WEE, say-TAY day-lee-SYUH ! la-dee-SYOHN, seel voo PLAY.","mean":"Yes, it was delicious! The bill, please."}],"title":"Dinner for two"},{"type":"sentence","t":"Une table pour deux, s'il vous plaît.","tr":"ewn TABL poor DUH, seel voo PLAY.","mean":"A table for two, please.","words":[{"t":"Une","mean":"a"},{"t":"table","mean":"table"},{"t":"pour","mean":"for"},{"t":"deux","mean":"two"},{"t":"s'il","mean":"if it"},{"t":"vous","mean":"you"},{"t":"plaît","mean":"pleases"}]},{"type":"sentence","t":"Qu'est-ce que vous nous conseillez ?","tr":"kess-kuh voo noo kohn-seh-YAY ?","mean":"What do you recommend (to us)?","words":[{"t":"Qu'est-ce","mean":"what (is it)"},{"t":"que","mean":"that"},{"t":"vous","mean":"you"},{"t":"nous","mean":"to us"},{"t":"conseillez","mean":"advise"}],"note":"{{Qu'est-ce que}} is a very common way to start a 'what' question."},{"type":"sentence","t":"Je suis allergique aux cacahuètes.","tr":"zhuh swee za-lair-ZHEEK oh ka-ka-WET.","mean":"I'm allergic to peanuts.","words":[{"t":"Je","mean":"I"},{"t":"suis","mean":"am"},{"t":"allergique","mean":"allergic"},{"t":"aux","mean":"to the"},{"t":"cacahuètes","mean":"peanuts"}],"note":"Swap in your own allergy: {{au lait}} (milk), {{au gluten}} (gluten), {{aux fruits de mer}} (seafood)."},{"type":"tip","kind":"culture","text":"Waiters will not bring the bill until you ask. Taking your time is normal, and rushing guests would be rude. When you are ready, say {{L'addition, s'il vous plaît.}}"},{"type":"tip","kind":"culture","text":"Tap water ({{une carafe d'eau}}) is free with a meal in French restaurants, and bread is usually free too."},{"type":"tip","kind":"tip","text":"Lunch is usually served from about 12:00 to 14:00 and dinner from about 19:30. Between meals many kitchens close, so look for a {{brasserie}}, which often serves food all day."},{"type":"steps","title":"Role-play: your turn","items":[{"title":"Ask for a table","t":"Bonsoir, une table pour deux, s'il vous plaît.","tr":"bohn-SWAR, ewn TABL poor DUH, seel voo PLAY.","mean":"Good evening, a table for two, please."},{"title":"Order your meal","t":"En entrée, la soupe, et en plat, le poulet.","tr":"ahn nahn-TRAY, la SOOP, ay ahn PLA, luh poo-LAY.","mean":"For the starter, the soup, and for the main, the chicken."},{"title":"Ask for water","t":"Une carafe d'eau, s'il vous plaît.","tr":"ewn ka-raf DOH, seel voo PLAY.","mean":"A jug of tap water, please."},{"title":"Say thank you","t":"C'était délicieux, merci !","tr":"say-TAY day-lee-SYUH, mair-SEE !","mean":"It was delicious, thank you!"},{"title":"Ask for the bill","t":"L'addition, s'il vous plaît.","tr":"la-dee-SYOHN, seel voo PLAY.","mean":"The bill, please."}]},{"type":"practice","text":"Read the lines aloud as if you were the customer.","lines":["Bonsoir ! Une table pour deux, s'il vous plaît.","La carte, s'il vous plaît.","Qu'est-ce que vous nous conseillez ?","Le plat du jour, s'il vous plaît. À point, merci.","Une bouteille d'eau gazeuse, s'il vous plaît.","C'était délicieux ! L'addition, s'il vous plaît."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"In a French restaurant, what is {{l'entrée}}?","options":["The main course","The way in","The dessert","The starter"],"answer":3,"explain":"In France, {{l'entrée}} is the first course."},{"q":"You want the full list of dishes. You ask for…","options":["le menu","la carte","la liste","l'addition"],"answer":1,"explain":"{{La carte}} is the full menu; {{le menu}} is a set meal."},{"q":"Listen. What does the customer want?","say":"Une carafe d'eau, s'il vous plaît.","options":["Tap water","A bottle of wine","Sparkling water","The bill"],"answer":0,"explain":"{{Une carafe d'eau}} is a jug of free tap water."},{"q":"How do you ask for meat cooked medium?","options":["saignant","à point","bien cuit","à moitié"],"answer":1,"explain":"{{saignant}} = rare, {{à point}} = medium, {{bien cuit}} = well done."},{"q":"When does the waiter usually bring the bill?","options":["With the dessert","As soon as you finish eating","After exactly one hour","When you ask for it"],"answer":3,"explain":"Ask: {{L'addition, s'il vous plaît.}}"},{"q":"Listen. What did the customer say?","say":"C'était délicieux !","options":["It was too expensive!","It's my birthday!","It was delicious!","The bill, please!"],"answer":2}]}]},{"id":"u5-shopping","icon":"€","title":"Shopping & the Market","subtitle":"Ask prices, choose quantities and try things on","minutes":14,"goals":["Ask how much something costs","Buy food by the kilo at a market","Shop for clothes politely"],"blocks":[{"type":"text","text":"From the open-air market to a clothes shop, these phrases help you ask prices, choose quantities and pay with confidence."},{"type":"vocab","items":[{"t":"le marché","tr":"luh mar-SHAY","mean":"the market"},{"t":"Combien ça coûte ?","tr":"kohm-BYAN sa KOOT ?","mean":"How much does it cost?"},{"t":"C'est combien ?","tr":"say kohm-BYAN ?","mean":"How much is it?"},{"t":"un kilo de…","tr":"uhn kee-LOH duh","mean":"a kilo of…","example":{"t":"un kilo de pommes","tr":"uhn kee-LOH duh POM","mean":"a kilo of apples"}},{"t":"une barquette","tr":"ewn bar-KET","mean":"a small tray / punnet (for berries)"},{"t":"C'est tout.","tr":"say TOO.","mean":"That's all."},{"t":"la monnaie","tr":"la mo-NEH","mean":"the change (money back)"},{"t":"trop cher","tr":"troh SHAIR","mean":"too expensive"},{"t":"la taille","tr":"la TIE","mean":"the size (clothes)"},{"t":"essayer","tr":"eh-seh-YAY","mean":"to try on"},{"t":"la caisse","tr":"la KESS","mean":"the checkout / till"},{"t":"les soldes","tr":"lay SOLD","mean":"the sales"}],"title":"Shopping words"},{"type":"dialogue","lines":[{"who":"Vendeur","t":"Bonjour madame ! Qu'est-ce qu'il vous faut ?","tr":"bohn-ZHOOR ma-DAM ! kess-keel voo FOH ?","mean":"Hello madam! What do you need?"},{"who":"Sophie","t":"Bonjour ! Un kilo de tomates, s'il vous plaît.","tr":"bohn-ZHOOR ! uhn kee-loh duh to-MAT, seel voo PLAY.","mean":"Hello! A kilo of tomatoes, please."},{"who":"Vendeur","t":"Voilà. Et avec ceci ?","tr":"vwah-LA. ay ah-vek suh-SEE ?","mean":"There you go. Anything else?"},{"who":"Sophie","t":"Elles sont combien, les fraises ?","tr":"el sohn kohm-BYAN, lay FREZ ?","mean":"How much are the strawberries?"},{"who":"Vendeur","t":"Quatre euros la barquette.","tr":"ka-truh-ROH la bar-KET.","mean":"Four euros a punnet."},{"who":"Sophie","t":"D'accord, une barquette. C'est tout, merci.","tr":"da-KOR, ewn bar-KET. say TOO, mair-SEE.","mean":"OK, one punnet. That's all, thanks."},{"who":"Vendeur","t":"Ça fait six euros vingt.","tr":"sa feh see zuh-roh VAN.","mean":"That's six euros twenty."},{"who":"Sophie","t":"Voilà dix euros.","tr":"vwah-LA dee zuh-ROH.","mean":"Here's ten euros."},{"who":"Vendeur","t":"Et voici votre monnaie. Bonne journée !","tr":"ay vwah-SEE votr mo-NEH. bun zhoor-NAY !","mean":"And here's your change. Have a nice day!"},{"who":"Sophie","t":"Merci, vous aussi !","tr":"mair-SEE, voo zoh-SEE !","mean":"Thanks, you too!"}],"title":"At the market stall"},{"type":"sentence","t":"Je regarde, merci.","tr":"zhuh ruh-GARD, mair-SEE.","mean":"I'm just looking, thanks.","words":[{"t":"Je","mean":"I"},{"t":"regarde","mean":"am looking"},{"t":"merci","mean":"thanks"}],"note":"The perfect answer when a shop assistant asks {{Je peux vous aider ?}} (Can I help you?)."},{"type":"sentence","t":"Je peux l'essayer ?","tr":"zhuh puh leh-seh-YAY ?","mean":"Can I try it on?","words":[{"t":"Je","mean":"I"},{"t":"peux","mean":"can"},{"t":"l'essayer","mean":"try it on"}]},{"type":"sentence","t":"Vous l'avez en plus grand ?","tr":"voo la-VAY ahn plew GRAHN ?","mean":"Do you have it in a bigger size?","words":[{"t":"Vous","mean":"you"},{"t":"l'avez","mean":"have it"},{"t":"en","mean":"in"},{"t":"plus","mean":"more"},{"t":"grand","mean":"big"}],"note":"Change {{grand}} to {{petit}} for a smaller size."},{"type":"tip","kind":"culture","text":"Always say {{Bonjour}} when you walk into a shop, and {{Merci, au revoir}} when you leave. In France, asking a question without a greeting can seem rude."},{"type":"tip","kind":"culture","text":"At many market stalls the seller chooses the fruit for you, so ask before you touch. Prices are written with a comma: {{6,20 €}} means six euros twenty."},{"type":"tip","kind":"fun","text":"France has official sales seasons ({{les soldes}}): one in winter, starting in January, and one in summer, starting in late June. The dates are set nationally."},{"type":"steps","title":"Role-play: your turn","items":[{"title":"Greet the seller","t":"Bonjour !","tr":"bohn-ZHOOR !","mean":"Hello!"},{"title":"Ask the price","t":"C'est combien ?","tr":"say kohm-BYAN ?","mean":"How much is it?"},{"title":"Choose a quantity","t":"Cinq cents grammes de cerises, s'il vous plaît.","tr":"san sahn GRAM duh suh-REEZ, seel voo PLAY.","mean":"500 grams of cherries, please."},{"title":"Finish your order","t":"C'est tout, merci.","tr":"say TOO, mair-SEE.","mean":"That's all, thanks."},{"title":"Pay and say goodbye","t":"Merci, au revoir !","tr":"mair-SEE, oh ruh-VWAR !","mean":"Thanks, goodbye!"}]},{"type":"practice","text":"Read aloud. Then change the fruit and the quantity.","lines":["Bonjour ! Un kilo de pommes, s'il vous plaît.","Elles sont combien, les fraises ?","C'est tout, merci.","Je regarde, merci.","Je peux l'essayer ?","Vous l'avez en plus petit ?"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"A shop assistant asks {{Je peux vous aider ?}} You only want to browse. You say…","options":["Je voudrais l'addition.","Je regarde, merci.","Combien ça coûte ?","C'est trop cher."],"answer":1,"explain":"{{Je regarde}} = I'm (just) looking."},{"q":"Listen. What is the question?","say":"C'est combien ?","options":["What size is it?","Where is it?","How much is it?","Is that all?"],"answer":2},{"q":"What does {{la monnaie}} mean at the till?","options":["The money bag","The change","The receipt","The price tag"],"answer":1,"explain":"{{Voici votre monnaie}} = Here's your change."},{"q":"What should you do first when you walk into a French shop?","options":["Say Bonjour","Ask the price at once","Touch the products","Say nothing and look"],"answer":0,"explain":"A greeting is expected in every shop."},{"q":"Listen. How much is it?","say":"Six euros vingt.","options":["€2.60","€6.20","€16.20","€6.02"],"answer":1},{"q":"{{Je peux l'essayer ?}} means…","options":["Can I try it on?","Can I pay by card?","Do you have it in blue?","Is it on sale?"],"answer":0}]}]},{"id":"u5-directions","icon":"→","title":"Asking for Directions","subtitle":"Ask the way and understand the answer","minutes":12,"goals":["Ask where a place is","Understand left, right and straight on","Use {{Il y a…}} to ask what is nearby"],"blocks":[{"type":"text","text":"Lost in a new town? With a few words you can ask the way and, more importantly, understand the answer."},{"type":"vocab","items":[{"t":"Où est… ?","tr":"oo EH","mean":"Where is…?","example":{"t":"Où est la gare ?","tr":"oo eh la GAR ?","mean":"Where is the station?"}},{"t":"à gauche","tr":"ah GOHSH","mean":"on the left / to the left"},{"t":"à droite","tr":"ah DRWAHT","mean":"on the right / to the right"},{"t":"tout droit","tr":"too DRWAH","mean":"straight on"},{"t":"tournez","tr":"toor-NAY","mean":"turn"},{"t":"prenez","tr":"pruh-NAY","mean":"take"},{"t":"la rue","tr":"la REW","mean":"the street"},{"t":"les feux","tr":"lay FUH","mean":"the traffic lights"},{"t":"le carrefour","tr":"luh kar-FOOR","mean":"the crossroads"},{"t":"près d'ici","tr":"preh dee-SEE","mean":"near here"},{"t":"loin","tr":"LWAN","mean":"far"},{"t":"en face de","tr":"ahn FASS duh","mean":"opposite"},{"t":"à côté de","tr":"ah koh-TAY duh","mean":"next to"}],"title":"Direction words"},{"type":"compare","title":"Don't mix them up","items":[{"t":"à droite","label":"to the right","desc":"You can hear the T at the end: {{drwaht}}."},{"t":"tout droit","label":"straight on","desc":"The T is silent: {{drwah}}. No turn at all!"},{"t":"à gauche","label":"to the left","desc":"The opposite of {{à droite}}."}]},{"type":"dialogue","lines":[{"who":"Tom","t":"Excusez-moi, madame. Où est la gare, s'il vous plaît ?","tr":"ek-skew-zay-MWAH, ma-DAM. oo eh la GAR, seel voo PLAY ?","mean":"Excuse me, madam. Where is the station, please?"},{"who":"Passante","t":"La gare ? Ce n'est pas loin. Allez tout droit.","tr":"la GAR ? suh neh pa LWAN. a-lay too DRWAH.","mean":"The station? It's not far. Go straight on."},{"who":"Passante","t":"Aux feux, tournez à gauche.","tr":"oh FUH, toor-nay ah GOHSH.","mean":"At the traffic lights, turn left."},{"who":"Tom","t":"Aux feux, à gauche… Et après ?","tr":"oh FUH, ah GOHSH… ay ah-PREH ?","mean":"At the lights, left… And then?"},{"who":"Passante","t":"Prenez la deuxième rue à droite.","tr":"pruh-nay la duh-zyem REW ah DRWAHT.","mean":"Take the second street on the right."},{"who":"Passante","t":"La gare est en face de la poste.","tr":"la GAR eh tahn FASS duh la POST.","mean":"The station is opposite the post office."},{"who":"Tom","t":"C'est à combien de minutes à pied ?","tr":"say tah kohm-BYAN duh mee-NEWT ah PYAY ?","mean":"How many minutes is it on foot?"},{"who":"Passante","t":"Environ dix minutes.","tr":"ahn-vee-ROHN dee mee-NEWT.","mean":"About ten minutes."},{"who":"Tom","t":"Merci beaucoup, madame !","tr":"mair-SEE boh-KOO, ma-DAM !","mean":"Thank you very much, madam!"},{"who":"Passante","t":"Je vous en prie. Bonne journée !","tr":"zhuh voo zahn PREE. bun zhoor-NAY !","mean":"You're welcome. Have a nice day!"}],"title":"Finding the station"},{"type":"sentence","t":"Où est la gare ?","tr":"oo eh la GAR ?","mean":"Where is the station?","words":[{"t":"Où","mean":"where"},{"t":"est","mean":"is"},{"t":"la","mean":"the"},{"t":"gare","mean":"station"}]},{"type":"sentence","t":"C'est loin d'ici ?","tr":"say LWAN dee-SEE ?","mean":"Is it far from here?","words":[{"t":"C'est","mean":"it is"},{"t":"loin","mean":"far"},{"t":"d'ici","mean":"from here"}]},{"type":"sentence","t":"Il y a une pharmacie près d'ici ?","tr":"eel ya ewn far-ma-SEE preh dee-SEE ?","mean":"Is there a pharmacy near here?","words":[{"t":"Il","mean":"it"},{"t":"y","mean":"there"},{"t":"a","mean":"has"},{"t":"une","mean":"a"},{"t":"pharmacie","mean":"pharmacy"},{"t":"près","mean":"near"},{"t":"d'ici","mean":"from here"}],"note":"{{Il y a}} means 'there is / there are'. It is one of the most useful phrases in French."},{"type":"tip","kind":"culture","text":"Before asking for help, always start with {{Excusez-moi}} and {{Bonjour}} (or {{Bonsoir}} in the evening). People are much happier to help."},{"type":"tip","kind":"tip","text":"If the answer is too fast, say {{Pardon, vous pouvez répéter plus lentement ?}} (Sorry, can you repeat more slowly?)."},{"type":"steps","title":"Role-play: your turn","items":[{"title":"Get attention","t":"Excusez-moi, monsieur.","tr":"ek-skew-zay-MWAH, muh-SYUH.","mean":"Excuse me, sir."},{"title":"Ask the way","t":"Où est le musée, s'il vous plaît ?","tr":"oo eh luh mew-ZAY, seel voo PLAY ?","mean":"Where is the museum, please?"},{"title":"Check the distance","t":"C'est loin ?","tr":"say LWAN ?","mean":"Is it far?"},{"title":"Repeat the key words","t":"À droite, puis tout droit ?","tr":"ah DRWAHT, pwee too DRWAH ?","mean":"Right, then straight on?"},{"title":"Say thank you","t":"Merci beaucoup !","tr":"mair-SEE boh-KOO !","mean":"Thank you very much!"}]},{"type":"practice","text":"Read aloud. Then give directions from your home to the nearest shop.","lines":["Excusez-moi, où est la poste, s'il vous plaît ?","Allez tout droit, puis tournez à gauche.","Prenez la première rue à droite.","La banque est à côté de la pharmacie.","C'est loin d'ici ?","Non, c'est à cinq minutes à pied."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Listen. What should you do?","say":"Tournez à droite.","options":["Turn left","Go straight on","Turn right","Go back"],"answer":2},{"q":"How do you say 'straight on'?","options":["à droite","à gauche","au carrefour","tout droit"],"answer":3,"explain":"{{tout droit}} (silent T) = straight on; {{à droite}} = right."},{"q":"{{en face de la poste}} means…","options":["opposite the post office","just next to the post office","inside the post office","behind the post office"],"answer":0,"explain":"{{en face de}} = opposite; {{à côté de}} = next to."},{"q":"Listen. How far is it?","say":"C'est à dix minutes à pied.","options":["Ten minutes on foot","Ten minutes by bus","Two minutes on foot","Ten kilometres away"],"answer":0},{"q":"What does {{Il y a une banque près d'ici ?}} mean?","options":["Where is the bank?","Is there a bank near here?","Is the bank open today?","Is the bank far from here?"],"answer":1},{"q":"{{les feux}} are…","options":["traffic lights","the street signs","the crossroads","the bus stops"],"answer":0,"explain":"{{Aux feux, tournez à gauche}} = At the lights, turn left."}]}]},{"id":"u5-transport","icon":"TGV","title":"Transport & the Train Station","subtitle":"Buy tickets and find your way by train, metro and bus","minutes":14,"goals":["Buy a one-way or return ticket","Ask about times and tracks","Say how you travel"],"blocks":[{"type":"text","text":"France has fast trains, big-city metros and buses almost everywhere. Learn how to buy a ticket, find your train and ask about times."},{"type":"vocab","items":[{"t":"la gare","tr":"la GAR","mean":"the train station"},{"t":"un billet","tr":"uhn bee-YAY","mean":"a ticket"},{"t":"un aller simple","tr":"uhn na-lay SAMPL","mean":"a one-way ticket"},{"t":"un aller-retour","tr":"uhn na-lay ruh-TOOR","mean":"a return ticket"},{"t":"la voie","tr":"la VWAH","mean":"the track (where your train leaves)"},{"t":"le quai","tr":"luh KAY","mean":"the platform"},{"t":"le départ / l'arrivée","tr":"luh day-PAR / la-ree-VAY","mean":"departure / arrival"},{"t":"en retard","tr":"ahn ruh-TAR","mean":"late / delayed"},{"t":"à l'heure","tr":"ah LUHR","mean":"on time"},{"t":"le métro","tr":"luh may-TROH","mean":"the underground / subway"},{"t":"l'arrêt de bus","tr":"la-REH duh BEWS","mean":"the bus stop"},{"t":"la correspondance","tr":"la ko-res-pohn-DAHNS","mean":"the connection / change of line"}],"title":"Travel words"},{"type":"dialogue","lines":[{"who":"Nina","t":"Bonjour, un billet pour Lyon, s'il vous plaît.","tr":"bohn-ZHOOR, uhn bee-YAY poor lee-OHN, seel voo PLAY.","mean":"Hello, a ticket to Lyon, please."},{"who":"Agent","t":"Un aller simple ou un aller-retour ?","tr":"uhn na-lay SAMPL oo uhn na-lay ruh-TOOR ?","mean":"One-way or return?"},{"who":"Nina","t":"Un aller-retour. Je pars demain et je reviens dimanche.","tr":"uhn na-lay ruh-TOOR. zhuh par duh-MAN ay zhuh ruh-vyan dee-MAHNSH.","mean":"A return. I leave tomorrow and come back on Sunday."},{"who":"Agent","t":"Il y a un train demain à huit heures douze. Ça vous va ?","tr":"eel ya uhn TRAN duh-MAN ah wee tuhr DOOZ. sa voo VA ?","mean":"There's a train tomorrow at 8:12. Does that suit you?"},{"who":"Nina","t":"Oui, parfait. C'est direct ?","tr":"WEE, par-FAY. say dee-REKT ?","mean":"Yes, perfect. Is it direct?"},{"who":"Agent","t":"Oui, c'est direct. Ça fait quatre-vingt-cinq euros.","tr":"WEE, say dee-REKT. sa feh ka-truh-van-san-kuh-ROH.","mean":"Yes, it's direct. That's 85 euros."},{"who":"Nina","t":"Le train part de quelle voie ?","tr":"luh TRAN par duh kel VWAH ?","mean":"Which track does the train leave from?"},{"who":"Agent","t":"Regardez le tableau des départs. La voie est affichée vingt minutes avant.","tr":"ruh-gar-DAY luh ta-BLOH day day-PAR. la VWAH eh ta-fee-SHAY van mee-NEWT ah-VAHN.","mean":"Check the departures board. The track is shown twenty minutes before."},{"who":"Nina","t":"D'accord, merci beaucoup !","tr":"da-KOR, mair-SEE boh-KOO !","mean":"OK, thanks a lot!"}],"title":"At the ticket office"},{"type":"table","head":["French","Meaning"],"rows":[["{{en train}}","by train"],["{{en bus}}","by bus"],["{{en métro}}","by metro"],["{{en voiture}}","by car"],["{{en avion}}","by plane"],["{{à pied}}","on foot"],["{{à vélo}}","by bike"]],"title":"How do you travel?"},{"type":"text","text":"A simple rule of thumb: use {{en}} for vehicles you sit inside, and {{à}} for {{pied}} (foot) and {{vélo}} (bike)."},{"type":"sentence","t":"Un aller-retour pour Lyon, s'il vous plaît.","tr":"uhn na-lay ruh-TOOR poor lee-OHN, seel voo PLAY.","mean":"A return ticket to Lyon, please.","words":[{"t":"Un","mean":"a"},{"t":"aller-retour","mean":"return ticket"},{"t":"pour","mean":"for / to"},{"t":"Lyon","mean":"Lyon"},{"t":"s'il","mean":"if it"},{"t":"vous","mean":"you"},{"t":"plaît","mean":"pleases"}]},{"type":"sentence","t":"À quelle heure part le prochain train ?","tr":"ah kel UHR par luh pro-shan TRAN ?","mean":"What time does the next train leave?","words":[{"t":"À","mean":"at"},{"t":"quelle","mean":"what"},{"t":"heure","mean":"hour / time"},{"t":"part","mean":"leaves"},{"t":"le","mean":"the"},{"t":"prochain","mean":"next"},{"t":"train","mean":"train"}]},{"type":"sentence","t":"Je descends au prochain arrêt.","tr":"zhuh day-SAHN oh pro-shan na-REH.","mean":"I'm getting off at the next stop.","words":[{"t":"Je","mean":"I"},{"t":"descends","mean":"get off"},{"t":"au","mean":"at the"},{"t":"prochain","mean":"next"},{"t":"arrêt","mean":"stop"}]},{"type":"tip","kind":"culture","text":"Timetables, tickets and announcements use the 24-hour clock: {{seize heures}} is 4 pm and {{vingt heures trente}} is 8:30 pm."},{"type":"tip","kind":"culture","text":"On high-speed trains (TGV) your seat is reserved, so check your coach number ({{la voiture}}) and seat. On a crowded metro, say {{Pardon}} to get past people."},{"type":"tip","kind":"warn","text":"Some paper tickets for regional trains and buses must be validated in a machine before you travel ({{composter}} or {{valider}}). If you forget, you can be fined."},{"type":"steps","title":"Role-play: your turn","items":[{"title":"Ask for a ticket","t":"Un billet pour Marseille, s'il vous plaît.","tr":"uhn bee-YAY poor mar-SAY, seel voo PLAY.","mean":"A ticket to Marseille, please."},{"title":"Choose the type","t":"Un aller simple, s'il vous plaît.","tr":"uhn na-lay SAMPL, seel voo PLAY.","mean":"A one-way ticket, please."},{"title":"Ask the time","t":"À quelle heure part le train ?","tr":"ah kel UHR par luh TRAN ?","mean":"What time does the train leave?"},{"title":"Ask about the track","t":"C'est quelle voie ?","tr":"say kel VWAH ?","mean":"Which track is it?"},{"title":"Check the route","t":"C'est direct ?","tr":"say dee-REKT ?","mean":"Is it direct?"}]},{"type":"practice","text":"Read aloud. Then plan a trip to a French city you'd like to visit.","lines":["Un aller-retour pour Paris, s'il vous plaît.","À quelle heure part le prochain train ?","Le train est en retard.","Je vais à la gare à pied.","Où est l'arrêt de bus ?","Je descends au prochain arrêt."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"A ticket there and back is…","options":["un aller simple","un billet simple","un retour-départ","un aller-retour"],"answer":3,"explain":"{{aller}} = going, {{retour}} = return."},{"q":"Listen. What's the problem?","say":"Le train est en retard.","options":["The train is on time.","The train is full.","The train is direct.","The train is late."],"answer":3},{"q":"How do you say 'on foot'?","options":["en pied","en voiture","à pied","par pied"],"answer":2,"explain":"{{à pied}} and {{à vélo}} use {{à}}."},{"q":"Listen. When does the train leave?","say":"Le train part à seize heures.","options":["6 pm","4 pm","4 am","10 pm"],"answer":1,"explain":"{{seize heures}} = 16:00 = 4 pm."},{"q":"{{la correspondance}} on the metro is…","options":["a change of line","a letter","the ticket machine","the last train"],"answer":0},{"q":"On a TGV, {{la voiture}} means…","options":["your own car","the train coach","the taxi rank outside","the driver's cabin"],"answer":1,"explain":"On trains, coaches are called {{voitures}}: {{voiture 12, place 45}}."}]}]},{"id":"u5-hotel","icon":"H","title":"At the Hotel","subtitle":"Check in, ask questions and solve problems","minutes":12,"goals":["Check in with a reservation","Ask about breakfast and check-out","Report a problem in your room"],"blocks":[{"type":"text","text":"Checking in, asking about breakfast, reporting a problem: here is the French you need for a smooth hotel stay."},{"type":"vocab","items":[{"t":"une chambre","tr":"ewn SHAHMBR","mean":"a room (bedroom)"},{"t":"une chambre double","tr":"ewn shahmbr DOOBL","mean":"a double room"},{"t":"une nuit","tr":"ewn NWEE","mean":"a night"},{"t":"la clé","tr":"la KLAY","mean":"the key"},{"t":"le petit-déjeuner","tr":"luh puh-tee day-zhuh-NAY","mean":"breakfast"},{"t":"compris","tr":"kohm-PREE","mean":"included"},{"t":"la réception","tr":"la ray-sep-SYOHN","mean":"the reception desk"},{"t":"l'ascenseur","tr":"la-sahn-SUHR","mean":"the lift / elevator"},{"t":"le rez-de-chaussée","tr":"luh rayd-shoh-SAY","mean":"the ground floor"},{"t":"le premier étage","tr":"luh pruh-myeh ray-TAZH","mean":"the first floor (one floor up)"},{"t":"la douche","tr":"la DOOSH","mean":"the shower"},{"t":"… ne marche pas","tr":"nuh marsh PA","mean":"… doesn't work"}],"title":"Hotel words"},{"type":"dialogue","lines":[{"who":"Réceptionniste","t":"Bonsoir monsieur, bienvenue !","tr":"bohn-SWAR muh-SYUH, byan-vuh-NEW !","mean":"Good evening, sir, welcome!"},{"who":"M. Diallo","t":"Bonsoir. J'ai une réservation au nom de Diallo.","tr":"bohn-SWAR. zhay ewn ray-zair-va-SYOHN oh nohm duh dya-LOH.","mean":"Good evening. I have a reservation in the name of Diallo."},{"who":"Réceptionniste","t":"Oui, une chambre double pour trois nuits.","tr":"WEE, ewn shahmbr DOOBL poor trwah NWEE.","mean":"Yes, a double room for three nights."},{"who":"M. Diallo","t":"C'est ça. Le petit-déjeuner est compris ?","tr":"say SA. luh puh-tee day-zhuh-NAY eh kohm-PREE ?","mean":"That's right. Is breakfast included?"},{"who":"Réceptionniste","t":"Oui, il est servi de sept heures à dix heures, au rez-de-chaussée.","tr":"WEE, eel eh sair-VEE duh seh TUHR ah dee ZUHR, oh rayd-shoh-SAY.","mean":"Yes, it's served from 7 to 10, on the ground floor."},{"who":"M. Diallo","t":"Très bien. Et le wifi ?","tr":"tray BYAN. ay luh wee-FEE ?","mean":"Very good. And the wifi?"},{"who":"Réceptionniste","t":"Le code est sur votre carte. Voici votre clé : chambre 214, au deuxième étage.","tr":"luh KOD eh sewr votr KART. vwah-SEE votr KLAY : SHAHMBR duh sahn ka-TORZ, oh duh-zyem ay-TAZH.","mean":"The code is on your card. Here's your key: room 214, on the second floor."},{"who":"M. Diallo","t":"Merci. Le départ, c'est à quelle heure ?","tr":"mair-SEE. luh day-PAR, say tah kel UHR ?","mean":"Thanks. What time is check-out?"},{"who":"Réceptionniste","t":"Avant onze heures. L'ascenseur est à droite.","tr":"ah-VAHN ohn-ZUHR. la-sahn-SUHR eh tah DRWAHT.","mean":"Before 11. The lift is on the right."},{"who":"M. Diallo","t":"Parfait, merci. Bonne soirée !","tr":"par-FAY, mair-SEE. bun swah-RAY !","mean":"Perfect, thanks. Have a nice evening!"}],"title":"Checking in"},{"type":"sentence","t":"J'ai une réservation au nom de Diallo.","tr":"zhay ewn ray-zair-va-SYOHN oh nohm duh dya-LOH.","mean":"I have a reservation in the name of Diallo.","words":[{"t":"J'ai","mean":"I have"},{"t":"une","mean":"a"},{"t":"réservation","mean":"reservation"},{"t":"au","mean":"in the"},{"t":"nom","mean":"name"},{"t":"de","mean":"of"},{"t":"Diallo","mean":"Diallo"}]},{"type":"sentence","t":"Est-ce que le petit-déjeuner est compris ?","tr":"ess-kuh luh puh-tee day-zhuh-NAY eh kohm-PREE ?","mean":"Is breakfast included?","words":[{"t":"Est-ce","mean":"is it (question)"},{"t":"que","mean":"that"},{"t":"le","mean":"the"},{"t":"petit-déjeuner","mean":"breakfast"},{"t":"est","mean":"is"},{"t":"compris","mean":"included"}],"note":"Put {{Est-ce que}} at the front to turn any sentence into a yes/no question."},{"type":"sentence","t":"La douche ne marche pas.","tr":"la DOOSH nuh marsh PA.","mean":"The shower doesn't work.","words":[{"t":"La","mean":"the"},{"t":"douche","mean":"shower"},{"t":"ne","mean":"not"},{"t":"marche","mean":"works"},{"t":"pas","mean":"(not)"}],"note":"Swap in {{le chauffage}} (the heating), {{la climatisation}} (the air conditioning) or {{le wifi}}."},{"type":"tip","kind":"culture","text":"Floors are counted as in the UK: {{le rez-de-chaussée}} is the ground floor and {{le premier étage}} is one floor up (the '2nd floor' in the US)."},{"type":"tip","kind":"culture","text":"Most French towns charge a small tourist tax per person per night ({{la taxe de séjour}}). It is often added to your bill at the end of your stay."},{"type":"steps","title":"Role-play: your turn","items":[{"title":"Greet the receptionist","t":"Bonsoir !","tr":"bohn-SWAR !","mean":"Good evening!"},{"title":"Give your name","t":"J'ai une réservation au nom de…","tr":"zhay ewn ray-zair-va-SYOHN oh nohm duh…","mean":"I have a reservation in the name of…"},{"title":"Ask about breakfast","t":"Le petit-déjeuner est à quelle heure ?","tr":"luh puh-tee day-zhuh-NAY eh tah kel UHR ?","mean":"What time is breakfast?"},{"title":"Report a problem","t":"Excusez-moi, le wifi ne marche pas.","tr":"ek-skew-zay-MWAH, luh wee-FEE nuh marsh PA.","mean":"Excuse me, the wifi doesn't work."},{"title":"Check out","t":"Je voudrais régler la note, s'il vous plaît.","tr":"zhuh voo-DRAY ray-glay la NOT, seel voo PLAY.","mean":"I'd like to pay the bill, please."}]},{"type":"practice","text":"Read aloud as the guest.","lines":["Bonsoir ! J'ai une réservation au nom de Martin.","Le petit-déjeuner est compris ?","L'ascenseur est où, s'il vous plaît ?","Excusez-moi, la douche ne marche pas.","Je voudrais régler la note, s'il vous plaît."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"In a French hotel, {{le rez-de-chaussée}} is…","options":["the ground floor","the first floor up","the basement car park","the top floor"],"answer":0,"explain":"{{rez-de-chaussée}} = ground floor; {{premier étage}} = one floor up."},{"q":"Listen. What does the receptionist say?","say":"Le petit-déjeuner est compris.","options":["Breakfast is not available.","Breakfast is at seven.","Lunch is included.","Breakfast is included."],"answer":3},{"q":"How do you say 'The shower doesn't work'?","options":["La douche ne parle pas.","La clé ne marche pas.","Le douche ne marchent pas.","La douche ne marche pas."],"answer":3,"explain":"{{La douche}} is feminine and singular: {{ne marche pas}}."},{"q":"{{l'ascenseur}} is…","options":["the lift","the staircase","the key card","the receipt"],"answer":0},{"q":"Listen. Which room?","say":"Chambre deux cent quatorze.","options":["240","214","204","114"],"answer":1},{"q":"{{Une chambre pour deux nuits}} is a room for…","options":["two people","two weeks","two nights","twelve nights"],"answer":2}]}]},{"id":"u5-doctor","icon":"+","title":"At the Doctor & Pharmacy","subtitle":"Say what hurts and get the right help","minutes":14,"goals":["Say how you feel and what hurts","Understand simple advice from a doctor","Get help at a pharmacy and in an emergency"],"blocks":[{"type":"text","text":"Nobody plans to get ill on a trip, but it helps to be ready. Learn to describe how you feel, understand the doctor and get help at a pharmacy."},{"type":"vocab","items":[{"t":"le médecin","tr":"luh mayd-SAN","mean":"the doctor"},{"t":"la pharmacie","tr":"la far-ma-SEE","mean":"the pharmacy / chemist's"},{"t":"malade","tr":"ma-LAD","mean":"ill / sick"},{"t":"J'ai mal à la tête.","tr":"zhay mal ah la TET.","mean":"I have a headache."},{"t":"J'ai mal à la gorge.","tr":"zhay mal ah la GORZH.","mean":"I have a sore throat."},{"t":"J'ai de la fièvre.","tr":"zhay duh la FYEVR.","mean":"I have a fever."},{"t":"Je tousse.","tr":"zhuh TOOSS.","mean":"I'm coughing."},{"t":"un rhume","tr":"uhn REWM","mean":"a cold"},{"t":"une ordonnance","tr":"ewn or-do-NAHNS","mean":"a prescription"},{"t":"un médicament","tr":"uhn may-dee-ka-MAHN","mean":"a medicine"},{"t":"un comprimé","tr":"uhn kohm-pree-MAY","mean":"a tablet / pill"},{"t":"les urgences","tr":"lay zewr-ZHAHNS","mean":"the emergency department (A&E / ER)"}],"title":"Health words"},{"type":"rule","name":"avoir mal à + body part","color":"orange","desc":"To say something hurts, use {{J'ai mal}} + {{à}} + the body part. {{à}} joins with {{le}} and {{les}}.","how":"{{à}} + {{le}} = {{au}} · {{à}} + {{la}} = {{à la}} · {{à}} + {{l'}} = {{à l'}} · {{à}} + {{les}} = {{aux}}","examples":[{"t":"J'ai mal au dos.","tr":"zhay mal oh DOH.","hl":"au"},{"t":"J'ai mal à la tête.","tr":"zhay mal ah la TET.","hl":"à la"},{"t":"J'ai mal à l'oreille.","tr":"zhay mal ah lo-RAY.","hl":"à l'"},{"t":"J'ai mal aux dents.","tr":"zhay mal oh DAHN.","hl":"aux"}]},{"type":"table","head":["French","Meaning"],"rows":[["{{J'ai mal à la tête.}}","My head hurts."],["{{J'ai mal au dos.}}","My back hurts."],["{{J'ai mal au ventre.}}","My stomach hurts."],["{{J'ai mal aux dents.}}","My teeth hurt."],["{{J'ai mal à l'oreille.}}","My ear hurts."],["{{J'ai mal au pied.}}","My foot hurts."]],"title":"Where does it hurt?"},{"type":"dialogue","lines":[{"who":"Médecin","t":"Bonjour, asseyez-vous. Qu'est-ce qui ne va pas ?","tr":"bohn-ZHOOR, a-seh-yay-VOO. kess-kee nuh va PA ?","mean":"Hello, take a seat. What's the matter?"},{"who":"Paul","t":"J'ai mal à la gorge et j'ai de la fièvre.","tr":"zhay mal ah la GORZH ay zhay duh la FYEVR.","mean":"I have a sore throat and a fever."},{"who":"Médecin","t":"Depuis quand ?","tr":"duh-pwee KAHN ?","mean":"Since when?"},{"who":"Paul","t":"Depuis deux jours. Et je tousse beaucoup.","tr":"duh-pwee duh ZHOOR. ay zhuh tooss boh-KOO.","mean":"For two days. And I'm coughing a lot."},{"who":"Médecin","t":"Bon, ce n'est pas grave. C'est un gros rhume.","tr":"BOHN, suh neh pa GRAV. say tuhn groh REWM.","mean":"Well, it's not serious. It's a bad cold."},{"who":"Médecin","t":"Voici une ordonnance. Reposez-vous et buvez beaucoup d'eau.","tr":"vwah-SEE ewn or-do-NAHNS. ruh-poh-zay-VOO ay bew-VAY boh-koo DOH.","mean":"Here's a prescription. Rest and drink plenty of water."},{"who":"Paul","t":"Merci, docteur. Je dois revenir ?","tr":"mair-SEE, dok-TUHR. zhuh dwah ruh-vuh-NEER ?","mean":"Thank you, doctor. Do I need to come back?"},{"who":"Médecin","t":"Si ça ne va pas mieux dans trois jours, oui.","tr":"see sa nuh va pa MYUH dahn trwah ZHOOR, WEE.","mean":"If you're not better in three days, yes."}],"title":"At the doctor's"},{"type":"dialogue","lines":[{"who":"Pharmacienne","t":"Bonjour, je peux vous aider ?","tr":"bohn-ZHOOR, zhuh puh voo zeh-DAY ?","mean":"Hello, can I help you?"},{"who":"Paul","t":"Bonjour, j'ai une ordonnance.","tr":"bohn-ZHOOR, zhay ewn or-do-NAHNS.","mean":"Hello, I have a prescription."},{"who":"Pharmacienne","t":"Merci. Prenez un comprimé trois fois par jour, pendant le repas.","tr":"mair-SEE. pruh-NAY uhn kohm-pree-MAY trwah FWAH par ZHOOR, pahn-dahn luh ruh-PA.","mean":"Thank you. Take one tablet three times a day, with meals."},{"who":"Paul","t":"D'accord. Merci beaucoup !","tr":"da-KOR. mair-SEE boh-KOO !","mean":"OK. Thank you very much!"}],"title":"At the pharmacy"},{"type":"sentence","t":"J'ai besoin d'un médecin.","tr":"zhay buh-ZWAN duhn mayd-SAN.","mean":"I need a doctor.","words":[{"t":"J'ai","mean":"I have"},{"t":"besoin","mean":"need"},{"t":"d'un","mean":"of a"},{"t":"médecin","mean":"doctor"}],"note":"{{J'ai besoin de…}} = I need… (literally 'I have need of…')."},{"type":"sentence","t":"J'ai mal à la tête.","tr":"zhay mal ah la TET.","mean":"I have a headache.","words":[{"t":"J'ai","mean":"I have"},{"t":"mal","mean":"pain / ache"},{"t":"à","mean":"at"},{"t":"la","mean":"the"},{"t":"tête","mean":"head"}]},{"type":"tip","kind":"culture","text":"Look for the green cross. French pharmacists are trained to give advice for small health problems, so a pharmacy is a good first stop. At night and on Sundays, a {{pharmacie de garde}} (on-duty pharmacy) is open; its address is posted on pharmacy doors."},{"type":"tip","kind":"warn","text":"Emergency numbers in France: {{15}} for an ambulance (SAMU), {{18}} for the fire brigade, {{17}} for the police, and {{112}} anywhere in the EU."},{"type":"steps","title":"Role-play: your turn","items":[{"title":"Say you're ill","t":"Je suis malade.","tr":"zhuh swee ma-LAD.","mean":"I'm ill."},{"title":"Say what hurts","t":"J'ai mal au ventre.","tr":"zhay mal oh VAHNTR.","mean":"I have a stomach ache."},{"title":"Say since when","t":"Depuis hier.","tr":"duh-pwee YAIR.","mean":"Since yesterday."},{"title":"Mention an allergy","t":"Je suis allergique à la pénicilline.","tr":"zhuh swee za-lair-ZHEEK ah la pay-nee-see-LEEN.","mean":"I'm allergic to penicillin."},{"title":"Ask how to take it","t":"Je le prends comment ?","tr":"zhuh luh prahn ko-MAHN ?","mean":"How do I take it?"}]},{"type":"practice","text":"Read aloud. Then say what hurts using a new body part.","lines":["Bonjour, je suis malade.","J'ai mal à la gorge et j'ai de la fièvre.","Depuis deux jours.","J'ai besoin d'un médecin.","Je le prends comment ?"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Listen. What's wrong?","say":"J'ai mal à la tête.","options":["I have a sore throat.","I have a fever.","I have a headache.","I'm very tired."],"answer":2},{"q":"Complete: {{J'ai mal ___ ventre.}}","options":["à la","aux","à le","au"],"answer":3,"explain":"{{à + le = au}}: {{J'ai mal au ventre.}}"},{"q":"{{une ordonnance}} is…","options":["an order at a café","an appointment","a prescription","a tablet"],"answer":2},{"q":"Which number calls an ambulance (SAMU) in France?","options":["15","17","18","911"],"answer":0,"explain":"15 = SAMU, 17 = police, 18 = fire brigade, 112 = EU emergency number."},{"q":"Listen. How long has the patient been ill?","say":"Depuis deux jours.","options":["For two weeks","Since this morning","For two days","For ten days"],"answer":2},{"q":"It's Sunday night and you need medicine. You look for…","options":["le bureau de poste","la pharmacie de garde","la boulangerie","le cabinet du dentiste"],"answer":1,"explain":"The {{pharmacie de garde}} is open when others are closed."}]}]},{"id":"u5-phone","icon":"Tél","title":"Phone Calls & Appointments","subtitle":"Make calls, leave messages and book appointments","minutes":12,"goals":["Start and end a phone call","Book, move or cancel an appointment","Spell your name and read phone numbers"],"blocks":[{"type":"text","text":"Phone calls feel harder than face-to-face chats because you can't see faces or gestures. Don't worry: a few fixed phrases do most of the work."},{"type":"vocab","items":[{"t":"Allô ?","tr":"a-LOH ?","mean":"Hello? (on the phone only)"},{"t":"C'est de la part de qui ?","tr":"say duh la PAR duh KEE ?","mean":"Who's calling, please?"},{"t":"Ne quittez pas.","tr":"nuh kee-tay PA.","mean":"Hold the line."},{"t":"rappeler","tr":"ra-PLAY","mean":"to call back"},{"t":"laisser un message","tr":"leh-SAY uhn meh-SAZH","mean":"to leave a message"},{"t":"prendre rendez-vous","tr":"prahndr rahn-day-VOO","mean":"to make an appointment"},{"t":"libre","tr":"LEEBR","mean":"free / available"},{"t":"annuler","tr":"a-new-LAY","mean":"to cancel"},{"t":"épeler","tr":"ay-PLAY","mean":"to spell"},{"t":"le numéro","tr":"luh new-may-ROH","mean":"the number"}],"title":"Phone words"},{"type":"dialogue","lines":[{"who":"Secrétaire","t":"Cabinet dentaire, bonjour !","tr":"ka-bee-NAY dahn-TAIR, bohn-ZHOOR !","mean":"Dental practice, hello!"},{"who":"Emma","t":"Bonjour, je voudrais prendre rendez-vous, s'il vous plaît.","tr":"bohn-ZHOOR, zhuh voo-DRAY prahndr rahn-day-VOO, seel voo PLAY.","mean":"Hello, I'd like to make an appointment, please."},{"who":"Secrétaire","t":"Mardi à quatorze heures, ça vous convient ?","tr":"mar-DEE ah ka-tor-ZUHR, sa voo kohn-VYAN ?","mean":"Tuesday at 2 pm, does that suit you?"},{"who":"Emma","t":"Mardi, je ne suis pas libre. Vous avez quelque chose jeudi ?","tr":"mar-DEE, zhuh nuh swee pa LEEBR. voo za-VAY kel-kuh SHOHZ zhuh-DEE ?","mean":"I'm not free on Tuesday. Do you have anything on Thursday?"},{"who":"Secrétaire","t":"Jeudi à neuf heures et demie ?","tr":"zhuh-DEE ah nuh-vuhr ay duh-MEE ?","mean":"Thursday at half past nine?"},{"who":"Emma","t":"Parfait, merci.","tr":"par-FAY, mair-SEE.","mean":"Perfect, thank you."},{"who":"Secrétaire","t":"C'est à quel nom ?","tr":"say tah kel NOHM ?","mean":"What name is it under?"},{"who":"Emma","t":"Laurent. Je vous épelle : L-A-U-R-E-N-T.","tr":"lo-RAHN. zhuh voo zay-PEL : el, ah, ew, air, uh, en, tay.","mean":"Laurent. I'll spell it: L-A-U-R-E-N-T."},{"who":"Secrétaire","t":"Très bien, c'est noté. À jeudi !","tr":"tray BYAN, say no-TAY. ah zhuh-DEE !","mean":"Very good, that's booked. See you on Thursday!"}],"title":"Booking the dentist"},{"type":"dialogue","lines":[{"who":"Lucas","t":"Allô, bonjour. Je voudrais parler à madame Petit, s'il vous plaît.","tr":"a-LOH, bohn-ZHOOR. zhuh voo-DRAY par-LAY ah ma-dam puh-TEE, seel voo PLAY.","mean":"Hello. I'd like to speak to Ms Petit, please."},{"who":"Accueil","t":"C'est de la part de qui ?","tr":"say duh la PAR duh KEE ?","mean":"Who's calling, please?"},{"who":"Lucas","t":"De Lucas Bernard.","tr":"duh lew-KA bair-NAR.","mean":"Lucas Bernard."},{"who":"Accueil","t":"Ne quittez pas, je vous la passe.","tr":"nuh kee-tay PA, zhuh voo la PASS.","mean":"Hold the line, I'll put you through to her."}],"title":"Asking for someone"},{"type":"sentence","t":"Je voudrais prendre rendez-vous.","tr":"zhuh voo-DRAY prahndr rahn-day-VOO.","mean":"I'd like to make an appointment.","words":[{"t":"Je","mean":"I"},{"t":"voudrais","mean":"would like"},{"t":"prendre","mean":"to take"},{"t":"rendez-vous","mean":"appointment"}]},{"type":"sentence","t":"Vous pouvez parler plus lentement ?","tr":"voo poo-VAY par-LAY plew lahnt-MAHN ?","mean":"Can you speak more slowly?","words":[{"t":"Vous","mean":"you"},{"t":"pouvez","mean":"can"},{"t":"parler","mean":"speak"},{"t":"plus","mean":"more"},{"t":"lentement","mean":"slowly"}],"note":"A life-saver on the phone! Also useful: {{Vous pouvez répéter ?}} (Can you repeat?)."},{"type":"sentence","t":"Je vous rappelle plus tard.","tr":"zhuh voo ra-PEL plew TAR.","mean":"I'll call you back later.","words":[{"t":"Je","mean":"I"},{"t":"vous","mean":"you"},{"t":"rappelle","mean":"call back"},{"t":"plus","mean":"more"},{"t":"tard","mean":"late"}],"note":"{{plus tard}} = later (literally 'more late')."},{"type":"tip","kind":"culture","text":"French phone numbers have ten digits and are read in pairs: {{06 12 34 56 78}} is {{zéro six, douze, trente-quatre, cinquante-six, soixante-dix-huit}}. Mobile numbers start with {{06}} or {{07}}."},{"type":"tip","kind":"tip","text":"Use {{Allô ?}} only on the phone. To end a call, say {{Au revoir, bonne journée !}}"},{"type":"steps","title":"Role-play: your turn","items":[{"title":"Greet","t":"Allô, bonjour !","tr":"a-LOH, bohn-ZHOOR !","mean":"Hello!"},{"title":"Say who you are","t":"C'est Emma Laurent.","tr":"say e-MA lo-RAHN.","mean":"It's Emma Laurent."},{"title":"Say why you're calling","t":"J'appelle pour prendre rendez-vous.","tr":"zha-PEL poor prahndr rahn-day-VOO.","mean":"I'm calling to make an appointment."},{"title":"Confirm the time","t":"Jeudi à neuf heures et demie, c'est parfait.","tr":"zhuh-DEE ah nuh-vuhr ay duh-MEE, say par-FAY.","mean":"Thursday at 9:30 is perfect."},{"title":"Cancel if you need to","t":"Je dois annuler mon rendez-vous.","tr":"zhuh dwah a-new-LAY mohn rahn-day-VOO.","mean":"I have to cancel my appointment."}]},{"type":"practice","text":"Read aloud. Then spell your own name with French letter names.","lines":["Allô, bonjour !","Je voudrais prendre rendez-vous, s'il vous plaît.","Vous avez quelque chose jeudi ?","Vous pouvez parler plus lentement ?","Je vous rappelle plus tard.","Au revoir, bonne journée !"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"On the phone, someone says {{Ne quittez pas.}} You should…","options":["hang up now","call back tomorrow","wait on the line","leave a message"],"answer":2,"explain":"{{Ne quittez pas}} = Don't hang up / Hold the line."},{"q":"Listen. What are they asking?","say":"C'est de la part de qui ?","options":["Where are you calling from?","Who's calling?","What's your number?","Can you call back?"],"answer":1},{"q":"How do you say 'to cancel'?","options":["annuler","rappeler","épeler","attendre"],"answer":0},{"q":"Listen. When is the appointment?","say":"Jeudi à neuf heures et demie.","options":["Tuesday at 9:30","Thursday at 10:30","Thursday at 9:00","Thursday at 9:30"],"answer":3},{"q":"How is the number {{06 45 22 10 89}} usually read?","options":["In pairs: zéro six, quarante-cinq…","Digit by digit: zéro, six, quatre…","As one big number","In groups of three"],"answer":0},{"q":"{{Je vous rappelle plus tard.}} means…","options":["I'll remind you tomorrow.","I'll call you back later.","Please call me later.","I can't hear you."],"answer":1}]}]},{"id":"u5-plans","icon":"RDV","title":"Making Plans with Friends","subtitle":"Invite, accept, say no kindly and fix a time","minutes":12,"goals":["Invite a friend using {{tu}}","Accept or refuse politely","Agree on a time and a meeting place"],"blocks":[{"type":"text","text":"Time to make plans! With friends, French people use {{tu}} and a relaxed style. Learn to invite, accept, say no kindly and fix a time and place."},{"type":"vocab","items":[{"t":"Tu es libre ?","tr":"tew eh LEEBR ?","mean":"Are you free?"},{"t":"Ça te dit ?","tr":"sa tuh DEE ?","mean":"Do you fancy it? / Interested?"},{"t":"ce soir","tr":"suh SWAR","mean":"tonight / this evening"},{"t":"ce week-end","tr":"suh wee-KEND","mean":"this weekend"},{"t":"aller au cinéma","tr":"a-lay oh see-nay-MA","mean":"to go to the cinema"},{"t":"boire un verre","tr":"bwar uhn VAIR","mean":"to have a drink (lit. drink a glass)"},{"t":"On se retrouve où ?","tr":"ohn suh ruh-troov OO ?","mean":"Where shall we meet?"},{"t":"Avec plaisir !","tr":"ah-vek pleh-ZEER !","mean":"I'd love to! (lit. with pleasure)"},{"t":"Ça marche !","tr":"sa MARSH !","mean":"Deal! / Sounds good!"},{"t":"Une autre fois ?","tr":"ewn ohtr FWAH ?","mean":"Another time?"},{"t":"À plus !","tr":"ah PLEWSS !","mean":"See you later! (casual)"}],"title":"Plans words"},{"type":"dialogue","lines":[{"who":"Inès","t":"Salut Hugo ! Tu es libre samedi soir ?","tr":"sa-LEW ew-GOH ! tew eh leebr sam-dee SWAR ?","mean":"Hi Hugo! Are you free on Saturday evening?"},{"who":"Hugo","t":"Samedi ? Oui, pourquoi ?","tr":"sam-DEE ? WEE, poor-KWAH ?","mean":"Saturday? Yes, why?"},{"who":"Inès","t":"Ça te dit d'aller au cinéma ? Il y a un nouveau film.","tr":"sa tuh DEE da-LAY oh see-nay-MA ? eel ya uhn noo-voh FEELM.","mean":"Fancy going to the cinema? There's a new film."},{"who":"Hugo","t":"Bonne idée ! Ça commence à quelle heure ?","tr":"bun ee-DAY ! sa ko-MAHNS ah kel UHR ?","mean":"Good idea! What time does it start?"},{"who":"Inès","t":"À vingt heures. On se retrouve au café d'en face à sept heures et demie ?","tr":"ah van TUHR. ohn suh ruh-TROOV oh ka-FAY dahn FASS ah seh tuhr ay duh-MEE ?","mean":"At 8 pm. Shall we meet at the café opposite at half past seven?"},{"who":"Hugo","t":"Ça marche ! Et après, on mange une pizza ?","tr":"sa MARSH ! ay ah-PREH, ohn mahnzh ewn peed-ZA ?","mean":"Deal! And afterwards, shall we have a pizza?"},{"who":"Inès","t":"Avec plaisir ! J'invite Léo aussi ?","tr":"ah-vek pleh-ZEER ! zhan-VEET lay-OH oh-SEE ?","mean":"I'd love to! Shall I invite Léo too?"},{"who":"Hugo","t":"Oui, bien sûr. À samedi !","tr":"WEE, byan SEWR. ah sam-DEE !","mean":"Yes, of course. See you on Saturday!"},{"who":"Inès","t":"À samedi ! Bisous !","tr":"ah sam-DEE ! bee-ZOO !","mean":"See you Saturday! Love, Inès! (lit. kisses)"}],"title":"Saturday night plans"},{"type":"table","head":["Say yes","Say no kindly"],"rows":[["{{Avec plaisir !}} I'd love to!","{{Désolé, je ne peux pas.}} Sorry, I can't."],["{{Bonne idée !}} Good idea!","{{Je suis pris ce soir.}} I'm busy tonight."],["{{Ça marche !}} Deal!","{{Une autre fois ?}} Another time?"],["{{Pourquoi pas ?}} Why not?","{{Ce week-end, ce n'est pas possible.}} This weekend isn't possible."]],"title":"Yes or no?"},{"type":"tip","kind":"tip","text":"A woman says {{Je suis prise}} (busy), with a Z sound at the end, and writes {{Désolée}} (sorry), which sounds just like {{Désolé}}."},{"type":"sentence","t":"Ça te dit d'aller au cinéma ?","tr":"sa tuh DEE da-LAY oh see-nay-MA ?","mean":"Do you fancy going to the cinema?","words":[{"t":"Ça","mean":"that"},{"t":"te","mean":"to you"},{"t":"dit","mean":"says"},{"t":"d'aller","mean":"to go"},{"t":"au","mean":"to the"},{"t":"cinéma","mean":"cinema"}],"note":"Literally 'Does it say (something) to you to go…?' A very friendly way to invite."},{"type":"sentence","t":"On se retrouve où ?","tr":"ohn suh ruh-troov OO ?","mean":"Where shall we meet?","words":[{"t":"On","mean":"we"},{"t":"se","mean":"each other"},{"t":"retrouve","mean":"meet up"},{"t":"où","mean":"where"}],"note":"In everyday speech, {{on}} usually means 'we'."},{"type":"sentence","t":"Désolé, je ne peux pas ce soir.","tr":"day-zo-LAY, zhuh nuh puh PA suh SWAR.","mean":"Sorry, I can't tonight.","words":[{"t":"Désolé","mean":"sorry"},{"t":"je","mean":"I"},{"t":"ne","mean":"not"},{"t":"peux","mean":"can"},{"t":"pas","mean":"(not)"},{"t":"ce","mean":"this"},{"t":"soir","mean":"evening"}]},{"type":"tip","kind":"culture","text":"With friends and people your own age, use {{tu}}. Text messages between friends often end with {{Bisous}} or {{Bises}} (kisses). It's friendly, not romantic."},{"type":"tip","kind":"fun","text":"Texting shortcuts: {{A+}} = À plus (see you), {{stp}} = s'il te plaît, {{bjr}} = bonjour, {{mdr}} = mort de rire (LOL)."},{"type":"steps","title":"Role-play: your turn","items":[{"title":"Ask if your friend is free","t":"Tu es libre ce soir ?","tr":"tew eh leebr suh SWAR ?","mean":"Are you free tonight?"},{"title":"Suggest something","t":"Ça te dit de boire un verre ?","tr":"sa tuh DEE duh bwar uhn VAIR ?","mean":"Fancy a drink?"},{"title":"Fix a time","t":"On se retrouve à dix-neuf heures ?","tr":"ohn suh ruh-troov ah deez-nuh-VUHR ?","mean":"Shall we meet at 7 pm?"},{"title":"Fix a place","t":"Devant la gare ?","tr":"duh-vahn la GAR ?","mean":"In front of the station?"},{"title":"Close the chat","t":"Ça marche, à plus !","tr":"sa MARSH, ah PLEWSS !","mean":"Deal, see you later!"}]},{"type":"practice","text":"Read aloud. Then invite a friend to do something you enjoy.","lines":["Salut ! Tu es libre samedi ?","Ça te dit d'aller au cinéma ?","Avec plaisir ! On se retrouve où ?","Devant le café, à huit heures.","Désolé, je ne peux pas. Une autre fois ?","Ça marche, à plus !"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Your friend asks {{Ça te dit d'aller au cinéma ?}} You want to go. You say…","options":["Je vous en prie.","Une autre fois ?","Je suis malade.","Avec plaisir !"],"answer":3},{"q":"Listen. What is your friend asking?","say":"On se retrouve où ?","options":["Where shall we meet?","What time shall we meet?","Who is coming with us?","Are you free tonight?"],"answer":0},{"q":"In everyday French, {{on}} usually means…","options":["they","you (formal)","it","we"],"answer":3,"explain":"{{On y va ?}} = Shall we go?"},{"q":"Which phrase politely says no?","options":["Bonne idée, j'arrive tout de suite !","Désolé, je ne peux pas.","Ça marche !","Pourquoi pas ?"],"answer":1},{"q":"A friend's text ends with {{Bisous}}. This is…","options":["just friendly","very romantic","a bit rude","a spelling mistake"],"answer":0},{"q":"Listen. What does it mean here?","say":"Ça marche !","options":["It's walking!","Deal! / OK!","It doesn't work.","Let's walk!"],"answer":1,"explain":"{{Ça marche !}} = That works for me!"}]}]},{"id":"u5-smalltalk","icon":"°C","title":"Small Talk & the Weather","subtitle":"Chat about the weather and get to know people","minutes":12,"goals":["Describe the weather","Ask where someone is from","Keep a friendly chat going"],"blocks":[{"type":"text","text":"Talking about the weather is the easiest way to start a chat with anyone. Add a few friendly questions and you can make small talk like a local."},{"type":"vocab","items":[{"t":"Quel temps fait-il ?","tr":"kel tahn feh-TEEL ?","mean":"What's the weather like?"},{"t":"Il fait beau.","tr":"eel feh BOH.","mean":"The weather's nice."},{"t":"Il fait mauvais.","tr":"eel feh mo-VEH.","mean":"The weather's bad."},{"t":"Il fait chaud.","tr":"eel feh SHOH.","mean":"It's hot."},{"t":"Il fait froid.","tr":"eel feh FRWAH.","mean":"It's cold."},{"t":"Il pleut.","tr":"eel PLUH.","mean":"It's raining."},{"t":"Il neige.","tr":"eel NEZH.","mean":"It's snowing."},{"t":"Il y a du vent.","tr":"eel ya dew VAHN.","mean":"It's windy."},{"t":"Il y a du soleil.","tr":"eel ya dew so-LAY.","mean":"It's sunny."},{"t":"la météo","tr":"la may-tay-OH","mean":"the weather forecast"}],"title":"Weather words"},{"type":"rule","name":"il fait / il y a du / weather verbs","color":"blue","desc":"Most weather phrases use {{il fait}} + an adjective. Some use {{il y a du}} + a noun. Rain and snow have their own verbs.","examples":[{"t":"Il fait chaud.","tr":"eel feh SHOH.","hl":"Il fait"},{"t":"Il y a du brouillard.","tr":"eel ya dew broo-YAR.","hl":"Il y a du"},{"t":"Il pleut.","tr":"eel PLUH.","hl":"pleut"}]},{"type":"dialogue","lines":[{"who":"Mme Roux","t":"Bonjour ! Quel beau temps aujourd'hui !","tr":"bohn-ZHOOR ! kel boh TAHN oh-zhoor-DWEE !","mean":"Hello! What lovely weather today!"},{"who":"Sam","t":"Oui, enfin du soleil ! Hier, il a plu toute la journée.","tr":"WEE, ahn-FAN dew so-LAY ! YAIR, eel a PLEW toot la zhoor-NAY.","mean":"Yes, sunshine at last! Yesterday it rained all day."},{"who":"Mme Roux","t":"Vous n'êtes pas d'ici, non ?","tr":"voo net pa dee-SEE, NOHN ?","mean":"You're not from here, are you?"},{"who":"Sam","t":"Non, je suis canadien. Je viens de Toronto.","tr":"NOHN, zhuh swee ka-na-DYAN. zhuh vyan duh to-rohn-TOH.","mean":"No, I'm Canadian. I'm from Toronto."},{"who":"Mme Roux","t":"Oh, il fait très froid là-bas en hiver, non ?","tr":"OH, eel feh tray FRWAH la-BA ahn nee-VAIR, NOHN ?","mean":"Oh, it's very cold there in winter, isn't it?"},{"who":"Sam","t":"Oui, et il neige beaucoup !","tr":"WEE, ay eel nezh boh-KOO !","mean":"Yes, and it snows a lot!"},{"who":"Mme Roux","t":"Et vous êtes ici en vacances ?","tr":"ay voo zet ee-SEE ahn va-KAHNS ?","mean":"And are you here on holiday?"},{"who":"Sam","t":"Non, je travaille ici pour six mois.","tr":"NOHN, zhuh tra-VIGH ee-SEE poor see MWAH.","mean":"No, I'm working here for six months."},{"who":"Mme Roux","t":"Super ! Alors, bon séjour en France !","tr":"sew-PAIR ! a-LOR, bohn say-ZHOOR ahn FRAHNS !","mean":"Great! Well, enjoy your stay in France!"},{"who":"Sam","t":"Merci, c'est gentil ! Bonne journée !","tr":"mair-SEE, say zhahn-TEE ! bun zhoor-NAY !","mean":"Thanks, that's kind! Have a nice day!"}],"title":"At the bus stop"},{"type":"sentence","t":"Il fait beau aujourd'hui.","tr":"eel feh BOH oh-zhoor-DWEE.","mean":"The weather's nice today.","words":[{"t":"Il","mean":"it"},{"t":"fait","mean":"makes / does"},{"t":"beau","mean":"nice"},{"t":"aujourd'hui","mean":"today"}],"note":"French uses {{il fait}} (literally 'it makes') for most weather."},{"type":"sentence","t":"Quel temps fait-il chez vous ?","tr":"kel tahn feh-teel shay VOO ?","mean":"What's the weather like where you live?","words":[{"t":"Quel","mean":"what"},{"t":"temps","mean":"weather"},{"t":"fait-il","mean":"does it make"},{"t":"chez","mean":"at the home of"},{"t":"vous","mean":"you"}]},{"type":"sentence","t":"Vous êtes d'où ?","tr":"voo zet DOO ?","mean":"Where are you from?","words":[{"t":"Vous","mean":"you"},{"t":"êtes","mean":"are"},{"t":"d'où","mean":"from where"}],"note":"With a friend: {{Tu es d'où ?}}"},{"type":"tip","kind":"culture","text":"France uses degrees Celsius: {{Il fait vingt-cinq degrés}} means it's 25 °C, a warm day (about 77 °F)."},{"type":"tip","kind":"culture","text":"Good small-talk topics: the weather, food, holidays, sport and where people are from. Salary, money and religion are usually seen as private, so avoid them with people you have just met."},{"type":"tip","kind":"tip","text":"Add {{non ?}} at the end of a sentence to mean 'isn't it?': {{Il fait froid, non ?}}"},{"type":"steps","title":"Role-play: your turn","items":[{"title":"Open with the weather","t":"Il fait beau aujourd'hui, non ?","tr":"eel feh BOH oh-zhoor-DWEE, NOHN ?","mean":"Nice weather today, isn't it?"},{"title":"Ask where they're from","t":"Vous êtes d'où ?","tr":"voo zet DOO ?","mean":"Where are you from?"},{"title":"Talk about yourself","t":"Je viens d'Angleterre.","tr":"zhuh vyan dahn-gluh-TAIR.","mean":"I'm from England."},{"title":"Ask about their visit","t":"Vous êtes ici en vacances ?","tr":"voo zet ee-SEE ahn va-KAHNS ?","mean":"Are you here on holiday?"},{"title":"Close politely","t":"Bonne journée !","tr":"bun zhoor-NAY !","mean":"Have a nice day!"}]},{"type":"practice","text":"Read aloud. Then describe today's weather where you are.","lines":["Quel temps fait-il aujourd'hui ?","Il fait beau et il y a du soleil.","Hier, il a plu toute la journée.","Il fait froid, non ?","Vous êtes d'où ?","Je viens des États-Unis."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Listen. What's the weather like?","say":"Il pleut.","options":["It's snowing.","It's windy.","It's raining.","It's sunny."],"answer":2},{"q":"How do you say 'It's cold'?","options":["Il fait froid.","Il est froid.","Il a froid.","Il fait chaud dehors."],"answer":0,"explain":"Weather uses {{il fait}}. ({{Il a froid}} means a person feels cold.)"},{"q":"Complete: {{Il y a du ___.}} (It's windy.)","options":["froid","pleut","beau","vent"],"answer":3},{"q":"Listen. What is the question?","say":"Vous êtes d'où ?","options":["Where are you going?","How are you today?","Where are you from?","Who are you with?"],"answer":2},{"q":"{{Il fait vingt-cinq degrés}} is…","options":["a freezing day","a snowy day","a stormy night","a warm day"],"answer":3},{"q":"Which topic is best avoided with someone you've just met?","options":["The weather today","Holidays","Their salary","Food"],"answer":2},{"q":"What does {{Il fait beau, non ?}} mean?","options":["It's nice weather, isn't it?","It's not nice weather.","Is it nice weather tomorrow?","It's nice, no thanks."],"answer":0}]}]}]});
LC.units.push({"id":"read","order":6,"icon":"Lu","color":"violet","title":"Reading & Culture","subtitle":"Stories, songs, proverbs and life in the French-speaking world","lessons":[{"id":"u6-story-leo","icon":"A1","title":"Story 1: Léo's Morning","subtitle":"A short story in the present tense","minutes":12,"goals":["Read a short story in French","Understand everyday verbs in the present","Answer questions about a text"],"blocks":[{"type":"text","text":"Your first French story! Read each sentence, tap the words you don't know, then read it again. Everything is in the present tense."},{"type":"vocab","items":[{"t":"habiter","tr":"a-bee-TAY","mean":"to live (somewhere)"},{"t":"le matin","tr":"luh ma-TAN","mean":"the morning"},{"t":"se lever","tr":"suh luh-VAY","mean":"to get up"},{"t":"boire","tr":"BWAR","mean":"to drink"},{"t":"une tartine","tr":"ewn tar-TEEN","mean":"a slice of bread with butter or jam"},{"t":"prendre le bus","tr":"prahndr luh BEWS","mean":"to take the bus"},{"t":"écouter","tr":"ay-koo-TAY","mean":"to listen (to)"},{"t":"en retard","tr":"ahn ruh-TAR","mean":"late"},{"t":"le cours","tr":"luh KOOR","mean":"the class / lesson"},{"t":"sourire","tr":"soo-REER","mean":"to smile"}],"title":"Words to know"},{"type":"text","text":"Read the story one sentence at a time.","title":"Le matin de Léo"},{"type":"sentence","t":"Léo a vingt ans.","tr":"lay-OH a van TAHN.","mean":"Léo is twenty.","words":[{"t":"Léo","mean":"Léo"},{"t":"a","mean":"has"},{"t":"vingt","mean":"twenty"},{"t":"ans","mean":"years"}],"note":"In French you 'have' an age: {{avoir … ans}}."},{"type":"sentence","t":"Il habite à Lyon avec son chat, Pixel.","tr":"eel a-BEET ah lee-OHN ah-vek sohn SHA, peek-SEL.","mean":"He lives in Lyon with his cat, Pixel.","words":[{"t":"Il","mean":"he"},{"t":"habite","mean":"lives"},{"t":"à","mean":"in"},{"t":"Lyon","mean":"Lyon"},{"t":"avec","mean":"with"},{"t":"son","mean":"his"},{"t":"chat","mean":"cat"},{"t":"Pixel","mean":"Pixel"}]},{"type":"sentence","t":"Le matin, il se lève à sept heures.","tr":"luh ma-TAN, eel suh LEV ah seh TUHR.","mean":"In the morning, he gets up at seven.","words":[{"t":"Le","mean":"the"},{"t":"matin","mean":"morning"},{"t":"il","mean":"he"},{"t":"se","mean":"himself"},{"t":"lève","mean":"gets up"},{"t":"à","mean":"at"},{"t":"sept","mean":"seven"},{"t":"heures","mean":"hours / o'clock"}]},{"type":"sentence","t":"Il boit un café et il mange une tartine.","tr":"eel bwah uhn ka-FAY ay eel mahnzh ewn tar-TEEN.","mean":"He drinks a coffee and eats a slice of bread.","words":[{"t":"Il","mean":"he"},{"t":"boit","mean":"drinks"},{"t":"un","mean":"a"},{"t":"café","mean":"coffee"},{"t":"et","mean":"and"},{"t":"il","mean":"he"},{"t":"mange","mean":"eats"},{"t":"une","mean":"a"},{"t":"tartine","mean":"slice of bread"}]},{"type":"sentence","t":"Puis il prend le bus pour aller à l'université.","tr":"pwee eel prahn luh BEWS poor a-LAY ah lew-nee-vair-see-TAY.","mean":"Then he takes the bus to go to university.","words":[{"t":"Puis","mean":"then"},{"t":"il","mean":"he"},{"t":"prend","mean":"takes"},{"t":"le","mean":"the"},{"t":"bus","mean":"bus"},{"t":"pour","mean":"in order to"},{"t":"aller","mean":"go"},{"t":"à","mean":"to"},{"t":"l'université","mean":"the university"}]},{"type":"sentence","t":"Dans le bus, il écoute de la musique.","tr":"dahn luh BEWS, eel ay-KOOT duh la mew-ZEEK.","mean":"On the bus, he listens to music.","words":[{"t":"Dans","mean":"in"},{"t":"le","mean":"the"},{"t":"bus","mean":"bus"},{"t":"il","mean":"he"},{"t":"écoute","mean":"listens to"},{"t":"de","mean":"some"},{"t":"la","mean":"(the)"},{"t":"musique","mean":"music"}]},{"type":"sentence","t":"Mais aujourd'hui, le bus est en retard.","tr":"meh oh-zhoor-DWEE, luh BEWS eh tahn ruh-TAR.","mean":"But today, the bus is late.","words":[{"t":"Mais","mean":"but"},{"t":"aujourd'hui","mean":"today"},{"t":"le","mean":"the"},{"t":"bus","mean":"bus"},{"t":"est","mean":"is"},{"t":"en","mean":"in"},{"t":"retard","mean":"delay"}],"note":"{{en retard}} = late (literally 'in delay')."},{"type":"sentence","t":"Léo arrive en cours à neuf heures dix.","tr":"lay-OH a-REEV ahn KOOR ah nuh-vuhr DEESS.","mean":"Léo gets to class at ten past nine.","words":[{"t":"Léo","mean":"Léo"},{"t":"arrive","mean":"arrives"},{"t":"en","mean":"in"},{"t":"cours","mean":"class"},{"t":"à","mean":"at"},{"t":"neuf","mean":"nine"},{"t":"heures","mean":"hours"},{"t":"dix","mean":"ten"}]},{"type":"sentence","t":"Le professeur sourit. Léo aussi !","tr":"luh pro-feh-SUHR soo-REE. lay-OH oh-SEE !","mean":"The teacher smiles. So does Léo!","words":[{"t":"Le","mean":"the"},{"t":"professeur","mean":"teacher"},{"t":"sourit","mean":"smiles"},{"t":"Léo","mean":"Léo"},{"t":"aussi","mean":"too"}]},{"type":"tip","kind":"culture","text":"A {{tartine}} is a slice of baguette with butter and jam, a classic French breakfast. For many families, croissants are more of a weekend treat."},{"type":"dictation","items":[{"t":"Léo a vingt ans.","tr":"lay-OH a van TAHN.","mean":"Léo is twenty."},{"t":"Il prend le bus.","tr":"eel prahn luh BEWS.","mean":"He takes the bus."},{"t":"Le bus est en retard.","tr":"luh BEWS eh tahn ruh-TAR.","mean":"The bus is late."}],"title":"Listen and write"},{"type":"quiz","title":"Did you understand?","items":[{"q":"How old is Léo?","options":["12","2","22","20"],"answer":3},{"q":"Where does Léo live?","options":["In Paris","In Lille","In Lyon","In Toulouse"],"answer":2},{"q":"Who is Pixel?","options":["His cat","His brother","His bus driver","His teacher"],"answer":0},{"q":"Listen. What does Léo have for breakfast?","say":"Il boit un café et il mange une tartine.","options":["Tea and a croissant","Juice and cereal","Coffee and bread","Nothing at all"],"answer":2},{"q":"Why is Léo late today?","options":["He gets up late","He forgets his bag","His cat is ill","The bus is late"],"answer":3},{"q":"{{Il se lève à sept heures.}} means…","options":["He goes to bed at seven.","He leaves at seven.","He gets up at seven.","He eats at seven."],"answer":2}]}]},{"id":"u6-story-market","icon":"A1+","title":"Story 2: Saturday at the Market","subtitle":"Chloé and her grandmother go shopping","minutes":12,"goals":["Read a longer story","Notice {{du}}, {{de la}} and {{des}} (some)","Answer questions about a text"],"blocks":[{"type":"text","text":"In this story, Chloé and her grandmother go to the market. Look out for {{du}}, {{de la}} and {{des}}: they mean 'some'."},{"type":"vocab","items":[{"t":"la grand-mère","tr":"la grahn-MAIR","mean":"the grandmother"},{"t":"la place","tr":"la PLASS","mean":"the town square"},{"t":"l'église","tr":"lay-GLEEZ","mean":"the church"},{"t":"beaucoup de monde","tr":"boh-koo duh MOHND","mean":"lots of people"},{"t":"ça sent bon","tr":"sa sahn BOHN","mean":"it smells good"},{"t":"acheter","tr":"ash-TAY","mean":"to buy"},{"t":"le fromage","tr":"luh fro-MAZH","mean":"the cheese"},{"t":"cher / chère","tr":"SHAIR","mean":"expensive"},{"t":"goûter","tr":"goo-TAY","mean":"to taste"},{"t":"ensemble","tr":"ahn-SAHMBL","mean":"together"}],"title":"Words to know"},{"type":"text","text":"Read the story one sentence at a time.","title":"Samedi au marché"},{"type":"sentence","t":"Le samedi, Chloé va au marché avec sa grand-mère.","tr":"luh sam-DEE, klo-AY va oh mar-SHAY ah-vek sa grahn-MAIR.","mean":"On Saturdays, Chloé goes to the market with her grandmother.","words":[{"t":"Le","mean":"the"},{"t":"samedi","mean":"Saturday"},{"t":"Chloé","mean":"Chloé"},{"t":"va","mean":"goes"},{"t":"au","mean":"to the"},{"t":"marché","mean":"market"},{"t":"avec","mean":"with"},{"t":"sa","mean":"her"},{"t":"grand-mère","mean":"grandmother"}],"note":"{{Le samedi}} (with {{le}}) means 'every Saturday'."},{"type":"sentence","t":"Le marché est sur la place, près de l'église.","tr":"luh mar-SHAY eh sewr la PLASS, preh duh lay-GLEEZ.","mean":"The market is on the square, near the church.","words":[{"t":"Le","mean":"the"},{"t":"marché","mean":"market"},{"t":"est","mean":"is"},{"t":"sur","mean":"on"},{"t":"la","mean":"the"},{"t":"place","mean":"square"},{"t":"près","mean":"near"},{"t":"de","mean":"of"},{"t":"l'église","mean":"the church"}]},{"type":"sentence","t":"Il y a beaucoup de monde et ça sent bon.","tr":"eel ya boh-koo duh MOHND ay sa sahn BOHN.","mean":"There are lots of people and it smells good.","words":[{"t":"Il","mean":"it"},{"t":"y","mean":"there"},{"t":"a","mean":"has"},{"t":"beaucoup","mean":"a lot"},{"t":"de","mean":"of"},{"t":"monde","mean":"people (world)"},{"t":"et","mean":"and"},{"t":"ça","mean":"it"},{"t":"sent","mean":"smells"},{"t":"bon","mean":"good"}]},{"type":"sentence","t":"La grand-mère achète des pommes, des carottes et du fromage.","tr":"la grahn-MAIR a-SHET day POM, day ka-ROT ay dew fro-MAZH.","mean":"Grandma buys apples, carrots and cheese.","words":[{"t":"La","mean":"the"},{"t":"grand-mère","mean":"grandmother"},{"t":"achète","mean":"buys"},{"t":"des","mean":"some"},{"t":"pommes","mean":"apples"},{"t":"des","mean":"some"},{"t":"carottes","mean":"carrots"},{"t":"et","mean":"and"},{"t":"du","mean":"some"},{"t":"fromage","mean":"cheese"}]},{"type":"sentence","t":"Chloé veut des fraises, mais elles sont chères.","tr":"klo-AY vuh day FREZ, meh el sohn SHAIR.","mean":"Chloé wants strawberries, but they are expensive.","words":[{"t":"Chloé","mean":"Chloé"},{"t":"veut","mean":"wants"},{"t":"des","mean":"some"},{"t":"fraises","mean":"strawberries"},{"t":"mais","mean":"but"},{"t":"elles","mean":"they"},{"t":"sont","mean":"are"},{"t":"chères","mean":"expensive"}]},{"type":"sentence","t":"Le vendeur sourit et donne une fraise à Chloé.","tr":"luh vahn-DUHR soo-REE ay dun ewn FREZ ah klo-AY.","mean":"The seller smiles and gives Chloé a strawberry.","words":[{"t":"Le","mean":"the"},{"t":"vendeur","mean":"seller"},{"t":"sourit","mean":"smiles"},{"t":"et","mean":"and"},{"t":"donne","mean":"gives"},{"t":"une","mean":"a"},{"t":"fraise","mean":"strawberry"},{"t":"à","mean":"to"},{"t":"Chloé","mean":"Chloé"}]},{"type":"sentence","t":"Chloé goûte la fraise. Elle est délicieuse !","tr":"klo-AY GOOT la FREZ. el eh day-lee-SYUHZ !","mean":"Chloé tastes the strawberry. It's delicious!","words":[{"t":"Chloé","mean":"Chloé"},{"t":"goûte","mean":"tastes"},{"t":"la","mean":"the"},{"t":"fraise","mean":"strawberry"},{"t":"Elle","mean":"it (she)"},{"t":"est","mean":"is"},{"t":"délicieuse","mean":"delicious"}],"note":"{{La fraise}} is feminine, so 'it' is {{elle}} and the adjective is {{délicieuse}}."},{"type":"sentence","t":"Alors la grand-mère achète une barquette de fraises.","tr":"a-LOR la grahn-MAIR a-SHET ewn bar-KET duh FREZ.","mean":"So Grandma buys a punnet of strawberries.","words":[{"t":"Alors","mean":"so"},{"t":"la","mean":"the"},{"t":"grand-mère","mean":"grandmother"},{"t":"achète","mean":"buys"},{"t":"une","mean":"a"},{"t":"barquette","mean":"punnet"},{"t":"de","mean":"of"},{"t":"fraises","mean":"strawberries"}]},{"type":"sentence","t":"À midi, elles mangent ensemble. Et en dessert, des fraises, bien sûr !","tr":"ah mee-DEE, el MAHNZH ahn-SAHMBL. ay ahn deh-SAIR, day FREZ, byan SEWR !","mean":"At noon, they eat together. And for dessert: strawberries, of course!","words":[{"t":"À","mean":"at"},{"t":"midi","mean":"noon"},{"t":"elles","mean":"they"},{"t":"mangent","mean":"eat"},{"t":"ensemble","mean":"together"},{"t":"Et","mean":"and"},{"t":"en","mean":"for"},{"t":"dessert","mean":"dessert"},{"t":"des","mean":"some"},{"t":"fraises","mean":"strawberries"},{"t":"bien","mean":"well"},{"t":"sûr","mean":"sure"}],"note":"{{bien sûr}} = of course."},{"type":"rule","name":"du, de la, des = some","color":"green","desc":"Use these for an amount that isn't counted exactly. In English we often say 'some', or nothing at all.","how":"{{du}} + masculine · {{de la}} + feminine · {{de l'}} + vowel · {{des}} + plural","examples":[{"t":"du fromage","tr":"dew fro-MAZH","hl":"du"},{"t":"de la confiture","tr":"duh la kohn-fee-TEWR","hl":"de la"},{"t":"de l'eau","tr":"duh LOH","hl":"de l'"},{"t":"des pommes","tr":"day POM","hl":"des"}]},{"type":"tip","kind":"culture","text":"Almost every French town has an open-air market on one or more mornings a week. Many people have a favourite stall and chat with the sellers they know."},{"type":"quiz","title":"Did you understand?","items":[{"q":"Who does Chloé go to the market with?","options":["Her mother","Her best friend","Her grandfather","Her grandmother"],"answer":3},{"q":"Where is the market?","options":["In the church","On the square","At the station","Next to the school"],"answer":1},{"q":"Why doesn't Chloé buy strawberries at first?","options":["They are expensive","She doesn't like them","They are not ripe","The stall is closed"],"answer":0},{"q":"Listen. What does Chloé say about the strawberry?","say":"Elle est délicieuse !","options":["It's expensive!","It's delicious!","It's very small!","It's not ripe!"],"answer":1},{"q":"Complete: {{La grand-mère achète ___ fromage.}}","options":["de la","des","un des","du"],"answer":3,"explain":"{{fromage}} is masculine: {{du fromage}}."},{"q":"What do they eat for dessert?","options":["Cheese","Apple tart","Strawberries","Chocolate cake"],"answer":2}]}]},{"id":"u6-story-brussels","icon":"A2","title":"Story 3: A Weekend in Brussels","subtitle":"A trip told in the past tense","minutes":15,"goals":["Read a story in the past tense (passé composé)","Spot verbs with {{avoir}} and {{être}}","Learn a little about Belgium"],"blocks":[{"type":"text","text":"This story is about the past, so it uses the {{passé composé}}: {{j'ai mangé}} (I ate), {{nous sommes entrées}} (we went in). Nadia tells you about her trip to Belgium."},{"type":"vocab","items":[{"t":"le week-end dernier","tr":"luh wee-kend dair-NYAY","mean":"last weekend"},{"t":"je suis allée","tr":"zhuh swee za-LAY","mean":"I went (a woman speaking)"},{"t":"nous avons pris","tr":"noo za-vohn PREE","mean":"we took"},{"t":"le voyage","tr":"luh vwah-YAZH","mean":"the journey"},{"t":"durer","tr":"dew-RAY","mean":"to last"},{"t":"visiter","tr":"vee-zee-TAY","mean":"to visit (a place)"},{"t":"ancien / ancienne","tr":"ahn-SYAN / ahn-SYEN","mean":"old"},{"t":"les moules-frites","tr":"lay mool-FREET","mean":"mussels and fries"},{"t":"une gaufre","tr":"ewn GOHFR","mean":"a waffle"},{"t":"adorer","tr":"a-do-RAY","mean":"to love"}],"title":"Words to know"},{"type":"text","text":"Read the story one sentence at a time.","title":"Un week-end à Bruxelles"},{"type":"sentence","t":"Le week-end dernier, je suis allée à Bruxelles avec mon amie Julie.","tr":"luh wee-kend dair-NYAY, zhuh swee za-LAY ah brew-SEL ah-vek moh na-MEE zhew-LEE.","mean":"Last weekend, I went to Brussels with my friend Julie.","words":[{"t":"Le","mean":"the"},{"t":"week-end","mean":"weekend"},{"t":"dernier","mean":"last"},{"t":"je","mean":"I"},{"t":"suis","mean":"am"},{"t":"allée","mean":"gone"},{"t":"à","mean":"to"},{"t":"Bruxelles","mean":"Brussels"},{"t":"avec","mean":"with"},{"t":"mon","mean":"my"},{"t":"amie","mean":"friend"},{"t":"Julie","mean":"Julie"}],"note":"Verbs of movement like {{aller}} use {{être}}. Nadia is a woman, so she writes {{allée}}."},{"type":"sentence","t":"Nous avons pris le train à Paris.","tr":"noo za-vohn PREE luh TRAN ah pa-REE.","mean":"We took the train in Paris.","words":[{"t":"Nous","mean":"we"},{"t":"avons","mean":"have"},{"t":"pris","mean":"taken"},{"t":"le","mean":"the"},{"t":"train","mean":"train"},{"t":"à","mean":"in"},{"t":"Paris","mean":"Paris"}]},{"type":"sentence","t":"Le voyage a duré une heure et demie.","tr":"luh vwah-YAZH a dew-RAY ew-NUHR ay duh-MEE.","mean":"The journey took an hour and a half.","words":[{"t":"Le","mean":"the"},{"t":"voyage","mean":"journey"},{"t":"a","mean":"has"},{"t":"duré","mean":"lasted"},{"t":"une","mean":"one"},{"t":"heure","mean":"hour"},{"t":"et","mean":"and"},{"t":"demie","mean":"half"}]},{"type":"sentence","t":"Le samedi matin, nous avons visité la Grand-Place.","tr":"luh sam-dee ma-TAN, noo za-vohn vee-zee-TAY la grahn-PLASS.","mean":"On Saturday morning, we visited the Grand-Place.","words":[{"t":"Le","mean":"the"},{"t":"samedi","mean":"Saturday"},{"t":"matin","mean":"morning"},{"t":"nous","mean":"we"},{"t":"avons","mean":"have"},{"t":"visité","mean":"visited"},{"t":"la","mean":"the"},{"t":"Grand-Place","mean":"Grand-Place (main square)"}]},{"type":"sentence","t":"C'est une très belle place, entourée de maisons anciennes.","tr":"seh tewn tray BEL PLASS, ahn-too-RAY duh meh-zohn ahn-SYEN.","mean":"It's a very beautiful square, surrounded by old houses.","words":[{"t":"C'est","mean":"it is"},{"t":"une","mean":"a"},{"t":"très","mean":"very"},{"t":"belle","mean":"beautiful"},{"t":"place","mean":"square"},{"t":"entourée","mean":"surrounded"},{"t":"de","mean":"by"},{"t":"maisons","mean":"houses"},{"t":"anciennes","mean":"old"}]},{"type":"sentence","t":"À midi, nous avons mangé des moules-frites.","tr":"ah mee-DEE, noo za-vohn mahn-ZHAY day mool-FREET.","mean":"At noon, we ate mussels and fries.","words":[{"t":"À","mean":"at"},{"t":"midi","mean":"noon"},{"t":"nous","mean":"we"},{"t":"avons","mean":"have"},{"t":"mangé","mean":"eaten"},{"t":"des","mean":"some"},{"t":"moules-frites","mean":"mussels and fries"}]},{"type":"sentence","t":"L'après-midi, il a plu, alors nous sommes entrées dans un musée.","tr":"la-preh-mee-DEE, eel a PLEW, a-LOR noo som zahn-TRAY dahn zuhn mew-ZAY.","mean":"In the afternoon it rained, so we went into a museum.","words":[{"t":"L'après-midi","mean":"the afternoon"},{"t":"il","mean":"it"},{"t":"a","mean":"has"},{"t":"plu","mean":"rained"},{"t":"alors","mean":"so"},{"t":"nous","mean":"we"},{"t":"sommes","mean":"are"},{"t":"entrées","mean":"entered"},{"t":"dans","mean":"in"},{"t":"un","mean":"a"},{"t":"musée","mean":"museum"}],"note":"Two women, so {{entrées}} ends in {{-es}}."},{"type":"sentence","t":"Le soir, nous avons goûté une gaufre au chocolat.","tr":"luh SWAR, noo za-vohn goo-TAY ewn GOHFR oh sho-ko-LA.","mean":"In the evening, we tried a chocolate waffle.","words":[{"t":"Le","mean":"the"},{"t":"soir","mean":"evening"},{"t":"nous","mean":"we"},{"t":"avons","mean":"have"},{"t":"goûté","mean":"tasted"},{"t":"une","mean":"a"},{"t":"gaufre","mean":"waffle"},{"t":"au","mean":"with the"},{"t":"chocolat","mean":"chocolate"}]},{"type":"sentence","t":"Dimanche, j'ai acheté du chocolat belge pour ma famille.","tr":"dee-MAHNSH, zhay ash-TAY dew sho-ko-LA BELZH poor ma fa-MEE-y.","mean":"On Sunday, I bought Belgian chocolate for my family.","words":[{"t":"Dimanche","mean":"Sunday"},{"t":"j'ai","mean":"I have"},{"t":"acheté","mean":"bought"},{"t":"du","mean":"some"},{"t":"chocolat","mean":"chocolate"},{"t":"belge","mean":"Belgian"},{"t":"pour","mean":"for"},{"t":"ma","mean":"my"},{"t":"famille","mean":"family"}]},{"type":"sentence","t":"J'ai adoré ce week-end, et je veux y retourner bientôt !","tr":"zhay a-do-RAY suh wee-KEND, ay zhuh vuh zee ruh-toor-NAY byan-TOH !","mean":"I loved this weekend, and I want to go back soon!","words":[{"t":"J'ai","mean":"I have"},{"t":"adoré","mean":"loved"},{"t":"ce","mean":"this"},{"t":"week-end","mean":"weekend"},{"t":"et","mean":"and"},{"t":"je","mean":"I"},{"t":"veux","mean":"want"},{"t":"y","mean":"there"},{"t":"retourner","mean":"to go back"},{"t":"bientôt","mean":"soon"}]},{"type":"table","head":["French","Meaning","Helper verb"],"rows":[["{{nous avons pris}}","we took","avoir"],["{{il a plu}}","it rained","avoir"],["{{j'ai acheté}}","I bought","avoir"],["{{je suis allée}}","I went","être"],["{{nous sommes entrées}}","we went in","être"]],"title":"The passé composé in the story"},{"type":"tip","kind":"culture","text":"French is one of Belgium's three official languages, with Dutch and German. Brussels is officially bilingual (French and Dutch). Belgians say {{septante}} for 70 and {{nonante}} for 90."},{"type":"quiz","title":"Did you understand?","items":[{"q":"Who did Nadia travel with?","options":["Her sister","Julie","Her parents","Nobody: she went alone"],"answer":1},{"q":"How did they travel to Brussels?","options":["By plane","By car","By train","By bus"],"answer":2},{"q":"What did they do when it rained?","options":["They went back to the hotel","They went into a museum","They bought umbrellas","They took the train home"],"answer":1},{"q":"Listen. What did they eat at lunchtime?","say":"À midi, nous avons mangé des moules-frites.","options":["Mussels and fries","A chocolate waffle","Fish and salad","Cheese and bread"],"answer":0},{"q":"Why is it {{je suis allée}} with an extra {{e}}?","options":["Because it's plural","Because Nadia is a woman","Because it's a question","Because Brussels is feminine"],"answer":1},{"q":"In Belgium, {{nonante}} means…","options":["90","70","80","19"],"answer":0},{"q":"What does Nadia want to do?","options":["Never travel again","Move to Paris next year","Go back soon","Learn Dutch first"],"answer":2}]}]},{"id":"u6-songs","icon":"♪","title":"Songs & Rhymes","subtitle":"Traditional French songs to sing along with","minutes":12,"goals":["Sing three traditional French songs","Understand what the words mean","Practise rhythm and rhyme"],"blocks":[{"type":"text","text":"Songs are a great way to remember French sounds. These traditional songs are centuries old, and French children still sing them today. Read the meaning, then sing along!"},{"type":"examples","items":[{"t":"Frère Jacques, frère Jacques,","tr":"frair ZHAHK, frair ZHAHK","mean":"Brother Jacques, Brother Jacques,"},{"t":"Dormez-vous ? Dormez-vous ?","tr":"dor-may-VOO ? dor-may-VOO ?","mean":"Are you sleeping? Are you sleeping?"},{"t":"Sonnez les matines, sonnez les matines,","tr":"so-nay lay ma-TEEN, so-nay lay ma-TEEN","mean":"Ring the morning bells, ring the morning bells,"},{"t":"Ding, dang, dong. Ding, dang, dong.","tr":"deeng, dahng, dohng","mean":"Ding, dang, dong."}],"title":"Frère Jacques"},{"type":"tip","kind":"culture","text":"{{Les matines}} are very early morning prayers in a monastery. Brother Jacques is a monk who has overslept and should be ringing the bell! The English version, 'Are you sleeping, Brother John?', tells the story a little differently."},{"type":"text","text":"{{Dormez-vous ?}} is a question made by swapping the verb and the subject: {{Vous dormez}} (you sleep) becomes {{Dormez-vous ?}} (do you sleep?)."},{"type":"sentence","t":"Sonnez les matines !","tr":"so-nay lay ma-TEEN !","mean":"Ring the morning bells!","words":[{"t":"Sonnez","mean":"ring"},{"t":"les","mean":"the"},{"t":"matines","mean":"morning prayers"}]},{"type":"examples","items":[{"t":"Au clair de la lune,","tr":"oh klair duh la LEWN","mean":"By the light of the moon,"},{"t":"Mon ami Pierrot,","tr":"moh na-mee pyeh-ROH","mean":"My friend Pierrot,"},{"t":"Prête-moi ta plume","tr":"pret-mwah ta PLEWM","mean":"Lend me your quill (pen)"},{"t":"Pour écrire un mot.","tr":"poor ay-kree ruhn MOH","mean":"To write a word."},{"t":"Ma chandelle est morte,","tr":"ma shahn-del eh MORT","mean":"My candle has gone out,"},{"t":"Je n'ai plus de feu.","tr":"zhuh nay plew duh FUH","mean":"I have no more fire."},{"t":"Ouvre-moi ta porte","tr":"oo-vruh-mwah ta PORT","mean":"Open your door to me"},{"t":"Pour l'amour de Dieu.","tr":"poor la-moor duh DYUH","mean":"For the love of God."}],"title":"Au clair de la lune (first verse)"},{"type":"tip","kind":"culture","text":"Pierrot is a classic sad clown from old French theatre. In the 1700s people wrote with a feather quill ({{une plume}}) by candlelight."},{"type":"sentence","t":"Prête-moi ta plume.","tr":"pret-mwah ta PLEWM.","mean":"Lend me your pen.","words":[{"t":"Prête-moi","mean":"lend me"},{"t":"ta","mean":"your"},{"t":"plume","mean":"quill / pen"}],"note":"{{Prête-moi}} is a friendly command with {{tu}}. Today you might say {{Prête-moi ton stylo}} (lend me your pen)."},{"type":"examples","items":[{"t":"Un, deux, trois, nous irons au bois,","tr":"uhn, duh, TRWAH, noo zee-rohn oh BWAH","mean":"One, two, three, we'll go to the woods,"},{"t":"Quatre, cinq, six, cueillir des cerises,","tr":"katr, sank, SEESS, kuh-yeer day suh-REEZ","mean":"Four, five, six, to pick cherries,"},{"t":"Sept, huit, neuf, dans mon panier neuf,","tr":"set, weet, NUHF, dahn mohn pa-nyay NUHF","mean":"Seven, eight, nine, in my new basket,"},{"t":"Dix, onze, douze, elles seront toutes rouges.","tr":"deess, ohnz, DOOZ, el suh-rohn toot ROOZH","mean":"Ten, eleven, twelve, they will all be red."}],"title":"Un, deux, trois, nous irons au bois"},{"type":"tip","kind":"memory","text":"Listen for the rhymes: {{trois / bois}}, {{six / cerises}}, {{neuf / neuf}}, {{douze / rouges}}. {{Neuf}} means both 'nine' and 'new', and the song plays with that!"},{"type":"practice","text":"Sing or read the songs aloud. Tap any word to hear it.","lines":["Frère Jacques, frère Jacques, dormez-vous ?","Sonnez les matines, ding, dang, dong.","Au clair de la lune, mon ami Pierrot,","Prête-moi ta plume pour écrire un mot.","Un, deux, trois, nous irons au bois,","Quatre, cinq, six, cueillir des cerises."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"In 'Frère Jacques', what does {{Dormez-vous ?}} mean?","options":["Are you dreaming?","Are you coming?","Where are you going?","Are you sleeping?"],"answer":3},{"q":"What does the singer of 'Au clair de la lune' want to borrow?","options":["A pen","A candle","A door key","Some bread"],"answer":0,"explain":"{{Prête-moi ta plume}} = Lend me your quill (pen)."},{"q":"Why does he need help?","options":["His candle has gone out","He is hungry and tired","He has lost his way home","His door is broken"],"answer":0},{"q":"Listen. What will they pick?","say":"Quatre, cinq, six, cueillir des cerises.","options":["Apples","Cherries","Strawberries","Flowers"],"answer":1,"explain":"{{des cerises}} = cherries."},{"q":"{{Neuf}} can mean…","options":["nine or new","nine or nineteen","new or now","nine only"],"answer":0},{"q":"{{Les matines}} are…","options":["morning newspapers","church towers","breakfast foods","morning prayers"],"answer":3}]}]},{"id":"u6-expressions","icon":"«»","title":"Expressions & Proverbs","subtitle":"Sound natural with everyday phrases, idioms and proverbs","minutes":12,"goals":["Use everyday expressions at the right moment","Understand colourful French idioms","Learn well-known proverbs"],"blocks":[{"type":"text","text":"Every language has little phrases that make you sound natural. Here are everyday expressions, colourful idioms and some famous proverbs."},{"type":"vocab","items":[{"t":"Bon courage !","tr":"bohn koo-RAZH !","mean":"Good luck! / Hang in there!"},{"t":"Bon appétit !","tr":"bo na-pay-TEE !","mean":"Enjoy your meal!"},{"t":"Santé !","tr":"sahn-TAY !","mean":"Cheers! (lit. health)"},{"t":"À tes souhaits !","tr":"ah tay SWEH !","mean":"Bless you! (after a sneeze)"},{"t":"Pas de souci.","tr":"pahd soo-SEE.","mean":"No worries."},{"t":"Tant pis !","tr":"tahn PEE !","mean":"Oh well! / Too bad!"},{"t":"Tant mieux !","tr":"tahn MYUH !","mean":"Good! / So much the better!"},{"t":"Ce n'est pas grave.","tr":"suh neh pa GRAV.","mean":"It doesn't matter. / No big deal."},{"t":"Oh là là !","tr":"oh la LA !","mean":"Oh dear! / Wow!"},{"t":"Bof.","tr":"BOF.","mean":"Meh. (not impressed)"},{"t":"J'ai la flemme.","tr":"zhay la FLEM.","mean":"I can't be bothered. (informal)"}],"title":"Everyday expressions"},{"type":"tip","kind":"tip","text":"In everyday speech, people often drop the {{ne}}: {{C'est pas grave}}, {{Je sais pas}}. That's normal when speaking, but keep the {{ne}} when you write."},{"type":"table","head":["French","Word for word","Real meaning"],"rows":[["{{Il pleut des cordes.}}","It's raining ropes.","It's pouring."],["{{Ça coûte les yeux de la tête.}}","It costs the eyes of the head.","It costs an arm and a leg."],["{{poser un lapin}}","to put down a rabbit","to stand someone up"],["{{avoir le cafard}}","to have the cockroach","to feel down"],["{{avoir un coup de foudre}}","to have a lightning strike","to fall in love at first sight"],["{{Ce n'est pas la mer à boire.}}","It's not the sea to drink.","It's not that hard."],["{{quand les poules auront des dents}}","when hens have teeth","when pigs fly (never)"]],"title":"Colourful idioms"},{"type":"sentence","t":"Il pleut des cordes.","tr":"eel pluh day KORD.","mean":"It's pouring (lit. it's raining ropes).","words":[{"t":"Il","mean":"it"},{"t":"pleut","mean":"rains"},{"t":"des","mean":"some"},{"t":"cordes","mean":"ropes"}]},{"type":"examples","items":[{"t":"Petit à petit, l'oiseau fait son nid.","tr":"puh-TEE ta puh-TEE, lwah-ZOH feh sohn NEE.","mean":"Little by little, the bird builds its nest.","note":"Big goals are reached in small steps, like learning French!"},{"t":"Mieux vaut tard que jamais.","tr":"myuh voh TAR kuh zha-MEH.","mean":"Better late than never."},{"t":"Après la pluie, le beau temps.","tr":"a-preh la PLWEE, luh boh TAHN.","mean":"After the rain, good weather.","note":"Good times follow bad times."},{"t":"L'habit ne fait pas le moine.","tr":"la-BEE nuh feh pa luh MWAN.","mean":"The robe doesn't make the monk.","note":"Don't judge by appearances."},{"t":"Qui se ressemble s'assemble.","tr":"kee suh ruh-SAHMBL sa-SAHMBL.","mean":"Those who are alike come together.","note":"Birds of a feather flock together."},{"t":"Vouloir, c'est pouvoir.","tr":"voo-LWAR, say poo-VWAR.","mean":"To want is to be able.","note":"Where there's a will, there's a way."}],"title":"Proverbs"},{"type":"sentence","t":"Petit à petit, l'oiseau fait son nid.","tr":"puh-TEE ta puh-TEE, lwah-ZOH feh sohn NEE.","mean":"Little by little, the bird builds its nest.","words":[{"t":"Petit","mean":"little"},{"t":"à","mean":"by"},{"t":"petit","mean":"little"},{"t":"l'oiseau","mean":"the bird"},{"t":"fait","mean":"makes"},{"t":"son","mean":"its"},{"t":"nid","mean":"nest"}]},{"type":"tip","kind":"culture","text":"Before eating, French people say {{Bon appétit !}} When drinking together, they say {{Santé !}} and look each other in the eye as they clink glasses."},{"type":"practice","text":"Read aloud. Which proverb is your favourite?","lines":["Bon courage pour ton examen !","Tant pis, ce n'est pas grave.","Il pleut des cordes aujourd'hui !","Ce n'est pas la mer à boire.","Petit à petit, l'oiseau fait son nid.","Mieux vaut tard que jamais."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Someone sneezes. You say…","options":["Bon appétit à tous !","Santé !","Tant mieux !","À tes souhaits !"],"answer":3},{"q":"Your friend has an exam tomorrow. You say…","options":["Bon appétit !","Tant pis !","Bon courage !","Oh là là, bof !"],"answer":2},{"q":"Listen. What's the weather like?","say":"Il pleut des cordes.","options":["It's a little cloudy.","It's pouring.","Someone needs a rope.","It's snowing hard."],"answer":1},{"q":"{{Il m'a posé un lapin}} means…","options":["He stood me up.","He gave me a rabbit.","He cooked me dinner.","He told me a joke."],"answer":0},{"q":"Which proverb means 'Better late than never'?","options":["Petit à petit, l'oiseau fait son nid.","Mieux vaut tard que jamais.","Vouloir, c'est pouvoir.","Après la pluie, le beau temps."],"answer":1},{"q":"{{Ça coûte les yeux de la tête}} describes something…","options":["very expensive","very beautiful","bad for your eyes","very easy to find"],"answer":0},{"q":"When you clink glasses, you say…","options":["Bon courage !","À tes souhaits !","Pas de souci !","Santé !"],"answer":3}]}]},{"id":"u6-manners","icon":"Tu","title":"Culture: La Bise, Tu & Vous","subtitle":"Greetings, cheek kisses and polite forms","minutes":12,"goals":["Understand {{la bise}} and when to shake hands","Choose between {{tu}} and {{vous}}","Use everyday politeness words"],"blocks":[{"type":"text","text":"Knowing a few social rules helps you feel at ease in France. Let's look at greetings, the famous {{bise}}, and when to say {{tu}} or {{vous}}."},{"type":"text","text":"{{La bise}} is a light touch of cheeks with a small kissing sound. Friends and family greet each other this way, and so do many colleagues who know each other well.","title":"La bise"},{"type":"tip","kind":"culture","text":"The number of kisses depends on the region. Two is the most common (for example in Paris), but some areas do one, three or even four! When in doubt, follow the other person's lead."},{"type":"tip","kind":"tip","text":"In business, or with people you don't know, a handshake ({{une poignée de main}}) is normal. Some people now prefer a simple wave or nod, and that's fine too."},{"type":"table","head":["Use tu with…","Use vous with…"],"rows":[["friends and family","people you don't know"],["children","older people"],["people your age (especially young people)","shop staff, waiters, officials"],["pets!","your boss or teacher (usually)"]],"title":"Tu or vous?"},{"type":"text","text":"{{Vous}} is also simply the plural 'you'. Use it whenever you talk to more than one person, even friends."},{"type":"examples","items":[{"t":"Tu veux un café ?","tr":"tew vuh uhn ka-FAY ?","mean":"Do you want a coffee? (friendly)","hl":"Tu"},{"t":"Vous voulez un café ?","tr":"voo voo-LAY uhn ka-FAY ?","mean":"Would you like a coffee? (polite)","hl":"Vous"},{"t":"Comment tu t'appelles ?","tr":"ko-mahn tew ta-PEL ?","mean":"What's your name? (friendly)","hl":"tu"},{"t":"Comment vous appelez-vous ?","tr":"ko-mahn voo za-play-VOO ?","mean":"What's your name? (polite)","hl":"vous"}],"title":"Same question, two styles"},{"type":"sentence","t":"On peut se tutoyer ?","tr":"ohn puh suh tew-twah-YAY ?","mean":"Shall we say 'tu' to each other?","words":[{"t":"On","mean":"we"},{"t":"peut","mean":"can"},{"t":"se","mean":"each other"},{"t":"tutoyer","mean":"say tu to"}],"note":"{{tutoyer}} = to say {{tu}}; {{vouvoyer}} = to say {{vous}}. Usually the older or more senior person suggests the switch."},{"type":"dialogue","lines":[{"who":"Mme Blanc","t":"Vous voulez encore du thé, Julien ?","tr":"voo voo-LAY ahn-kor dew TAY, zhew-LYAN ?","mean":"Would you like more tea, Julien?"},{"who":"Julien","t":"Oui, merci beaucoup, madame.","tr":"WEE, mair-SEE boh-KOO, ma-DAM.","mean":"Yes, thank you very much, madam."},{"who":"Mme Blanc","t":"Appelez-moi Claire. Et on peut se tutoyer, non ?","tr":"a-play-MWAH KLAIR. ay ohn puh suh tew-twah-YAY, NOHN ?","mean":"Call me Claire. And we can say 'tu', can't we?"},{"who":"Julien","t":"Avec plaisir ! Alors… tu as un jardin magnifique, Claire.","tr":"ah-vek pleh-ZEER ! a-LOR… tew a uhn zhar-DAN ma-nyee-FEEK, KLAIR.","mean":"With pleasure! So… you have a wonderful garden, Claire."},{"who":"Mme Blanc","t":"Merci ! Tu veux le voir ?","tr":"mair-SEE ! tew vuh luh VWAR ?","mean":"Thanks! Do you want to see it?"},{"who":"Julien","t":"Oui, je veux bien !","tr":"WEE, zhuh vuh BYAN !","mean":"Yes, I'd love to!"}],"title":"Switching to tu"},{"type":"tip","kind":"culture","text":"Politeness words matter a lot: {{Bonjour}} when you arrive, {{Merci}}, {{S'il vous plaît}}, and {{Au revoir}} when you leave, in shops, on the bus, even in a lift. Adding {{Monsieur}} or {{Madame}} makes it extra polite."},{"type":"practice","text":"Read each pair aloud: first friendly, then polite.","lines":["Tu veux un café ?","Vous voulez un café ?","Comment tu t'appelles ?","Comment vous appelez-vous ?","Tu es d'où ?","Vous êtes d'où ?"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"You meet your new boss. You should probably use…","options":["tu","either: it doesn't matter","toi","vous"],"answer":3},{"q":"You talk to two of your friends together. You use…","options":["vous","tu","nous","on"],"answer":0,"explain":"{{Vous}} is always used for more than one person."},{"q":"What is {{la bise}}?","options":["A firm two-handed handshake","A cheek-kiss greeting","A small bow","A kind of hug"],"answer":1},{"q":"How many kisses is most common in Paris?","options":["One","Three","Two","Four"],"answer":2},{"q":"Listen. What is the person suggesting?","say":"On peut se tutoyer ?","options":["Meeting tomorrow","Speaking more slowly","Saying 'tu'","Having a drink"],"answer":2},{"q":"Which question uses the polite {{vous}} form?","options":["Tu veux un café ?","Tu prends un café, toi ?","Un café, ça te dit ?","Vous voulez un café ?"],"answer":3}]}]},{"id":"u6-world","icon":"Fr","title":"Culture: Meals & the French-Speaking World","subtitle":"How the French eat, and where French is spoken","minutes":14,"goals":["Know French mealtimes and courses","Learn table manners","Discover French-speaking countries"],"blocks":[{"type":"text","text":"Food and language bring people together. Discover how French meals work, then travel around the world of French speakers."},{"type":"table","head":["Meal","When","What's typical"],"rows":[["{{le petit-déjeuner}}","7:00–9:00","bread with butter and jam, coffee, tea or hot chocolate; croissants at the weekend"],["{{le déjeuner}}","12:00–14:00","often a hot meal; many schools and workplaces have a canteen"],["{{le goûter}}","about 16:30","an after-school snack for children: bread and chocolate, fruit or biscuits"],["{{le dîner}}","19:30–21:00","the evening meal, often with the family"]],"title":"A day of French meals"},{"type":"tip","kind":"culture","text":"A full meal can have several courses: {{entrée}} (starter), {{plat}} (main course), {{fromage}} (cheese) and {{dessert}}. Cheese comes before dessert!"},{"type":"tip","kind":"culture","text":"At the table, bread is often placed straight on the tablecloth next to your plate. Keep your hands (wrists) on the table, not in your lap, and wait for {{Bon appétit !}} before you start."},{"type":"tip","kind":"warn","text":"In Québec, Belgium and Switzerland, meal names are different: {{le déjeuner}} = breakfast, {{le dîner}} = lunch and {{le souper}} = dinner."},{"type":"text","text":"About 320 million people speak French, on every continent. It is an official language in around 29 countries, and one of the two working languages of the United Nations Secretariat, with English.","title":"French around the world"},{"type":"table","head":["Country","Capital","Did you know?"],"rows":[["France","Paris","About 68 million people live in France."],["Belgium","Brussels","French, Dutch and German are all official languages."],["Switzerland","Bern","French is one of four national languages."],["Canada","Ottawa","Québec is the main French-speaking province."],["Senegal","Dakar","French is the official language; Wolof is spoken by most people."],["Côte d'Ivoire","Yamoussoukro","Its biggest city, Abidjan, is a major French-speaking hub."],["DR Congo","Kinshasa","Kinshasa is one of the biggest French-speaking cities in the world."],["Haiti","Port-au-Prince","French and Haitian Creole are both official."],["Madagascar","Antananarivo","Malagasy and French are both official."]],"title":"Where French is spoken"},{"type":"vocab","items":[{"t":"magasiner","tr":"ma-ga-zee-NAY","mean":"to go shopping (Québec)"},{"t":"le char","tr":"luh SHAR","mean":"the car (Québec, informal)"},{"t":"la fin de semaine","tr":"la fan duh suh-MEN","mean":"the weekend (Québec)"},{"t":"le courriel","tr":"luh koo-RYEL","mean":"email (Québec, and the official word in France too)"},{"t":"septante","tr":"sep-TAHNT","mean":"seventy (Belgium, Switzerland)"},{"t":"nonante","tr":"no-NAHNT","mean":"ninety (Belgium, Switzerland)"},{"t":"huitante","tr":"wee-TAHNT","mean":"eighty (parts of Switzerland)"}],"title":"Words from around the French-speaking world"},{"type":"sentence","t":"Le français est parlé sur cinq continents.","tr":"luh frahn-SEH eh par-LAY sewr sank kohn-tee-NAHN.","mean":"French is spoken on five continents.","words":[{"t":"Le","mean":"the"},{"t":"français","mean":"French (language)"},{"t":"est","mean":"is"},{"t":"parlé","mean":"spoken"},{"t":"sur","mean":"on"},{"t":"cinq","mean":"five"},{"t":"continents","mean":"continents"}]},{"type":"practice","text":"Read aloud. Then say which French-speaking country you'd like to visit.","lines":["Le petit-déjeuner, le déjeuner, le goûter, le dîner.","Le fromage, puis le dessert.","Bon appétit !","Je voudrais visiter le Québec.","Septante, huitante, nonante."]},{"type":"quiz","title":"Quick quiz","items":[{"q":"What is {{le goûter}}?","options":["A big Sunday lunch","A late dinner","An afternoon snack","A breakfast drink"],"answer":2},{"q":"In a French meal, what is the usual order?","options":["Cheese, then dessert","Dessert, then cheese","Cheese with the starter","Dessert with the main course"],"answer":0},{"q":"In Québec, {{le dîner}} is…","options":["dinner","breakfast","lunch","a snack"],"answer":2},{"q":"About how many people speak French in the world?","options":["About 30 million","About 320 million","About 1.5 billion","About 80 million"],"answer":1},{"q":"What is the capital of Senegal?","options":["Abidjan","Kinshasa","Dakar","Bamako"],"answer":2},{"q":"Listen. In Belgium, this number is…","say":"septante","options":["17","70","60","700"],"answer":1},{"q":"Where do you keep your hands during a French meal?","options":["On the table","In your lap","Behind your back","On your knees"],"answer":0}]}]},{"id":"u6-review","icon":"Fin","title":"Final Review Lab","subtitle":"Mix everything: talk, read, listen and remember","minutes":18,"goals":["Use everyday conversation phrases together","Read, listen and write in French","Check everything you have learned"],"blocks":[{"type":"text","text":"Congratulations, you've reached the last lesson! This lab mixes everything: conversation, reading, listening and culture. Take your time and enjoy it."},{"type":"dialogue","lines":[{"who":"Lucie","t":"Salut Ben ! Tu es libre cet après-midi ?","tr":"sa-LEW BEN ! tew eh LEEBR seh ta-preh-mee-DEE ?","mean":"Hi Ben! Are you free this afternoon?"},{"who":"Ben","t":"Oui ! On se retrouve où ?","tr":"WEE ! ohn suh ruh-troov OO ?","mean":"Yes! Where shall we meet?"},{"who":"Lucie","t":"Au café en face de la gare, à quinze heures ?","tr":"oh ka-FAY ahn FASS duh la GAR, ah kan ZUHR ?","mean":"At the café opposite the station, at 3 pm?"},{"who":"Ben","t":"Ça marche. Mais où est la gare ?","tr":"sa MARSH. meh oo eh la GAR ?","mean":"Deal. But where is the station?"},{"who":"Lucie","t":"C'est facile : tout droit, puis la première rue à gauche.","tr":"say fa-SEEL : too DRWAH, pwee la pruh-myair REW ah GOHSH.","mean":"It's easy: straight on, then the first street on the left."},{"who":"Ben","t":"Parfait. Il fait beau, on prend une table en terrasse ?","tr":"par-FAY. eel feh BOH, ohn prahn ewn TABL ahn teh-RASS ?","mean":"Perfect. The weather's nice, shall we sit outside on the terrace?"},{"who":"Lucie","t":"Bonne idée ! À tout à l'heure !","tr":"bun ee-DAY ! ah too ta LUHR !","mean":"Good idea! See you later!"}],"title":"Plans in town"},{"type":"text","text":"Tap each word, then say the whole sentence.","title":"Build the sentence"},{"type":"sentence","t":"Je voudrais un aller-retour pour Paris.","tr":"zhuh voo-DRAY uhn na-lay ruh-TOOR poor pa-REE.","mean":"I'd like a return ticket to Paris.","words":[{"t":"Je","mean":"I"},{"t":"voudrais","mean":"would like"},{"t":"un","mean":"a"},{"t":"aller-retour","mean":"return ticket"},{"t":"pour","mean":"for / to"},{"t":"Paris","mean":"Paris"}]},{"type":"sentence","t":"Il y a du vent aujourd'hui.","tr":"eel ya dew VAHN oh-zhoor-DWEE.","mean":"It's windy today.","words":[{"t":"Il","mean":"it"},{"t":"y","mean":"there"},{"t":"a","mean":"has"},{"t":"du","mean":"some"},{"t":"vent","mean":"wind"},{"t":"aujourd'hui","mean":"today"}]},{"type":"sentence","t":"Nous avons mangé une gaufre au chocolat.","tr":"noo za-vohn mahn-ZHAY ewn GOHFR oh sho-ko-LA.","mean":"We ate a chocolate waffle.","words":[{"t":"Nous","mean":"we"},{"t":"avons","mean":"have"},{"t":"mangé","mean":"eaten"},{"t":"une","mean":"a"},{"t":"gaufre","mean":"waffle"},{"t":"au","mean":"with the"},{"t":"chocolat","mean":"chocolate"}]},{"type":"sentence","t":"J'ai mal au ventre depuis hier.","tr":"zhay mal oh VAHNTR duh-pwee YAIR.","mean":"I've had a stomach ache since yesterday.","words":[{"t":"J'ai","mean":"I have"},{"t":"mal","mean":"pain"},{"t":"au","mean":"at the"},{"t":"ventre","mean":"stomach"},{"t":"depuis","mean":"since"},{"t":"hier","mean":"yesterday"}],"note":"French uses the present tense with {{depuis}}: 'I have pain since yesterday'."},{"type":"dictation","items":[{"t":"Où est la pharmacie ?","tr":"oo eh la far-ma-SEE ?","mean":"Where is the pharmacy?"},{"t":"L'addition, s'il vous plaît.","tr":"la-dee-SYOHN, seel voo PLAY.","mean":"The bill, please."},{"t":"Il fait froid ce matin.","tr":"eel feh FRWAH suh ma-TAN.","mean":"It's cold this morning."},{"t":"Tu es libre samedi ?","tr":"tew eh leebr sam-DEE ?","mean":"Are you free on Saturday?"},{"t":"Petit à petit, l'oiseau fait son nid.","tr":"puh-TEE ta puh-TEE, lwah-ZOH feh sohn NEE.","mean":"Little by little, the bird builds its nest."}],"title":"Listen and write"},{"type":"quiz","title":"Final quiz","items":[{"q":"Listen. Where are you most likely to hear this?","say":"Je voudrais un thé, s'il vous plaît.","options":["At the doctor's","At the train station","On the phone to a friend","In a café"],"answer":3},{"q":"You arrive at a hotel. You say…","options":["J'ai une réservation.","J'ai une ordonnance du médecin.","J'ai mal à la tête.","Je regarde, merci."],"answer":0},{"q":"Which one means 'straight on'?","options":["à droite","tout droit","à gauche","au carrefour"],"answer":1},{"q":"Which is correct for 'I have a sore throat'?","options":["Je suis mal à la gorge.","J'ai mal au gorge.","J'ai la gorge malade aujourd'hui.","J'ai mal à la gorge."],"answer":3},{"q":"{{Bof}} shows that you are…","options":["not impressed","very excited about it","hungry","late"],"answer":0},{"q":"Listen. Which track?","say":"Le train part de la voie trois.","options":["Track 13","Track 2","Platform 30","Track 3"],"answer":3},{"q":"In Story 3, where did Nadia go?","options":["Lyon","Brussels","Geneva","Montréal"],"answer":1},{"q":"In France, which comes after the main course?","options":["Cheese","The starter","The aperitif","The soup"],"answer":0}]},{"type":"selfcheck","title":"Can you…?","items":["Order food and drink and ask for the bill","Ask for directions and understand the answer","Buy a train ticket and find your track","Check in at a hotel and report a problem","Say what hurts at the doctor's","Make an appointment on the phone","Invite a friend and accept or refuse","Chat about the weather","Read a short story in French","Choose between tu and vous"]},{"type":"tip","kind":"fun","text":"Félicitations ! Keep going: listen to French songs, watch films with subtitles, and talk with French speakers whenever you can. {{Petit à petit, l'oiseau fait son nid.}}"},{"type":"practice","text":"Your final reading: say each line with confidence!","lines":["Bonjour ! Je voudrais un café, s'il vous plaît.","Excusez-moi, où est la gare ?","Un aller-retour pour Lyon, s'il vous plaît.","Il fait beau aujourd'hui, non ?","Tu es libre ce soir ? On va au cinéma ?","Merci pour tout, et à bientôt !"]}]}]});
